import type { CourseLesson } from "./course";
import { topicExtensions } from "./course-extensions";
import { languageExtensions } from "./language-extensions";
import { integrationsprojekte } from "./integrationsprojekte";

type Example = { title: string; code: string; note: string; language?: string; walkthrough?: string[] };
export type LessonBlueprint = Pick<CourseLesson, "id" | "title" | "objective" | "duration" | "language" | "explanation" | "starterCode" | "task" | "successPattern" | "practice" | "knowledgeCheck"> & {
  module: string;
  examples: Example[];
  languageCourse?: CourseLesson["languageCourse"];
  takeaway?: string;
  projectSteps?: string[];
  acceptanceCriteria?: string[];
  resultPreview?: { title: string; summary: string; checks: string[] };
  resources?: { label: string; url: string }[];
};

function exampleLanguage(title: string): string | undefined {
  if (/Vite:|Cargo und Clippy/i.test(title)) return "bash";
  if (/CMake:/i.test(title)) return "cmake";
  if (/Make:/i.test(title)) return "makefile";
  if (/OpenAPI:|Semgrep:|CI:/i.test(title)) return "yaml";
  if (/SQLAlchemy:/i.test(title)) return "python";
  if (/Playwright:/i.test(title)) return "typescript";
  if (/React:|WCAG:/i.test(title)) return /WCAG:/i.test(title) ? "html" : "jsx";
  if (/Godot:/i.test(title)) return "gdscript";
  if (/ASVS:|ZAP:/i.test(title)) return "checkliste";
  if (/Pull Request:/i.test(title)) return "text";
  return undefined;
}
const example = (title: string, code: string, note: string, language?: string): Example => ({ title, code, note, language: language ?? exampleLanguage(title) });
const intro = (id: string, title: string, language: string, explanation: string, examples: Example[], question: string, correct: string, wrongA: string, wrongB: string): LessonBlueprint => ({
  id, title, language, module: "01 · Verstehen", duration: 10, practice: false,
  objective: `Du kannst in eigenen Worten erklären, was ${title.replace(/^Was ist /, "")} ist und wofür man es nutzt.`,
  explanation, examples, starterCode: "", task: question, successPattern: /(?!) /,
  knowledgeCheck: { question, options: [correct, wrongA, wrongB], correctIndex: 0, explanation: correct },
  takeaway: "Erst den Zweck verstehen. Syntax und Werkzeuge kommen in den nächsten Lektionen.",
});
const lesson = (id: string, module: string, title: string, language: string, objective: string, explanation: string, examples: Example[], starterCode: string, task: string, marker: string, takeaway?: string, projectSteps?: string[], acceptanceCriteria?: string[], resultPreview?: LessonBlueprint["resultPreview"]): LessonBlueprint => ({
  id, module, title, language, objective, explanation, examples, starterCode, task, duration: id === "capstone" || id === "ai-capstone-pipeline" ? 60 : id === "problem-solving" ? 22 : 28,
  successPattern: new RegExp(marker, "i"), practice: true, takeaway, projectSteps, acceptanceCriteria, resultPreview,
});

const javascript: LessonBlueprint[] = [
  intro("orientation", "Was ist JavaScript?", "javascript", "JavaScript ist eine Programmiersprache: Du beschreibst damit genaue Schritte, die eine Laufzeit ausführt. Im Browser reagiert JavaScript zum Beispiel auf Klicks und Formulare. Mit Node.js kann dieselbe Sprache auch Serverprogramme und Werkzeuge betreiben. Ein Browser, Node.js und die JavaScript-Sprache sind drei verschiedene Dinge.", [example("Eine Anweisung", "console.log(2 + 3);", "Die Laufzeit berechnet den Ausdruck und zeigt 5 an."), example("Reaktion auf eine Eingabe", "Klick → Ereignis → Funktion → sichtbare Rückmeldung", "Später lernst du, solche Ereignisse im Browser mit JavaScript zu behandeln.")], "Welche Aussage stimmt?", "JavaScript beschreibt Schritte; Browser oder Node.js führen sie in ihrer Laufzeit aus.", "JavaScript ist eine Gestaltungssprache, die Farben und Abstände festlegt.", "JavaScript läuft ausschließlich auf einer einzigen Webseite."),
  lesson("run", "02 · Erste Schritte", "Anweisungen und Ausgabe", "javascript", "Du führst Anweisungen aus und kannst Ergebnisse sichtbar machen.", "Eine Anweisung ist ein einzelner Arbeitsschritt. `console.log(...)` schreibt einen Wert in die Konsole. JavaScript liest Anweisungen der Reihe nach; ein Ausdruck wie `2 + 3` wird vor der Ausgabe berechnet.", [example("Text ausgeben", "console.log('Hallo');", "Text steht zwischen Anführungszeichen."), example("Einen Ausdruck ausgeben", "console.log(2 + 3);", "Die Ausgabe ist die Zahl 5, nicht der Text '2 + 3'.")], "// Gib deinen Namen aus\n", "Gib einen kurzen Begrüßungstext und das Ergebnis einer Addition mit console.log aus.", "console\\s*\\.\\s*log\\s*\\("),
  lesson("values", "02 · Erste Schritte", "Werte und Variablen", "javascript", "Du benennst Werte und unterscheidest const von let.", "Eine Variable verbindet einen Namen mit einem Wert. `const` verhindert eine erneute Zuweisung an diesen Namen; das Objekt selbst kann trotzdem veränderbar sein. `let` passt, wenn du den Namen später neu belegen musst. Nutze sprechende Namen wie `totalPrice` statt `x`.", [example("Ein fester Name", "const learnerName = 'Mina';", "Der Name learnerName verweist auf den Text Mina."), example("Ein veränderlicher Punktestand", "let score = 0;\nscore = score + 1;", "let erlaubt die spätere Zuweisung eines neuen Werts.")], "const learnerName = 'Mina';\n", "Lege eine const-Variable für ein Lernziel an und gib Name und Lernziel aus.", "\\bconst\\s+\\w+\\s*=.*console\\s*\\.\\s*log"),
  lesson("types", "02 · Erste Schritte", "Datentypen und Umwandlung", "javascript", "Du erkennst Text, Zahl und Boolean und kannst Werte vergleichen.", "JavaScript hat dynamische Typen: Ein Wert hat einen Typ, auch wenn er nicht bei der Variablendeklaration hingeschrieben wird. Häufig sind `string`, `number` und `boolean`. `Number('12')` wandelt gültigen Zahlentext in eine Zahl um; ungültige Eingaben ergeben `NaN`, das du prüfen musst.", [example("Drei Typen", "const name = 'Mina';\nconst age = 14;\nconst ready = true;", "Die Werte sind Text, Zahl und Wahrheitswert."), example("Text sicher umwandeln", "const points = Number('12');\nconsole.log(Number.isNaN(points));", "Number.isNaN hilft, eine fehlgeschlagene Umwandlung zu erkennen.")], "const age = 14;\n", "Lege einen Zahlenwert und einen Textwert an und gib beide Typen mit typeof aus.", "typeof\\s+\\w+"),
  lesson("operators", "02 · Erste Schritte", "Operatoren und Vergleiche", "javascript", "Du rechnest mit Zahlen und vergleichst Werte ohne Typüberraschungen.", "`+`, `-`, `*` und `/` rechnen mit Zahlen; `===` vergleicht Wert und Typ. `==` führt eine automatische Typumwandlung aus und kann überraschende Ergebnisse liefern. Verwende für Bedingungen normalerweise `===`, `!==`, `<` und `>=`.", [example("Rechnen", "const total = 3 * 4 + 2;", "Multiplikation wird vor Addition berechnet: total ist 14."), example("Strenger Vergleich", "console.log(12 === '12'); // false", "Zahl 12 und Text '12' sind nicht gleich typisiert.")], "const price = 12;\n", "Berechne den Preis für drei Stück und prüfe mit ===, ob die Anzahl genau 3 ist.", "===|\\*"),
  lesson("conditions", "03 · Ablauf steuern", "Bedingungen mit if und else", "javascript", "Du beschreibst unterschiedliche Fälle mit klaren Bedingungen.", "Eine `if`-Bedingung wird zu `true` oder `false` ausgewertet. Ist sie wahr, läuft der zugehörige Block; andernfalls kann `else` greifen. Für mehrere Fälle kannst du `else if` verwenden. Prüfe Grenzwerte bewusst, etwa ob 10 bereits bestanden bedeutet.", [example("Zwei Fälle", "if (score >= 10) {\n  console.log('Bestanden');\n} else {\n  console.log('Weiter üben');\n}", "Der Vergleich bestimmt genau einen der zwei Zweige."), example("Drei Fälle", "if (score < 0) {\n  console.log('Ungültig');\n} else if (score >= 10) {\n  console.log('Bestanden');\n} else {\n  console.log('Weiter üben');\n}", "Die Reihenfolge der Prüfungen ist wichtig.")], "const score = 8;\n\n", "Ergänze eine if/else-Prüfung für mindestens 10 Punkte und gib in beiden Fällen eine Meldung aus.", "if\\s*\\([^)]*score\\s*>=\\s*10[^)]*\\)[\\s\\S]*else"),
  lesson("loops", "03 · Ablauf steuern", "Schleifen und Wiederholungen", "javascript", "Du wiederholst Schritte, ohne denselben Code mehrfach zu kopieren.", "Eine `for`-Schleife eignet sich, wenn du einen Zähler oder eine bekannte Anzahl an Durchläufen hast. `while` wiederholt, solange eine Bedingung wahr ist. Ändere in jeder Runde den Zustand so, dass die Schleife irgendwann endet.", [example("Zählen", "for (let i = 1; i <= 3; i++) {\n  console.log(i);\n}", "Start, Endbedingung und Änderung stehen sichtbar im Schleifenkopf."), example("Werte durchlaufen", "for (const name of ['Mina', 'Sam']) {\n  console.log(name);\n}", "for...of liest nacheinander die Werte eines Arrays.")], "// Gib die Zahlen 1 bis 5 aus\n", "Schreibe eine for-Schleife, die von 1 bis einschließlich 5 zählt.", "for\\s*\\(\\s*(?:let|var)\\s+i\\s*=\\s*1\\s*;\\s*i\\s*<=\\s*5"),
  lesson("collections", "03 · Ablauf steuern", "Arrays und Objekte", "javascript", "Du speicherst mehrere zusammengehörige Werte und liest sie aus.", "Ein Array ist eine geordnete Liste; der erste Index ist 0. Ein Objekt gruppiert Werte unter benannten Eigenschaften. Mit `map` erzeugst du aus jedem Element ein neues Ergebnis, mit `filter` behältst du passende Elemente. Wähle die Struktur nach der Frage, die du beantworten willst.", [example("Array lesen", "const scores = [4, 8, 12];\nconsole.log(scores[0]); // 4", "Der Index 0 bezeichnet das erste Element."), example("Objekt und Filter", "const learner = { name: 'Mina', score: 12 };\nconst passed = [4, 12].filter(score => score >= 10);", "Eigenschaften beschreiben einen Datensatz; filter wählt passende Werte.")], "const scores = [4, 8, 12];\n", "Ergänze ein Objekt mit Name und Punktzahl und filtere aus einem Array alle Werte ab 10.", "\\.filter\\s*\\(|\\{[^}]*name"),
  lesson("functions", "04 · Wiederverwenden", "Funktionen, Parameter und Rückgabe", "javascript", "Du zerlegst ein Problem in aufrufbare Schritte mit Eingaben und Ergebnis.", "Eine Funktion bündelt einen benannten Arbeitsschritt. Parameter sind Platzhalter für Eingaben; `return` gibt das Ergebnis zurück. Ein Funktionsaufruf führt den Körper aus. Eine Funktion sollte möglichst eine klar beschreibbare Aufgabe haben.", [example("Wert zurückgeben", "function double(value) {\n  return value * 2;\n}\nconsole.log(double(4));", "double erhält 4 und gibt 8 zurück."), example("Arrow Function", "const greet = name => `Hallo, ${name}`;", "Kurze Funktionen können als Arrow Function geschrieben werden.")], "// Schreibe eine Funktion add(a, b)\n\nconsole.log(add(2, 3));\n", "Schreibe add(a, b), gib die Summe zurück und rufe die Funktion mit zwei Werten auf.", "function\\s+add\\s*\\(|const\\s+add\\s*=.*=>"),
  lesson("errors", "04 · Wiederverwenden", "Fehler lesen und gezielt debuggen", "javascript", "Du findest die Stelle eines Fehlers und prüfst Annahmen schrittweise.", "Die Konsole zeigt meist Fehlertyp, Meldung und Zeile. Ein Syntaxfehler verhindert das Parsen; ein Laufzeitfehler tritt erst beim Ausführen auf; ein Logikfehler liefert ein falsches Ergebnis. Prüfe zuerst Eingabewerte und Zwischenstände mit `console.log`, dann ändere immer nur eine Sache.", [example("Eingabe sichtbar machen", "console.log({ score, type: typeof score });", "Ein Objekt in der Ausgabe zeigt mehrere Zwischenwerte auf einmal."), example("Eingabe abfangen", "const value = Number(input);\nif (Number.isNaN(value)) {\n  console.log('Bitte Zahl eingeben');\n}", "Prüfe Daten, bevor du mit ihnen weiterrechnest.")], "const input = 'abc';\n// Prüfe die Umwandlung\n", "Wandle Eingabetext in eine Zahl um, erkenne NaN und gib bei ungültiger Eingabe eine hilfreiche Meldung aus.", "Number\\.isNaN\\s*\\("),
  lesson("modules", "04 · Wiederverwenden", "Module und async/await", "javascript", "Du trennst Dateien und verstehst asynchrone Ergebnisse.", "ES-Module teilen Code mit `export` und `import` in Dateien auf. Netzwerkanfragen dauern; deshalb liefern Browser-Fetch und viele Node-APIs ein Promise. `await` wartet innerhalb einer `async`-Funktion auf dessen Ergebnis. Fehler bei Anfragen behandelst du mit `try/catch`.", [example("Funktion exportieren", "export function formatName(name) {\n  return name.trim();\n}", "Eine andere Datei kann die Funktion gezielt importieren."), example("Anfrage behandeln", "async function loadCourses() {\n  try {\n    const response = await fetch('/api/courses');\n    if (!response.ok) throw new Error('Anfrage fehlgeschlagen');\n    return await response.json();\n  } catch (error) {\n    console.error(error);\n  }\n}", "Prüfe HTTP-Status und Fehler; ein Promise garantiert keine erfolgreiche Antwort.")], "async function loadData() {\n  // Anfrage behandeln\n}\n", "Ergänze in einer async-Funktion await fetch(...), prüfe response.ok und behandle Fehler mit try/catch.", "async\\s+function|await\\s+fetch|try\\s*\\{"),
  lesson("tests", "05 · Anwenden", "Tests und ein erstes Browserprojekt", "javascript", "Du prüfst Funktionen mit mehreren Fällen und bindest eine Oberfläche an Ereignisse.", "Ein Test vergleicht ein erwartetes Ergebnis mit dem tatsächlichen Ergebnis. Teste normalen Fall, Grenzfall und ungültige Eingabe. Im Browser bildet das DOM die HTML-Struktur ab; `addEventListener` reagiert auf Aktionen. DOM und Ereignisse sind Browserfunktionen, nicht die JavaScript-Sprache selbst.", [example("Kleine Prüffunktion", "function isAdult(age) { return age >= 18; }\nconsole.assert(isAdult(18) === true);", "Ein Grenzfall deckt Fehler an der Schwelle auf."), example("Klick reagieren", "button.addEventListener('click', () => {\n  message.textContent = 'Gestartet';\n});", "textContent setzt Text, ohne HTML aus Nutzereingaben zu interpretieren.")], "function isAdult(age) {\n  return age >= 18;\n}\n", "Teste die Grenze 18 und 17 mit console.assert und schreibe eine sichere Text-Rückmeldung für einen Klick.", "console\\.assert|addEventListener\\s*\\("),
  lesson("ecosystem", "06 · Werkzeuge sinnvoll wählen", "React und Node.js: Was sie ergänzen", "javascript", "Du unterscheidest Sprachgrundlagen, Browser-APIs, Laufzeiten und Bibliotheken.", "React ist eine Bibliothek zum Bauen von Oberflächen aus Komponenten. Node.js ist eine Laufzeit für JavaScript außerhalb des Browsers. Beides ersetzt nicht Variablen, Funktionen, Module oder asynchrone Abläufe. Beginne ein Projekt mit plain JavaScript, wenn es klein bleibt; nimm React bei komplexer, wiederverwendbarer UI und Node.js für Server oder Werkzeuge.", [example("React-Komponente", "function Greeting({ name }) {\n  return <h1>Hallo, {name}</h1>;\n}", "JSX beschreibt UI; eine Komponente ist eine Funktion, die Darstellung zurückgibt."), example("Node.js", "import { readFile } from 'node:fs/promises';\nconst text = await readFile('notes.txt', 'utf8');", "Node bietet APIs wie Dateizugriff, die eine Browserseite nicht einfach besitzt.")], "// Schreibe eine kleine Funktion, die einen Namen begrüßt\n", "Erkläre am Beispiel, welche Aufgabe JavaScript übernimmt und welche Rolle React oder Node.js dabei hat.", "function\\s+\\w+\\s*\\(|export|import"),
];

const java: LessonBlueprint[] = [
  intro("orientation", "Was ist Java?", "java", "Java ist eine statisch typisierte Programmiersprache. Der Compiler prüft Quellcode und erzeugt Bytecode; die Java Virtual Machine (JVM) führt diesen aus. Java wird für Server, Unternehmensprogramme, Android-Anwendungen und Desktopsoftware eingesetzt. JDK, JVM und Java-Sprache sind unterschiedliche Teile.", [example("Vom Quelltext zur Ausführung", "Main.java → javac → Bytecode → JVM", "Der Bytecode ist nicht direkt die Java-Laufzeit."), example("Eine Ausgabe", "System.out.println(2 + 3);", "Die JVM führt die Anweisung aus und gibt 5 aus.")], "Welche Aufgabe hat die JVM?", "Sie führt den kompilierten Java-Bytecode aus.", "Sie ist ein Datenbankformat für Webseiten.", "Sie schreibt automatisch den Java-Quelltext für dich."),
  lesson("run", "02 · Sprache und Werte", "Programmstart und Ausgabe", "java", "Du erkennst den Programmeinstieg und gibst Werte aus.", "Ein einfaches Java-Programm enthält eine Klasse und eine `main`-Methode. `System.out.println` schreibt eine Zeile in die Konsole. Der Java-Compiler verlangt passende Typen und eine gültige Struktur, bevor das Programm startet.", [example("Programmeinstieg", "class Main {\n  public static void main(String[] args) {\n    System.out.println(2 + 3);\n  }\n}", "Die JVM startet hier die main-Methode."), example("Text ausgeben", "System.out.println(\"Hallo Java\");", "Text ist in doppelte Anführungszeichen eingeschlossen.")], "class Main {\n  public static void main(String[] args) {\n    // Ausgabe ergänzen\n  }\n}\n", "Gib einen Begrüßungstext sowie das Ergebnis einer Addition aus.", "System\\.out\\.println\\s*\\("),
  lesson("types", "02 · Sprache und Werte", "Variablen und statische Typen", "java", "Du deklarierst Variablen mit einem passenden Typ.", "Java prüft viele Typfehler vor der Ausführung. `int` speichert ganze Zahlen, `double` Kommazahlen, `boolean` Wahrheitswerte und `String` Text. Eine Variable kann meist nicht nachträglich auf einen anderen Typ wechseln.", [example("Typ vor dem Namen", "int score = 12;\nString learner = \"Mina\";", "Der Typ steht vor dem Variablennamen."), example("Konstante", "final int MAX_TRIES = 3;", "final verhindert, dass die Variable neu zugewiesen wird.")], "int score = 12;\n", "Lege String learner und int score an und gib beide mit System.out.println aus.", "\\b(?:int|String)\\s+\\w+\\s*=.*System\\.out\\.println"),
  lesson("operations", "02 · Sprache und Werte", "Rechnen und Vergleichen", "java", "Du verwendest arithmetische und logische Operatoren korrekt.", "Java unterscheidet `==` bei primitiven Werten und Inhaltvergleiche bei Objekten. Für Text vergleichst du den Inhalt meist mit `equals`. Ganzzahldivision schneidet den Nachkommaanteil ab; `5 / 2` ergibt deshalb 2. Verwende `5.0 / 2`, wenn du 2,5 brauchst.", [example("Ganzzahldivision", "int half = 5 / 2; // 2", "Beide Operanden sind int, also ist das Ergebnis ebenfalls ganzzahlig."), example("Textinhalt vergleichen", "if (name.equals(\"Mina\")) {\n  System.out.println(\"Hallo Mina\");\n}", "== prüft bei Strings nicht zuverlässig den Zeicheninhalt.")], "int a = 5;\nint b = 2;\n", "Berechne ganzzahlige und Dezimaldivision und vergleiche zwei Strings mit equals.", "\\.equals\\s*\\(|5\\.0\\s*/\\s*2"),
  lesson("conditions", "03 · Ablauf steuern", "if, else und switch", "java", "Du wählst anhand eines Werts einen nachvollziehbaren Ablauf.", "`if` prüft einen boolean-Ausdruck. `else if` ergänzt weitere Fälle, `else` fängt den Rest ab. `switch` ist für mehrere klar getrennte Werte lesbar. Vergleiche bei Zahlen Grenzen bewusst und verhindere ungültige Eingaben vor der Bewertung.", [example("Grenzwert prüfen", "if (score >= 10) {\n  System.out.println(\"Bestanden\");\n} else {\n  System.out.println(\"Weiter üben\");\n}", "Der Grenzwert 10 gehört hier zum bestandenen Fall."), example("Mehrere feste Fälle", "switch (day) {\n  case 1 -> System.out.println(\"Montag\");\n  default -> System.out.println(\"Anderer Tag\");\n}", "Die Pfeilsyntax ist in modernen Java-Versionen verfügbar.")], "int score = 8;\n", "Ergänze if/else für 10 Punkte und gib bei negativen Punkten eine ungültige Eingabe aus.", "if\\s*\\([^)]*score\\s*>=\\s*10[^)]*\\)[\\s\\S]*else"),
  lesson("loops", "03 · Ablauf steuern", "Schleifen und Iterationen", "java", "Du wiederholst Anweisungen sicher und kannst Elemente durchlaufen.", "`for` eignet sich für Zähler, `while` für Wiederholung bis zu einer Bedingung. Die erweiterte for-Schleife läuft durch jedes Element einer Sammlung. Achte darauf, dass sich die Schleifenbedingung ändert, sonst entsteht eine Endlosschleife.", [example("Zählschleife", "for (int i = 1; i <= 3; i++) {\n  System.out.println(i);\n}", "Der Zähler startet bei 1 und wird pro Runde erhöht."), example("Array durchlaufen", "for (String name : names) {\n  System.out.println(name);\n}", "Die erweiterte Schleife liest jeden Namen der Reihe nach.")], "for (int i = 1; i <= 5; i++) {\n  // Ausgabe\n}\n", "Gib die Zahlen 1 bis 5 aus und durchlaufe zusätzlich ein String-Array.", "for\\s*\\(\\s*int\\s+i\\s*=\\s*1\\s*;\\s*i\\s*<=\\s*5"),
  lesson("collections", "03 · Ablauf steuern", "Arrays, Listen und Maps", "java", "Du wählst passende Datenstrukturen für geordnete Werte und Schlüssel.", "Arrays haben eine feste Länge. `ArrayList` wächst bei Bedarf und speichert geordnete Elemente; `HashMap` ordnet Schlüssel Werten zu. Generics wie `List<String>` machen den erlaubten Elementtyp sichtbar und reduzieren Umwandlungsfehler.", [example("Liste", "List<String> names = new ArrayList<>();\nnames.add(\"Mina\");", "Die Liste kann weitere Namen aufnehmen."), example("Map", "Map<String, Integer> scores = new HashMap<>();\nscores.put(\"Mina\", 12);", "Der Schlüssel Mina verweist auf den Wert 12.")], "List<String> names = new ArrayList<>();\n", "Füge zwei Namen zu einer ArrayList hinzu und durchlaufe sie mit einer for-each-Schleife.", "List\\s*<\\s*String\\s*>|ArrayList"),
  lesson("methods", "04 · Objektorientierung", "Methoden und Klassen", "java", "Du strukturierst Verhalten in Methoden und stellst eigene Typen dar.", "Eine Methode beschreibt Verhalten einer Klasse. Parameter sind Eingaben; der Rückgabetyp steht vor dem Methodennamen. Eine Klasse beschreibt einen eigenen Typ mit Feldern und Methoden. Instanzen sind konkrete Objekte dieses Typs.", [example("Methode mit Rückgabe", "static int doubleValue(int value) {\n  return value * 2;\n}", "int vor dem Namen beschreibt den Rückgabewert."), example("Objekt", "class Learner {\n  String name;\n  Learner(String name) { this.name = name; }\n}", "Der Konstruktor legt einen neuen Learner an.")], "static int add(int a, int b) {\n  // Ergebnis zurückgeben\n}\n", "Schreibe add(a,b) mit int-Rückgabe und erstelle eine Klasse mit einem Feld und einem Konstruktor.", "static\\s+int\\s+add\\s*\\(|class\\s+\\w+"),
  lesson("errors", "04 · Objektorientierung", "Ausnahmen und Fehlerbehandlung", "java", "Du behandelst erwartbare Fehler, ohne wichtige Details zu verschlucken.", "Eine Exception signalisiert, dass ein normaler Ablauf nicht möglich war. Behandle nur Fehler, für die du eine sinnvolle Reaktion kennst. `try/catch` ist kein Ersatz für Eingabeprüfung; ein leerer catch-Block versteckt den Fehler.", [example("Zahl parsen", "try {\n  int value = Integer.parseInt(input);\n} catch (NumberFormatException error) {\n  System.out.println(\"Bitte eine ganze Zahl eingeben\");\n}", "Nur der erwartete Parsefehler wird hier behandelt."), example("Eigene Prüfung", "if (score < 0) {\n  throw new IllegalArgumentException(\"Punktzahl darf nicht negativ sein\");\n}", "Ungültige Werte kannst du klar zurückweisen.")], "String input = \"abc\";\n", "Wandle einen Text in eine Zahl um und gib bei NumberFormatException eine verständliche Meldung aus.", "try\\s*\\{[\\s\\S]*catch\\s*\\(\\s*NumberFormatException"),
  lesson("tests", "05 · Anwenden", "JUnit-Tests und Spring Boot als Ausblick", "java", "Du schreibst überprüfbare Methoden und erkennst den Platz wichtiger Werkzeuge.", "Teste eine Methode mit normalen Werten, Grenzwerten und ungültigen Eingaben. JUnit ist ein Testframework. Spring Boot baut auf Java, Klassen und Methoden auf und erleichtert Webdienste; es ist kein Ersatz für Java-Grundlagen. Starte erst mit dem einfachen Java-Programm und nimm Spring Boot, wenn du Routing und HTTP-APIs brauchst.", [example("JUnit-Grenzfall", "@Test\nvoid scoreAtLimitPasses() {\n  assertTrue(isPassing(10));\n}", "Der Test dokumentiert die gewünschte Grenzregel."), example("Spring Boot Route", "@GetMapping(\"/courses\")\nList<Course> courses() { return service.all(); }", "Eine Route verweist auf Geschäftslogik, die separat getestet werden sollte.")], "static boolean isPassing(int score) {\n  return score >= 10;\n}\n", "Prüfe die Werte 9, 10 und 11 in JUnit und erkläre, wann ein Webframework wie Spring Boot nützlich wird.", "@Test|assertTrue|assertEquals"),
];

const python: LessonBlueprint[] = [
  intro("orientation", "Was ist Python?", "python", "Python ist eine universelle Programmiersprache, die auf Lesbarkeit und einen schnellen Einstieg ausgelegt ist. Sie wird für Automatisierung, Webdienste, Datenanalyse und wissenschaftliche Software genutzt. CPython, die verbreitete Implementierung, übersetzt Quelltext in Bytecode und führt ihn in einer virtuellen Maschine aus.", [example("Anweisung und Ergebnis", "print(2 + 3)", "Python berechnet zuerst den Ausdruck und gibt 5 aus."), example("Typische Einsatzfelder", "Automatisierung · Web-API · Datenanalyse · Tests", "Die Sprache bleibt dieselbe; Bibliotheken ergänzen passende Aufgaben.")], "Wofür kann Python eingesetzt werden?", "Zum Beispiel für Automatisierung, Webdienste und Datenanalyse.", "Nur zum Erstellen von Webseitenfarben.", "Ausschließlich auf einem bestimmten Betriebssystem."),
  lesson("run", "02 · Sprache und Werte", "Skript, Einrückung und Ausgabe", "python", "Du führst ein Python-Skript aus und erkennst, wie Einrückung Codeblöcke bildet.", "Eine Python-Datei endet häufig auf `.py`. `print` zeigt einen Wert an. Anders als viele Sprachen markiert Python Codeblöcke durch Einrückung; gleichmäßig eingerückte Zeilen gehören zusammen. Üblich sind vier Leerzeichen pro Ebene.", [example("Ausgabe", "print('Hallo Python')", "Die Funktion print gibt den Text aus."), example("Block durch Einrückung", "if True:\n    print('Dieser Block gehört zu if')", "Die eingerückte Zeile wird nur im Block ausgeführt.")], "# Gib eine Begrüßung aus\n", "Gib eine Begrüßung und das Ergebnis einer Rechnung aus. Schreibe einen kurzen if-Block mit vier Leerzeichen Einrückung.", "print\\s*\\("),
  lesson("values", "02 · Sprache und Werte", "Variablen und Grundtypen", "python", "Du verwendest Namen für Text, Zahlen und Wahrheitswerte.", "Eine Zuweisung wie `score = 12` bindet einen Namen an einen Wert. Häufige Typen sind `int`, `float`, `str` und `bool`. Namen werden nicht mit einem Typ deklariert; zur Laufzeit gehört der Typ zum Wert. Nutze `type(...)`, um ihn zu untersuchen.", [example("Werte benennen", "name = 'Mina'\nscore = 12\nready = True", "Text, ganze Zahl und boolescher Wert."), example("Typ prüfen", "print(type(score).__name__)  # int", "type zeigt den aktuellen Typ des Werts.")], "name = 'Mina'\nscore = 12\n", "Lege Text, Zahl und Wahrheitswert an und gib die Typen mit type aus.", "type\\s*\\("),
  lesson("operators", "02 · Sprache und Werte", "Operatoren und Vergleiche", "python", "Du rechnest mit Zahlen und formulierst Bedingungen.", "Python unterstützt die üblichen Rechenoperatoren. `//` ist Ganzzahldivision, `%` liefert den Rest. Vergleiche ergeben `True` oder `False`; `and`, `or` und `not` verbinden Wahrheitswerte. Achte darauf, dass `input()` immer Text liefert, auch wenn die Eingabe wie eine Zahl aussieht.", [example("Rechnung", "total = 5 + 2 * 3\nremainder = 10 % 3", "Multiplikation geschieht vor Addition; der Rest ist 1."), example("Text zu Zahl", "age = int(input('Alter: '))\nprint(age >= 18)", "Für ungültigen Text brauchst du später eine Fehlerbehandlung.")], "price = 4\nquantity = 3\n", "Berechne einen Gesamtpreis, vergleiche ihn mit einer Grenze und wandle eine Texteingabe in int um.", "int\\s*\\(\\s*input|>=|%"),
  lesson("conditions", "03 · Abläufe", "if, elif und else", "python", "Du teilst den Programmablauf in verständliche Fälle auf.", "`if` führt einen eingerückten Block aus, wenn die Bedingung wahr ist. `elif` prüft einen weiteren Fall; `else` behandelt alle übrigen Fälle. Python kennt keine geschweiften Klammern für diese Blöcke, deshalb muss die Einrückung stimmen.", [example("Zwei Fälle", "if score >= 10:\n    print('Bestanden')\nelse:\n    print('Weiter üben')", "Die Vergleichsgrenze entscheidet zwischen zwei Ausgaben."), example("Drei Fälle", "if score < 0:\n    print('Ungültig')\nelif score >= 10:\n    print('Bestanden')\nelse:\n    print('Weiter üben')", "elif erlaubt zusätzliche Fälle in klarer Reihenfolge.")], "score = 8\n", "Ergänze einen if/elif/else-Block für ungültige, bestandene und noch nicht bestandene Punktzahlen.", "if\\s+score\\s*>=\\s*10:[\\s\\S]*else:"),
  lesson("loops", "03 · Abläufe", "for, while und Abbruchbedingungen", "python", "Du wiederholst Code und vermeidest Endlosschleifen.", "`for` durchläuft Elemente einer Sequenz. `range(1, 6)` erzeugt 1 bis 5, weil das Ende exklusiv ist. `while` wiederholt, solange eine Bedingung stimmt. Verändere im Schleifenkörper den Wert, von dem die Bedingung abhängt.", [example("Zählen", "for number in range(1, 4):\n    print(number)", "Ausgabe: 1, 2, 3; die obere Grenze 4 ist ausgeschlossen."), example("Liste durchlaufen", "for name in ['Mina', 'Sam']:\n    print(name)", "Die Schleife erhält direkt die Listenelemente.")], "for number in range(1, 6):\n    # Zahl ausgeben\n    pass\n", "Gib 1 bis 5 aus und schreibe eine while-Schleife, die ihren Zähler sicher erhöht.", "range\\s*\\(\\s*1\\s*,\\s*6|while\\s+"),
  lesson("collections", "03 · Abläufe", "Listen und Dictionaries", "python", "Du speicherst geordnete Werte und benannte Eigenschaften.", "Eine Liste speichert Werte in Reihenfolge und kann wachsen. Ein Dictionary ordnet Schlüsseln Werte zu. `append` fügt hinzu; `in` prüft Zugehörigkeit. Bei fehlenden Dictionary-Schlüsseln kannst du `get` nutzen, um einen Standardwert anzugeben.", [example("Liste erweitern", "scores = [4, 8]\nscores.append(12)", "Die Liste enthält nun drei Punktzahlen."), example("Dictionary lesen", "learner = {'name': 'Mina', 'score': 12}\nprint(learner.get('score', 0))", "get liefert 0, falls score fehlt.")], "scores = [4, 8, 12]\n", "Füge einen Wert an eine Liste an und lies name und score aus einem Dictionary.", "\\.append\\s*\\(|\\.get\\s*\\("),
  lesson("functions", "04 · Funktionen und Dateien", "Funktionen, Parameter und Rückgabe", "python", "Du kapselst einen Arbeitsschritt mit def und return.", "`def` definiert eine Funktion. Parameter benennen die erwarteten Eingaben; `return` gibt einen Wert zurück. Lokale Variablen leben in ihrem Funktionsbereich. Ein Standardargument ist sinnvoll, wenn es für viele Aufrufe denselben sicheren Wert gibt.", [example("Wert zurückgeben", "def double(value):\n    return value * 2\n\nprint(double(4))", "Die Funktion gibt 8 zurück; print zeigt es nur an."), example("Standardwert", "def greet(name='Lernende Person'):\n    return f'Hallo, {name}'", "Ein Aufruf ohne Namen verwendet den Standardwert.")], "def add(a, b):\n    # Summe zurückgeben\n    pass\n", "Implementiere add(a, b), rufe die Funktion mit 2 und 3 auf und prüfe auch negative Werte.", "def\\s+add\\s*\\(|return\\s+.*\\+"),
  lesson("errors", "04 · Funktionen und Dateien", "Fehlerbehandlung und Module", "python", "Du fängst erwartbare Fehler ab und teilst Code in Module.", "Ein Syntaxfehler verhindert das Starten; eine Exception entsteht während der Ausführung. Behandle in `except` nur erwartbare Fehler, etwa `ValueError` beim Zahlenparsen. `import` bindet Module ein. Eigene Dateien sollten Namen haben, die nicht mit bekannten Standardbibliotheken kollidieren.", [example("Zahl sicher lesen", "try:\n    age = int('unknown')\nexcept ValueError:\n    print('Bitte eine ganze Zahl eingeben')", "Das Programm gibt eine hilfreiche Meldung statt eines Tracebacks aus."), example("Modul importieren", "from pathlib import Path\nprint(Path('.').resolve())", "pathlib bietet plattformgerechte Pfadfunktionen.")], "text = '12'\n", "Fange ValueError beim Umwandeln von Text in int ab und verwende ein importiertes Standardmodul.", "except\\s+ValueError|from\\s+pathlib\\s+import"),
  lesson("tests", "05 · Anwenden", "Dateien, Tests und Python-Werkzeuge", "python", "Du prüfst Funktionen und wählst Bibliotheken passend zur Aufgabe.", "Schreibe Tests für normale und ungültige Eingaben. `pytest` ist ein Testwerkzeug; `FastAPI` erstellt APIs, `pandas` arbeitet mit tabellarischen Daten. Das sind Zusatzbibliotheken, keine Bestandteile der Python-Syntax. Für Dateipfade ist `pathlib` meist verständlicher als selbst zusammengesetzte Pfadzeichenketten.", [example("Test mit pytest", "def test_double():\n    assert double(4) == 8", "Ein Test wird als Aussage geschrieben, die wahr sein muss."), example("Datei lesen", "from pathlib import Path\ntext = Path('notes.txt').read_text(encoding='utf-8')", "Explizite Textkodierung macht Dateiverhalten nachvollziehbar.")], "def double(value):\n    return value * 2\n", "Schreibe einen pytest-Test für 4 und 0. Erkläre anschließend, ob dein Projekt FastAPI, pandas oder keine der beiden Bibliotheken braucht.", "assert\\s+double\\s*\\(|read_text\\s*\\("),
];

const php: LessonBlueprint[] = [
  intro("orientation", "Was ist PHP?", "php", "PHP ist eine Programmiersprache, die besonders oft auf Webservern ausgeführt wird. Ein Server kann PHP verwenden, um eine HTTP-Anfrage zu verarbeiten und HTML oder JSON zurückzusenden. PHP läuft auch in der Kommandozeile. Die Sprache selbst lernst du zuerst mit Werten, Bedingungen und Funktionen.", [example("Serverantwort erzeugen", "<?php\necho 'Hallo';", "Der Server kann den ausgegebenen Text in seine Antwort übernehmen."), example("Zwei Einsatzorte", "Webserver: Anfrage → PHP → HTML/JSON\nCLI: Befehl → PHP-Skript → Ausgabe", "Die Laufumgebung bestimmt, wie die Ausgabe verwendet wird.")], "Wo läuft PHP typischerweise bei einer Webseite?", "Auf dem Server, der die Anfrage verarbeitet und eine Antwort erzeugt.", "Ausschließlich im Stylesheet des Browsers.", "PHP ist der Name einer Datenbank, die HTML speichert."),
  lesson("run", "02 · Syntax und Werte", "Ausgabe und PHP-Tags", "php", "Du erkennst PHP-Code und gibst einen Wert aus.", "PHP-Code steht in `<?php ... ?>`-Tags, wenn eine Datei auch HTML enthält. `echo` gibt Text oder einen Wert aus. In einer reinen PHP-Datei lässt man den schließenden Tag häufig weg, damit keine versehentlichen Leerzeichen in die Antwort gelangen.", [example("Text ausgeben", "<?php\necho 'Hallo PHP';", "Der String wird ausgegeben."), example("Wert berechnen", "<?php\necho 2 + 3;", "PHP berechnet vor der Ausgabe den Wert 5.")], "<?php\n", "Gib einen Text und das Ergebnis einer Addition aus.", "echo\\s+"),
  lesson("values", "02 · Syntax und Werte", "Variablen und Datentypen", "php", "Du weist Variablen Werte zu und erkennst grundlegende Typen.", "Variablennamen beginnen in PHP mit `$`. Häufige Typen sind `int`, `float`, `string`, `bool` und `array`. PHP ist dynamisch typisiert; `declare(strict_types=1)` kann bei Funktionsgrenzen strengere Typprüfungen aktivieren. Nutze aussagekräftige Namen und prüfe Daten aus Anfragen.", [example("Text und Zahl", "<?php\n$name = 'Mina';\n$score = 12;", "Das Dollarzeichen gehört zum Variablennamen."), example("Typ untersuchen", "var_dump($score);", "var_dump zeigt Wert und Typ für die Entwicklung.")], "<?php\n$name = 'Mina';\n", "Lege $score an, gib name und score aus und untersuche den Typ von score.", "\\$score\\s*=|var_dump\\s*\\("),
  lesson("strings", "02 · Syntax und Werte", "Strings und sichere Ausgabe", "php", "Du arbeitest mit Text und gibst ihn kontextgerecht aus.", "Ein String kann in einfachen oder doppelten Anführungszeichen stehen; doppelte Strings interpolieren Variablen. Wenn Text aus einer Anfrage als HTML ausgegeben wird, kann unescaped Inhalt gefährlich werden. Für HTML-Kontext ist `htmlspecialchars` mit passender Kodierung eine grundlegende Schutzmaßnahme.", [example("Interpolation", "$name = 'Mina';\necho \"Hallo, $name\";", "In doppelten Anführungszeichen wird $name ersetzt."), example("HTML sicher ausgeben", "echo htmlspecialchars($userInput, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');", "Escaping muss zum Ausgabekontext passen.")], "<?php\n$userInput = 'Text';\n", "Gib eine Variable in einem String aus und sichere eine HTML-Ausgabe mit htmlspecialchars ab.", "htmlspecialchars\\s*\\("),
  lesson("conditions", "03 · Ablauf", "Bedingungen und Schleifen", "php", "Du steuerst Abläufe mit if, foreach und klaren Grenzfällen.", "`if/else` wählt einen Ablauf anhand einer Bedingung. `foreach` durchläuft Werte aus Arrays. `===` prüft Wert und Typ und ist bei Eingaben meist weniger überraschend als `==`. Validierung muss serverseitig stattfinden, auch wenn der Browser dieselben Felder prüft.", [example("Strenger Vergleich", "if ($score === 12) {\n  echo 'Zwölf';\n}", "Der Wert muss Zahl 12 sein, nicht der Text '12'."), example("Array durchlaufen", "foreach ($names as $name) {\n  echo htmlspecialchars($name, ENT_QUOTES, 'UTF-8');\n}", "Jeder Wert wird einzeln ausgegeben und im HTML-Kontext escaped.")], "<?php\n$score = 8;\n", "Ergänze if/else für die Grenze 10 und durchlaufe ein Array mit foreach.", "if\\s*\\([^)]*\\$score\\s*>=\\s*10|foreach\\s*\\("),
  lesson("functions", "03 · Ablauf", "Funktionen und Typdeklarationen", "php", "Du schreibst wiederverwendbare Funktionen mit klarer Ein- und Ausgabe.", "Eine Funktion wird mit `function` deklariert. Parameter- und Rückgabetypen machen Erwartungen sichtbar. Ein `return` gibt den Wert zurück; `echo` schreibt etwas in die Antwort und ist nicht dasselbe. Eine kleine Funktion lässt sich einfacher testen.", [example("Typisierte Funktion", "function doubleValue(int $value): int {\n  return $value * 2;\n}", "Die Signatur dokumentiert Eingabe- und Ergebnistyp."), example("Ergebnis verwenden", "$doubled = doubleValue(4);\necho $doubled;", "Berechnung und Darstellung bleiben getrennte Schritte.")], "function add(int $a, int $b): int {\n  // Summe zurückgeben\n}\n", "Implementiere add mit int-Parametern und int-Rückgabe und verwende das Ergebnis.", "function\\s+add\\s*\\(|return\\s+\\$a\\s*\\+\\s*\\$b"),
  lesson("arrays", "04 · Daten und Dateien", "Arrays, assoziative Arrays und JSON", "php", "Du speicherst Listen und Datensätze und wandelst sie in JSON um.", "Ein PHP-Array kann eine Liste oder eine Schlüssel-Wert-Struktur abbilden. `[]` ist die moderne Schreibweise. `json_encode` erstellt JSON; kontrolliere Fehler und nutze passende Optionen für Unicode. JSON ist ein Austauschformat, keine sichere Datenbank.", [example("Liste und Datensatz", "$names = ['Mina', 'Sam'];\n$user = ['name' => 'Mina', 'score' => 12];", "Numerische und benannte Schlüssel erfüllen unterschiedliche Zwecke."), example("JSON erzeugen", "$json = json_encode($user, JSON_THROW_ON_ERROR);", "Die Option macht Kodierungsfehler als Exception sichtbar.")], "<?php\n$user = ['name' => 'Mina'];\n", "Ergänze eine Punktzahl, erzeuge JSON mit JSON_THROW_ON_ERROR und lies das Ergebnis wieder ein.", "json_encode\\s*\\(|JSON_THROW_ON_ERROR"),
  lesson("database", "04 · Daten und Dateien", "Formulare, Validierung und PDO", "php", "Du prüfst Eingaben und fragst Datenbanken ohne SQL-Verkettung ab.", "Alle Formularwerte sind zunächst nicht vertrauenswürdig. Prüfe Typ, Länge und erlaubte Werte serverseitig. PDO-Prepared-Statements trennen SQL-Befehl und Parameter und schützen vor SQL-Injection. Berechtigungen und Ausgabekodierung bleiben zusätzlich nötig.", [example("Zahl validieren", "$score = filter_input(INPUT_POST, 'score', FILTER_VALIDATE_INT);\nif ($score === false || $score === null) {\n  http_response_code(400);\n}", "Prüfe ungültige und fehlende Werte."), example("Parameter binden", "$stmt = $pdo->prepare('SELECT id FROM users WHERE email = :email');\n$stmt->execute(['email' => $email]);", "Der Wert wird als Parameter übergeben, nicht in SQL hineinkopiert.")], "$stmt = $pdo->prepare('SELECT id FROM users WHERE email = :email');\n", "Validiere eine Formularzahl und schreibe eine PDO-Abfrage mit benanntem Parameter.", "prepare\\s*\\(|execute\\s*\\("),
  lesson("frameworks", "05 · Anwenden", "Composer, Laravel und PHPUnit", "php", "Du verstehst, was Paketmanager, Framework und Testwerkzeug leisten.", "Composer verwaltet PHP-Pakete. Laravel bietet unter anderem Routing, Validierung und Datenbankzugriff, nimmt dir aber Sicherheitsentscheidungen nicht ab. PHPUnit testet Funktionen und Klassen. Beginne mit PHP-Grundlagen; wähle Laravel erst, wenn eine Anwendung von seinem Aufbau profitiert.", [example("Testabsicht", "self::assertSame(8, doubleValue(4));", "Der Test prüft konkretes erwartetes Verhalten."), example("Laravel Route", "Route::get('/courses', [CourseController::class, 'index']);", "Die Route sollte auf einen Controller verweisen, der Zugriffe kontrolliert.")], "function doubleValue(int $value): int { return $value * 2; }\n", "Schreibe einen PHPUnit-Test für 4 und 0 und beschreibe, wann du ein Webframework einsetzen würdest.", "assertSame\\s*\\(|Route::get\\s*\\("),
];

const typescript: LessonBlueprint[] = [
  intro("orientation", "Was ist TypeScript?", "typescript", "TypeScript ist eine Erweiterung von JavaScript mit einem statischen Typsystem. Der Compiler prüft den Code vor der Ausführung und erzeugt JavaScript; Browser und Node.js führen weiterhin JavaScript aus. TypeScript-Typen werden zur Laufzeit entfernt. Deshalb prüft ein TypeScript-Typ keine unbekannten Daten aus Netzwerk oder Formularen.", [example("Vor der Laufzeit", "TypeScript → Typprüfung → JavaScript → Browser / Node.js", "Die Laufzeit erhält JavaScript, nicht TypeScript-Typinformationen."), example("Typ notiert", "const score: number = 12;", "Der Compiler meldet, wenn hier ein Text zugewiesen wird.")], "Was macht der TypeScript-Compiler typischerweise?", "Er prüft Typen und übersetzt TypeScript in JavaScript.", "Er speichert alle Variablen als Typinformationen in der Datenbank.", "Er ersetzt die Laufzeitumgebung des Browsers."),
  lesson("run", "02 · Typen und Werte", "Ausgabe und Typannotation", "typescript", "Du schreibst eine eindeutige Typannotation und liest Compilerfehler.", "TypeScript erkennt viele Typen selbst; Annotationen helfen besonders an Schnittstellen. `string`, `number` und `boolean` sind Grundtypen. Der Compiler verhindert beispielsweise, dass eine Zahl an eine Funktion übergeben wird, die Text erwartet.", [example("Variable typisieren", "const learner: string = 'Mina';\nconst score: number = 12;", "Annotationen stehen hinter dem Doppelpunkt."), example("Funktion typisieren", "function greet(name: string): string {\n  return `Hallo, ${name}`;\n}", "Eingabe- und Rückgabetyp sind sichtbar.")], "const score: number = 12;\n", "Lege eine Text- und eine Zahlenvariable mit Typ an und schreibe eine Funktion mit String-Rückgabe.", "const\\s+\\w+\\s*:\\s*number|function\\s+\\w+\\s*\\([^)]*:\\s*string"),
  lesson("unions", "02 · Typen und Werte", "Unions, Literaltypen und narrowing", "typescript", "Du beschreibst mehrere erlaubte Werte und prüfst sie vor der Verwendung.", "Ein Union-Typ wie `string | number` erlaubt genau einen Wert aus diesen Typen. `typeof` grenzt den Typ in einem Zweig ein; das heißt narrowing. Literaltypen begrenzen eine Auswahl, etwa `'loading' | 'success' | 'error'`, und helfen, ungültige Zustände auszuschließen.", [example("Typ eingrenzen", "function label(value: string | number): string {\n  if (typeof value === 'number') return value.toFixed(1);\n  return value.toUpperCase();\n}", "Innerhalb des if-Zweigs kennt TypeScript value als Zahl."), example("Status festlegen", "type Status = 'loading' | 'success' | 'error';", "Andere Zeichenketten sind für Status nicht zulässig.")], "type Status = 'loading' | 'success' | 'error';\n", "Erstelle eine Funktion für string | number und behandle beide Typen mit typeof.", "\\btypeof\\s+\\w+|\\btype\\s+\\w+\\s*="),
  lesson("objects", "02 · Typen und Werte", "Objekttypen und optionale Felder", "typescript", "Du beschreibst die Struktur eines Datensatzes mit einer Schnittstelle.", "Ein `type`-Alias oder `interface` beschreibt erwartete Eigenschaften. `?` kennzeichnet ein optionales Feld; vor seiner Nutzung musst du prüfen, ob es vorhanden ist. `readonly` verbietet eine erneute Zuweisung an das Feld im geprüften Code, verändert das Objekt zur Laufzeit aber nicht.", [example("Interface", "interface Learner {\n  name: string;\n  score?: number;\n}", "score kann fehlen und muss deshalb geprüft werden."), example("Optionalen Wert prüfen", "if (learner.score !== undefined) {\n  console.log(learner.score.toFixed(0));\n}", "Die Prüfung macht den Zugriff sicher.")], "interface Learner {\n  name: string;\n  score?: number;\n}\n", "Beschreibe Learner mit name und optionalem score und prüfe score vor dem Zugriff.", "interface\\s+Learner|score\\?\\s*:") ,
  lesson("functions", "03 · Programmfluss", "Funktionen, Generics und Arrays", "typescript", "Du typisierst wiederverwendbare Funktionen und Listen.", "Ein Generic wie `Array<T>` beschreibt eine Liste von Werten eines Typs. Eine Funktion `<T>` kann mit verschiedenen Typen arbeiten, ohne die Typprüfung aufzugeben. Schreibe Generics nur, wenn die Funktion tatsächlich mit mehreren Typen arbeiten soll.", [example("Arraytyp", "const names: string[] = ['Mina', 'Sam'];", "Jedes Element muss ein String sein."), example("Generic Funktion", "function first<T>(items: T[]): T | undefined {\n  return items[0];\n}", "Bei first(names) kennt der Rückgabewert den Typ string | undefined.")], "function first<T>(items: T[]): T | undefined {\n  return items[0];\n}\n", "Erstelle eine Funktion, die das erste Element oder undefined zurückgibt, und prüfe den leeren Fall.", "<T>|\\bT\\[\\]|undefined"),
  lesson("async", "03 · Programmfluss", "Promises und asynchrone Daten", "typescript", "Du typisierst asynchrone Funktionen und prüfst unbekannte Antworten.", "Eine Funktion mit `async` liefert ein Promise. `await` macht den Ablauf lesbarer, wartet aber nicht synchron auf dem gesamten Programm. Netzwerkdaten sind zur Laufzeit nicht automatisch geprüft: `unknown` zwingt dich, sie vor der Verwendung zu validieren.", [example("Promise Rückgabe", "async function loadName(): Promise<string> {\n  return 'Mina';\n}", "Der Aufruf liefert Promise<string>."), example("Unbekannte Antwort", "const raw: unknown = JSON.parse(text);\nif (typeof raw === 'string') console.log(raw.toUpperCase());", "unknown ist sicherer als any, weil es eine Prüfung verlangt.")], "async function loadName(): Promise<string> {\n  return 'Mina';\n}\n", "Erstelle eine async Funktion und prüfe einen Wert vom Typ unknown mit typeof.", "Promise\\s*<|:\\s*unknown|\\btypeof\\b"),
  lesson("errors", "04 · Anwendung und Tests", "Fehler, Zod und Laufzeitvalidierung", "typescript", "Du erkennst, warum statische Typen externe Daten nicht automatisch validieren.", "Ein Typ wird beim Kompilieren entfernt. Eine JSON-Antwort kann daher trotz TypeScript-Typ falsche Werte enthalten. Laufzeitvalidatoren wie Zod prüfen reale Daten und erzeugen daraus einen validierten Wert. Behandle Netzwerkfehler und ungültige Antworten getrennt.", [example("Typ ist keine Laufzeitprüfung", "const payload: unknown = JSON.parse(text);", "Die Daten kommen als unbekannt an und brauchen eine echte Prüfung."), example("Zod Schema", "const Course = z.object({ id: z.string(), title: z.string() });\nconst course = Course.parse(payload);", "parse wirft bei ungültigen Daten einen Fehler.")], "const payload: unknown = JSON.parse(text);\n", "Validiere ein unbekanntes Objekt mit einem Schema oder beschreibe konkret die nötigen Laufzeitprüfungen.", "unknown|\\.parse\\s*\\(|safeParse\\s*\\("),
  lesson("frameworks", "05 · Anwenden", "React, Tests und Projektkonfiguration", "typescript", "Du wählst Typen und Werkzeuge passend zum Projekt.", "React-Komponenten können Props typisieren; Tests prüfen Verhalten unabhängig von der Oberfläche. `tsconfig` legt Compilerregeln fest. TypeScript hilft beim Umbau und bei großen Datenmodellen, garantiert aber weder korrekte Geschäftslogik noch Sicherheit. Stelle `strict` ein und vermeide `any` als Standardausweg.", [example("Props typisieren", "type GreetingProps = { name: string };\nfunction Greeting({ name }: GreetingProps) {\n  return <h1>Hallo, {name}</h1>;\n}", "Der Aufrufer muss ein name-Feld als Text übergeben."), example("Strenge Prüfung", "{\n  \"compilerOptions\": { \"strict\": true }\n}", "Strenge Optionen machen mögliche Fehler früher sichtbar.")], "type GreetingProps = { name: string };\n", "Typisiere eine React-Prop und schreibe eine Funktion, die eine falsche Eingabe im Test zurückweist.", "type\\s+\\w+Props|\\bstrict\\b|expect\\s*\\("),
];

const cpp: LessonBlueprint[] = [
  intro("orientation", "Was ist C++?", "cpp", "C++ ist eine kompilierte Programmiersprache für native Programme, Spiele, Werkzeuge und leistungsnahe Software. Sie baut auf C auf, ist aber eine eigene Sprache mit Klassen, Templates und einer umfangreichen Standardbibliothek. C++ gibt dir viel Kontrolle; dadurch musst du Ressourcen und Objektlebenszeiten bewusst verstehen.", [example("Kompilieren und starten", "C++-Quelltext → Compiler → ausführbares Programm", "Der Compiler übersetzt Quelltext passend zur Zielplattform."), example("Ein Ausgabeprogramm", "std::cout << \"Hallo\";", "Die Standardbibliothek stellt die Konsolenausgabe bereit.")], "Wofür wird C++ häufig verwendet?", "Für native Programme, Spiele und leistungsnahe Systeme.", "Als Layoutsprache, die nur Abstände einer Webseite festlegt.", "Als Datenbankserver, der Quelltext automatisch ausführt."),
  lesson("run", "02 · Sprache und Typen", "Programmeinstieg und Ausgabe", "cpp", "Du verstehst main und gibst Werte über die Standardbibliothek aus.", "Ein C++-Programm startet normalerweise in `main`. Einbinden mit `#include` macht Deklarationen verfügbar. `std::cout` schreibt Text; `\n` erzeugt einen Zeilenumbruch. Moderne Projekte sollten einen passenden Sprachstandard und Compilerwarnungen aktivieren.", [example("Kleines Programm", "#include <iostream>\nint main() {\n  std::cout << \"Hallo\" << '\\n';\n}", "main ist der Programmeinstieg."), example("Rechnen und ausgeben", "std::cout << 2 + 3 << '\\n';", "Der Ausdruck wird vor dem Einfügen in den Ausgabestrom berechnet.")], "#include <iostream>\nint main() {\n  // Ausgabe\n}\n", "Gib Text und das Ergebnis von 2 + 3 in main aus.", "std::cout\\s*<<"),
  lesson("types", "02 · Sprache und Typen", "Variablen, const und auto", "cpp", "Du wählst passende Grundtypen und erkennst, wann auto sinnvoll ist.", "`int`, `double`, `bool` und `std::string` beschreiben unterschiedliche Werte. `const` verhindert unbeabsichtigte Neuzuweisung. `auto` lässt den Compiler den Typ aus dem Initialwert ableiten; es macht C++ nicht dynamisch typisiert. Bevorzuge klare Namen und initialisiere Variablen sofort.", [example("Typen explizit", "int score = 12;\ndouble ratio = 0.75;\nbool ready = true;", "Die Deklarationen benennen Typ und Startwert."), example("Typ ableiten", "const auto message = std::string{\"Hallo\"};", "auto ist hier statische Typableitung zur Compilezeit.")], "int score = 12;\n", "Lege Zahl, Text und Wahrheitswert an; verwende const für einen unveränderlichen Wert.", "\\b(?:int|double|bool|std::string)\\s+\\w+\\s*=|const\\s+auto"),
  lesson("conditions", "03 · Ablauf und Daten", "Bedingungen und Schleifen", "cpp", "Du steuerst Abläufe und vermeidest Grenzen außerhalb eines Arrays.", "`if` und `else` wählen einen Zweig. Eine Zählschleife eignet sich für bekannte Grenzen; bei Sammlungen ist eine range-based for-Schleife meist sicherer. C++-Arrays beginnen bei Index 0; ein Zugriff außerhalb der gültigen Elemente ist ein Fehler.", [example("Bedingung", "if (score >= 10) {\n  std::cout << \"Bestanden\";\n} else {\n  std::cout << \"Weiter üben\";\n}", "Beide Fälle sind ausdrücklich behandelt."), example("Vektor durchlaufen", "for (int value : values) {\n  std::cout << value << '\\n';\n}", "Die Schleife liest jedes Element der Sammlung.")], "int score = 8;\n", "Ergänze if/else für 10 Punkte und durchlaufe einen std::vector mit range-based for.", "if\\s*\\([^)]*score\\s*>=\\s*10|for\\s*\\(\\s*int\\s+\\w+\\s*:") ,
  lesson("functions", "03 · Ablauf und Daten", "Funktionen und Referenzen", "cpp", "Du schreibst Funktionen und vermeidest unnötige Kopien.", "Eine Funktion deklariert Rückgabetyp, Namen und Parameter. Übergib kleine Zahlenwerte direkt; größere unveränderte Objekte oft als `const&`, damit keine Kopie entsteht. `void` bedeutet, dass keine Rückgabe erwartet wird. Halte Funktionen kurz und teste ihre Randfälle.", [example("Wert übergeben", "int doubleValue(int value) {\n  return value * 2;\n}", "Die Funktion erhält eine Kopie der Zahl."), example("Konstante Referenz", "void printName(const std::string& name) {\n  std::cout << name;\n}", "Die Referenz vermeidet Kopie und const schützt vor Änderung über diesen Zugriff.")], "int add(int a, int b) {\n  // Summe zurückgeben\n}\n", "Implementiere add und eine Funktion, die einen const std::string& entgegennimmt.", "int\\s+add\\s*\\(|const\\s+std::string\\s*&"),
  lesson("containers", "03 · Ablauf und Daten", "std::string, vector und map", "cpp", "Du nutzt Standardcontainer statt selbst unsichere Speicherverwaltung zu bauen.", "`std::string` verwaltet Text, `std::vector<T>` eine dynamische Liste und `std::map` geordnete Schlüssel-Wert-Paare. Container verwalten ihre Elemente und passen ihre Größe an. Greife nur auf gültige Elemente zu und verwende `at`, wenn du eine Bereichsprüfung möchtest.", [example("Vector", "std::vector<int> scores{4, 8, 12};\nscores.push_back(15);", "Der Vector wächst beim Einfügen."), example("Map", "std::map<std::string, int> points;\npoints[\"Mina\"] = 12;", "Der Schlüssel verweist auf einen Punktestand.")], "std::vector<int> scores{4, 8, 12};\n", "Füge einen Wert in den Vector ein und gib alle Elemente aus.", "std::vector\\s*<|push_back\\s*\\("),
  lesson("resources", "04 · Speicher und Typen", "Objektlebenszeit, RAII und Smart Pointer", "cpp", "Du lässt Ressourcen automatisch freigeben und vermeidest unnötige rohe new/delete-Aufrufe.", "C++-Objekte haben Lebenszeiten. RAII bindet eine Ressource an ein Objekt: Beim Verlassen des Bereichs wird sie automatisch freigegeben. Für geteilten Besitz gibt es `std::shared_ptr`, für eindeutigen dynamischen Besitz meist `std::unique_ptr`. Verwende rohe Zeiger nicht als Eigentumsmodell.", [example("Automatische Lebenszeit", "{\n  std::vector<int> values{1, 2, 3};\n} // Speicher wird automatisch freigegeben", "Der Container kümmert sich um seinen Speicher."), example("Eindeutiger Besitz", "auto item = std::make_unique<Widget>();", "unique_ptr besitzt die Ressource eindeutig.")], "auto item = std::make_unique<Widget>();\n", "Erkläre den Unterschied zwischen einzigartigem und geteiltem Besitz und nutze einen Smart Pointer.", "make_unique\\s*<|unique_ptr\\s*<"),
  lesson("classes", "04 · Speicher und Typen", "Klassen, Konstruktoren und const", "cpp", "Du kapselst Zustand und schützt Klasseninvarianten.", "Eine Klasse bündelt Daten und Funktionen. Der Konstruktor stellt einen gültigen Anfangszustand her. `private` schützt interne Details; öffentliche Methoden bieten kontrollierten Zugriff. `const`-Methoden versprechen, den beobachtbaren Objektzustand nicht zu verändern.", [example("Kleine Klasse", "class Learner {\n public:\n  explicit Learner(std::string name) : name_(std::move(name)) {}\n  const std::string& name() const { return name_; }\n private:\n  std::string name_;\n};", "Der Konstruktor initialisiert das Feld; der Zugriff ist const."), example("Objekt erstellen", "Learner learner{\"Mina\"};\nstd::cout << learner.name();", "Geschweifte Initialisierung ist klar und prüft Typen.")], "class Learner {\n public:\n  // Konstruktor ergänzen\n private:\n  std::string name_;\n};\n", "Ergänze einen Konstruktor und eine const-Zugriffsmethode für name_.", "class\\s+Learner|name\\(\\)\\s*const"),
  lesson("tools", "05 · Anwenden", "CMake, Tests und Bibliotheken", "cpp", "Du organisierst Builds und prüfst Verhalten mit einem Testframework.", "CMake beschreibt, wie Quellcode zu Zielen gebaut wird. Catch2 ist ein Testframework; die C++-Standardbibliothek enthält Container, Algorithmen und Ein-/Ausgabe. Compilerwarnungen und AddressSanitizer helfen, Fehler zu finden. Füge Abhängigkeiten gezielt hinzu und prüfe Lizenz und Wartungszustand.", [example("Algorithmus nutzen", "std::sort(scores.begin(), scores.end());", "Standardalgorithmen vermeiden handgeschriebene Sortierfehler."), example("Testidee", "CHECK(doubleValue(4) == 8);", "Ein Unit-Test beschreibt eine erwartete Eigenschaft.")], "int doubleValue(int value) { return value * 2; }\n", "Schreibe Tests für normalen und Grenzfall; notiere, was CMake, Catch2 und die Standardbibliothek jeweils tun.", "CHECK\\s*\\(|std::sort\\s*\\("),
];

const csharp: LessonBlueprint[] = [
  intro("orientation", "Was ist C#?", "csharp", "C# ist eine statisch typisierte Programmiersprache im .NET-Ökosystem. Der Compiler erzeugt Intermediate Language; die .NET-Laufzeit führt das Programm aus. C# wird für Webdienste, Desktopsoftware, Cloudanwendungen und Spiele eingesetzt. .NET ist die Laufzeit und Plattform; hier lernst du zunächst die Sprache selbst.", [example("Vom Code zur Laufzeit", "C# → Compiler → IL → .NET-Laufzeit", "Die Laufzeit verwaltet unter anderem Ausführung und Speicher."), example("Konsolenausgabe", "Console.WriteLine(2 + 3);", "Die Konsole zeigt 5 an.")], "Was ist .NET im Verhältnis zu C#?", ".NET ist eine Laufzeit und Plattform, auf der C#-Programme laufen können.", ".NET ist ein Datentyp für Dezimalzahlen.", "C# ist nur eine andere Schreibweise für HTML."),
  lesson("run", "02 · Sprache und Typen", "Programmeinstieg und Ausgabe", "csharp", "Du schreibst ein Konsolenprogramm und gibst Ergebnisse aus.", "Ein Konsolenprojekt enthält eine Einstiegsmethode oder moderne Top-Level-Anweisungen. `Console.WriteLine` gibt Text mit Zeilenumbruch aus. Der Compiler prüft Syntax und Typen; Fehlermeldungen zeigen häufig Datei und Zeile.", [example("Top-Level", "Console.WriteLine(\"Hallo C#\");", "Aktuelle Projektvorlagen können ohne sichtbare Main-Methode beginnen."), example("Rechnung", "Console.WriteLine(2 + 3);", "Der Ausdruck wird als Zahl berechnet.")], "Console.WriteLine(\"Hallo\");\n", "Gib eine Begrüßung und eine berechnete Summe aus.", "Console\\.WriteLine\\s*\\("),
  lesson("types", "02 · Sprache und Typen", "Typen, var und nullable Werte", "csharp", "Du unterscheidest statische Typen, Typableitung und mögliche Nullwerte.", "C# prüft Typen vor der Ausführung. `var` leitet den statischen Typ aus dem Startwert ab; danach bleibt er derselbe. `string?` kann bei aktivierten nullable Referenztypen auf null gesetzt werden. Prüfe optionale Werte, bevor du auf ihre Mitglieder zugreifst.", [example("Typableitung", "var score = 12; // statischer Typ: int\nstring learner = \"Mina\";", "var ist keine dynamische Typvariable."), example("Null prüfen", "string? name = GetName();\nif (name is not null) Console.WriteLine(name.Length);", "Die Prüfung schützt vor NullReferenceException.")], "var score = 12;\n", "Lege Text und int-Wert an und prüfe einen nullable String vor seiner Verwendung.", "string\\?| is not null|\\bvar\\s+score"),
  lesson("flow", "03 · Ablauf und Daten", "Bedingungen, Schleifen und Muster", "csharp", "Du steuerst den Ablauf und behandelst mehrere Fälle.", "`if`, `else` und `switch` wählen einen Pfad; `for` eignet sich für Zähler, `foreach` für Sammlungen. Ein `switch`-Ausdruck kann einen Wert zurückgeben. Schreibe jeden Fall explizit und vermeide verschachtelte Entscheidungen, die sich als kleine Methode besser erklären lassen.", [example("Punktzahl prüfen", "if (score >= 10) {\n  Console.WriteLine(\"Bestanden\");\n} else {\n  Console.WriteLine(\"Weiter üben\");\n}", "Die Grenze gehört zum bestandenen Fall."), example("Werte ausgeben", "foreach (var name in names)\n  Console.WriteLine(name);", "foreach liest jedes Element.")], "int score = 8;\n", "Ergänze if/else für die Grenze 10 und gib eine Liste mit foreach aus.", "if\\s*\\([^)]*score\\s*>=\\s*10|foreach\\s*\\("),
  lesson("collections", "03 · Ablauf und Daten", "Listen, Dictionaries und LINQ", "csharp", "Du speicherst Daten und filterst Sammlungen lesbar.", "`List<T>` speichert eine veränderliche Folge, `Dictionary<TKey,TValue>` ordnet Schlüssel Werten zu. LINQ bietet Abfragen wie `Where` und `Select`. Eine LINQ-Abfrage ist oft lesbar, wenn sie kurz bleibt; debugge lange Ketten schrittweise.", [example("Liste", "var scores = new List<int> { 4, 8, 12 };\nscores.Add(15);", "List<int> akzeptiert nur ganze Zahlen."), example("Filtern", "var passed = scores.Where(score => score >= 10).ToList();", "Where behält Werte, deren Bedingung true ergibt.")], "var scores = new List<int> { 4, 8, 12 };\n", "Füge einen Wert ein und filtere alle Punktzahlen ab 10 mit LINQ.", "Where\\s*\\(|List<int>|Dictionary<"),
  lesson("methods", "04 · Objektorientierung", "Methoden, Klassen und Records", "csharp", "Du kapselst Verhalten und unterscheidest veränderliche Klassen von Datenrecords.", "Methoden erhalten Parameter und liefern optional einen Rückgabewert. Eine Klasse bündelt Zustand und Verhalten. `record` eignet sich oft für Datenwerte mit wertbasierter Gleichheit. Nutze Zugriffsmodifizierer, damit interne Details nicht ungewollt Teil der öffentlichen Schnittstelle werden.", [example("Methode", "static int Double(int value) => value * 2;", "Der Ausdruck nach => ist das zurückgegebene Ergebnis."), example("Datenrecord", "public record Course(string Id, string Title);", "Records erzeugen eine kompakte Datenmodell-Form.")], "static int Add(int a, int b) => a + b;\n", "Schreibe eine Add-Methode und einen Record mit zwei Eigenschaften.", "static\\s+int\\s+Add|record\\s+\\w+\\s*\\("),
  lesson("errors", "04 · Objektorientierung", "Exceptions, Dateien und async/await", "csharp", "Du behandelst Fehler und wartest nicht blockierend auf Datei- oder Netzwerkergebnisse.", "Eine Exception signalisiert einen Fehlerfall. Fange nur Ausnahmen ab, auf die du sinnvoll reagieren kannst. `async` und `await` erleichtern nicht blockierende Datei- und Netzwerkarbeit. Nutze `using` beziehungsweise `await using`, wenn Ressourcen wie Streams freigegeben werden müssen.", [example("Fehler behandeln", "try {\n  var value = int.Parse(input);\n} catch (FormatException) {\n  Console.WriteLine(\"Bitte eine Zahl eingeben\");\n}", "Der konkrete Ausnahmefall wird behandelt."), example("Datei asynchron lesen", "var text = await File.ReadAllTextAsync(path);", "await wartet auf die Dateioperation, ohne den Thread unnötig zu blockieren.")], "try {\n  var value = int.Parse(input);\n} catch (FormatException) {\n  // Meldung\n}\n", "Behandle ungültigen Zahlentext und lies eine Datei asynchron.", "catch\\s*\\(\\s*FormatException|await\\s+File\\."),
  lesson("frameworks", "05 · Anwenden", "Tests, ASP.NET Core und Unity", "csharp", "Du ordnest .NET-Werkzeuge ihrer konkreten Aufgabe zu.", "xUnit testet C#-Verhalten. ASP.NET Core baut Webanwendungen und APIs. Unity ist eine Spieleengine, die C#-Skripte verwendet. Wähle nach dem Projekt: Backendroute, UI oder Spiel haben unterschiedliche Laufzeit- und Testanforderungen. Verstehe die Funktion zuerst, bevor du Frameworkcode kopierst.", [example("Unit-Test", "Assert.Equal(8, Double(4));", "Der Test überprüft ein Ergebnis."), example("ASP.NET Minimal API", "app.MapGet(\"/health\", () => Results.Ok(new { status = \"ok\" }));", "Der Server ordnet HTTP-Pfad und Handler zu.")], "static int Double(int value) => value * 2;\n", "Schreibe einen Test mit 4 und 0 und beschreibe, wann ASP.NET Core oder Unity passend wäre.", "Assert\\.Equal|MapGet\\s*\\("),
];

const rust: LessonBlueprint[] = [
  intro("orientation", "Was ist Rust?", "rust", "Rust ist eine kompilierte Programmiersprache für systemnahe Software, Kommandozeilenwerkzeuge, Webdienste und eingebettete Programme. Der Compiler prüft viele Speicher- und Threadingregeln bereits beim Übersetzen. Das Ownership-Modell wirkt anfangs ungewohnt, soll aber typische Speicherfehler ohne Garbage Collector verhindern.", [example("Projektlauf", "Rust-Quelltext → rustc / Cargo → natives Programm", "Cargo organisiert meist Build, Tests und Abhängigkeiten."), example("Ein Wert", "let score: i32 = 12;", "Der Typ ist zur Compilezeit festgelegt.")], "Was ist ein zentrales Merkmal von Rust?", "Der Compiler erzwingt Regeln für Besitz und sichere Speicherzugriffe.", "Rust führt jeden Befehl erst nach dem Klick in einer Tabellenzelle aus.", "Rust benötigt für jedes Programm zwingend einen Garbage Collector."),
  lesson("run", "02 · Werte und Besitz", "main, Ausgabe und let", "rust", "Du startest ein Rust-Programm und deklarierst unveränderliche Werte.", "Ein Programm startet gewöhnlich in `fn main()`. `println!` ist ein Makro für formatierte Ausgabe. Variablen sind standardmäßig unveränderlich; `mut` erlaubt gezielte Änderung. Typen wie `i32` können oft aus dem Kontext abgeleitet werden.", [example("Konsolenausgabe", "fn main() {\n    println!(\"Hallo Rust\");\n}", "Das Ausrufezeichen kennzeichnet ein Makro."), example("Veränderbarer Wert", "let mut score = 0;\nscore += 1;", "mut macht die Neuzuweisung ausdrücklich.")], "fn main() {\n    // Ausgabe ergänzen\n}\n", "Gib eine Begrüßung aus und erhöhe einen mutablen Punktestand.", "println!\\s*\\(|let\\s+mut\\s+score"),
  lesson("types", "02 · Werte und Besitz", "Skalare Typen, Tupel und Arrays", "rust", "Du wählst feste Typen und unterscheidest Tupel von dynamischen Vektoren.", "Rusts Grundtypen umfassen Ganzzahlen, Fließkommazahlen, `bool` und `char`. Ein Tupel bündelt Werte verschiedener Typen; ein Array hat feste Länge. Ein `Vec<T>` ist eine dynamische Liste. Der Typ muss eindeutig sein, oft wird er abgeleitet.", [example("Tupel", "let point: (i32, i32) = (3, 4);\nprintln!(\"{}\", point.0);", "Auf Tupelbestandteile greifst du über Positionen zu."), example("Vector", "let scores: Vec<i32> = vec![4, 8, 12];", "Der Vector kann zur Laufzeit wachsen.")], "let scores: Vec<i32> = vec![4, 8, 12];\n", "Lies das erste Element sicher mit get und gib einen verständlichen Fall für None aus.", "\\.get\\s*\\(|Option<"),
  lesson("flow", "03 · Ablauf", "Bedingungen, match und Schleifen", "rust", "Du wählst Fälle vollständig und durchläufst Werte.", "`if` ist ein Ausdruck und kann einen Wert liefern. `match` behandelt Fälle; Rust verlangt, dass sie vollständig abgedeckt sind. `for` durchläuft Iteratoren. Vermeide Indexzugriffe, wenn eine Iteratorlösung einfacher ist.", [example("if als Ausdruck", "let label = if score >= 10 { \"Bestanden\" } else { \"Weiter üben\" };", "Beide Zweige liefern denselben Typ."), example("match", "match score {\n    0 => println!(\"Start\"),\n    1..=9 => println!(\"Weiter\"),\n    _ => println!(\"Bestanden\"),\n}", "Der Unterstrich fängt alle übrigen Werte ab.")], "let score = 8;\n", "Ergänze eine vollständige match- oder if/else-Entscheidung und durchlaufe einen Vector.", "match\\s+score|if\\s+score\\s*>=\\s*10"),
  lesson("ownership", "04 · Besitz und Fehler", "Ownership und Borrowing", "rust", "Du erklärst Besitzübergabe und verwendest Referenzen zum Ausleihen.", "Jeder Wert hat einen Besitzer. Beim Verschieben (move) geht der Besitz weiter; der alte Name ist danach nicht mehr nutzbar. Eine Referenz leiht einen Wert aus. Viele unveränderliche Referenzen oder genau eine veränderliche Referenz verhindern gleichzeitige widersprüchliche Änderungen.", [example("Move", "let first = String::from(\"hi\");\nlet second = first;\n// first ist hier nicht mehr verwendbar", "String wird nicht einfach kopiert."), example("Ausleihen", "fn length(text: &String) -> usize {\n    text.len()\n}", "Die Referenz liest den String, ohne ihn zu übernehmen.")], "fn length(text: &String) -> usize {\n    text.len()\n}\n", "Schreibe eine Funktion, die einen String nur ausleiht, seine Länge zurückgibt und den Aufruferwert weiter nutzbar lässt.", "&String|&str|\\.len\\(\\)"),
  lesson("structs", "04 · Besitz und Fehler", "Structs, Enums und Methoden", "rust", "Du modellierst eigene Datentypen und beschreibst Zustände vollständig.", "Ein `struct` bündelt benannte Felder. Ein `enum` beschreibt eine feste Menge an Varianten und kann Daten tragen. Methoden stehen in einem `impl`-Block. Nutze Enums für Zustände statt frei kombinierbarer boolescher Flags.", [example("Struct", "struct Learner { name: String, score: u32 }", "Der Datentyp hat zwei benannte Felder."), example("Enum", "enum LoadState { Loading, Ready(String), Failed(String) }", "Jeder Zustand trägt die passenden Daten.")], "struct Learner { name: String, score: u32 }\n", "Erstelle einen Learner und ein Enum mit Loading, Ready und Failed.", "struct\\s+Learner|enum\\s+\\w+"),
  lesson("result", "04 · Besitz und Fehler", "Option, Result und Fehlerbehandlung", "rust", "Du behandelst fehlende Werte und fehlgeschlagene Operationen explizit.", "`Option<T>` ist `Some(value)` oder `None`; `Result<T, E>` ist `Ok(value)` oder `Err(error)`. `?` gibt einen Fehler an den Aufrufer weiter. Nutze `unwrap` nicht für unkontrollierte Eingaben, weil das Programm dabei abstürzen kann.", [example("Option prüfen", "if let Some(score) = scores.first() {\n    println!(\"{score}\");\n}", "Der Wert wird nur verwendet, wenn er vorhanden ist."), example("Result weitergeben", "fn read_config() -> Result<String, std::io::Error> {\n    std::fs::read_to_string(\"config.txt\")\n}", "Der Aufrufer muss den Fehler behandeln oder weiterreichen.")], "fn read_config() -> Result<String, std::io::Error> {\n    std::fs::read_to_string(\"config.txt\")\n}\n", "Behandle das Ergebnis einer Dateioperation ohne unwrap und gib eine verständliche Fehlerreaktion an.", "Result<|\\?;|if let Some"),
  lesson("modules", "05 · Anwenden", "Module, Tests und Cargo", "rust", "Du strukturierst Crates und prüfst Regeln mit Tests.", "Module strukturieren Namen und Sichtbarkeit; `pub` macht Elemente außerhalb sichtbar. Cargo verwaltet Build, Test und Abhängigkeiten. Unit-Tests können nahe am Code stehen. Clippy findet mögliche Fehler und Stilprobleme; Axum ist ein Webframework, das du erst nach Besitz, Result und asynchronen Grundlagen einführst.", [example("Unit-Test", "#[test]\nfn doubles_value() {\n    assert_eq!(double(4), 8);\n}", "assert_eq vergleicht erwartetes und tatsächliches Ergebnis."), example("Modul verwenden", "mod math;\nuse math::double;", "Die Datei math.rs kann das Modul enthalten.")], "fn double(value: i32) -> i32 { value * 2 }\n", "Schreibe Tests für 4 und 0 und erkläre, wozu Cargo, Clippy und Axum jeweils dienen.", "#\\[test\\]|assert_eq!|mod\\s+math"),
];

const sql: LessonBlueprint[] = [
  intro("orientation", "Was ist SQL?", "sql", "SQL ist eine deklarative Abfragesprache für relationale Datenbanken. Du beschreibst, welche Daten du lesen oder ändern möchtest; das Datenbanksystem plant die Ausführung. SQL ist keine allgemeine Programmiersprache und PostgreSQL ist ein konkretes Datenbanksystem, das SQL unterstützt.", [example("Abfrage beschreiben", "SELECT title FROM courses WHERE published = true;", "Du sagst, welche Spalte und Zeilen du erhalten möchtest."), example("Begriffe unterscheiden", "SQL = Sprache · PostgreSQL = Datenbanksystem · Tabelle = strukturierte Daten", "Ein System kann zusätzliche eigene SQL-Funktionen haben.")], "Was tust du mit einer deklarativen SELECT-Abfrage?", "Du beschreibst, welche Daten du sehen möchtest.", "Du schreibst dem Datenbanksystem jeden Festplattenzugriff vor.", "Du formatierst damit ausschließlich das Aussehen einer Webseite."),
  lesson("tables", "02 · Tabellen lesen", "Tabellen, Spalten, Zeilen und SELECT", "sql", "Du liest gezielt Spalten aus einer Tabelle.", "Eine Tabelle besteht aus Spalten mit definierten Typen und Zeilen mit einzelnen Datensätzen. `SELECT` nennt die gewünschten Spalten, `FROM` die Tabelle. Verwende explizite Spalten statt `SELECT *`, damit Abfragen und API-Antworten stabiler bleiben.", [example("Eine Spalte", "SELECT title\nFROM courses;", "Gibt für jede Zeile den Titel zurück."), example("Zwei Spalten", "SELECT id, title\nFROM courses;", "Die Ergebnisliste enthält nur diese beiden Spalten.")], "SELECT title\nFROM courses;\n", "Lies id, title und category aus courses und erkläre, was eine Zeile repräsentiert.", "SELECT\\s+id\\s*,\\s*title"),
  lesson("filter", "02 · Tabellen lesen", "Filtern, Sortieren und begrenzen", "sql", "Du filterst Daten gezielt und sortierst Ergebnisse eindeutig.", "`WHERE` filtert Zeilen, `ORDER BY` sortiert und `LIMIT` begrenzt die Ausgabe. `NULL` bedeutet unbekannt oder nicht vorhanden; verwende dafür `IS NULL`, nicht `= NULL`. Eine stabile Sortierung braucht bei Gleichständen oft eine zweite Spalte.", [example("Filtern", "SELECT id, title\nFROM courses\nWHERE published = true;", "Die Bedingung bleibt vor Sortierung und Limit relevant."), example("Sortieren und begrenzen", "SELECT id, title\nFROM courses\nORDER BY title, id\nLIMIT 10;", "id löst Gleichstände bei title deterministisch auf.")], "SELECT id, title\nFROM courses\n", "Finde veröffentlichte Kurse, sortiere nach Titel und begrenze auf zehn Ergebnisse.", "WHERE\\s+published|ORDER\\s+BY|LIMIT\\s+10"),
  lesson("aggregate", "03 · Abfragen verbinden", "Gruppieren und Aggregatfunktionen", "sql", "Du fasst mehrere Zeilen zu verständlichen Kennzahlen zusammen.", "`COUNT`, `SUM`, `AVG`, `MIN` und `MAX` berechnen Werte über Zeilen. `GROUP BY` bildet Gruppen; jede ausgewählte Spalte muss gruppiert oder aggregiert sein. `HAVING` filtert Gruppen nach der Aggregation; `WHERE` filtert vorher einzelne Zeilen.", [example("Zählen", "SELECT category, COUNT(*) AS course_count\nFROM courses\nGROUP BY category;", "Jede Kategorie erhält eine Anzahl."), example("Gruppe filtern", "SELECT category, COUNT(*)\nFROM courses\nGROUP BY category\nHAVING COUNT(*) >= 2;", "HAVING prüft das Gruppenergebnis.")], "SELECT category, COUNT(*) AS course_count\nFROM courses\n", "Zähle Kurse pro Kategorie und zeige nur Kategorien mit mindestens zwei Kursen.", "GROUP\\s+BY|HAVING\\s+COUNT"),
  lesson("joins", "03 · Abfragen verbinden", "JOINs und Beziehungen", "sql", "Du verbindest zusammengehörige Zeilen aus mehreren Tabellen.", "Ein Foreign Key verbindet etwa einen Kurs mit seinen Lektionen. `INNER JOIN` liefert passende Paare; `LEFT JOIN` behält alle Zeilen links und füllt fehlende rechte Werte mit NULL. Lege fest, ob die Beziehung eins-zu-eins, eins-zu-viele oder viele-zu-viele ist.", [example("INNER JOIN", "SELECT courses.title, lessons.title\nFROM courses\nJOIN lessons ON lessons.course_id = courses.id;", "Jede passende Kurs-Lektions-Kombination wird ausgegeben."), example("LEFT JOIN", "SELECT courses.title, lessons.id\nFROM courses\nLEFT JOIN lessons ON lessons.course_id = courses.id;", "Auch Kurse ohne Lektionen bleiben im Ergebnis.")], "SELECT courses.title, lessons.title\nFROM courses\n", "Verbinde Kurse und Lektionen und erkläre, wann du LEFT JOIN statt JOIN brauchst.", "JOIN\\s+lessons\\s+ON|LEFT\\s+JOIN"),
  lesson("mutations", "04 · Daten ändern", "INSERT, UPDATE und DELETE", "sql", "Du änderst gezielt Daten und schützt dich vor versehentlichen Massenänderungen.", "`INSERT` fügt Zeilen hinzu, `UPDATE` ändert und `DELETE` entfernt sie. Prüfe vor UPDATE und DELETE dieselbe Bedingung mit SELECT. Verwende in Anwendungen Parameter statt SQL-Text zusammenzukleben. Eine WHERE-Bedingung ist bei gezielten Änderungen entscheidend.", [example("Einfügen", "INSERT INTO courses (id, title)\nVALUES (1, 'SQL Grundlagen');", "Die Spaltenliste macht die Zuordnung verständlich."), example("Sicher aktualisieren", "UPDATE courses\nSET title = 'SQL Einstieg'\nWHERE id = 1;", "Ohne WHERE würden alle Zeilen betroffen sein.")], "UPDATE courses\nSET title = 'Neuer Titel'\n", "Füge eine Kurszeile ein und ergänze beim UPDATE eine eindeutige WHERE-Bedingung.", "INSERT\\s+INTO\\s+courses|UPDATE\\s+courses[\\s\\S]*WHERE\\s+id"),
  lesson("schema", "04 · Daten ändern", "Schema, Schlüssel und Constraints", "sql", "Du schützt Daten mit passenden Datentypen und Integritätsregeln.", "Ein Schema beschreibt Tabellen und Beziehungen. Primary Keys identifizieren Zeilen; Foreign Keys sichern Referenzen. `NOT NULL`, `UNIQUE` und `CHECK` verhindern ungültige Zustände. Constraints gehören in die Datenbank, weil mehrere Clients dieselben Regeln einhalten müssen.", [example("Tabelle mit Regeln", "CREATE TABLE learner (\n  id INTEGER PRIMARY KEY,\n  email TEXT NOT NULL UNIQUE,\n  age INTEGER CHECK (age >= 0)\n);", "Die Datenbank erzwingt eindeutige E-Mail und nichtnegative Werte."), example("Beziehung", "course_id INTEGER REFERENCES courses(id)", "Die referenzierte Kurszeile muss existieren.")], "CREATE TABLE learner (\n  id INTEGER PRIMARY KEY,\n  email TEXT NOT NULL UNIQUE\n);\n", "Ergänze einen Fremdschlüssel und eine CHECK-Regel für eine nichtnegative Punktzahl.", "REFERENCES\\s+courses|CHECK\\s*\\("),
  lesson("transactions", "05 · Zuverlässige Daten", "Transaktionen und Konsistenz", "sql", "Du führst zusammengehörige Änderungen als eine Einheit aus.", "Eine Transaktion bündelt Änderungen: `BEGIN`, danach Änderungen und schließlich `COMMIT`; bei einem Fehler kann `ROLLBACK` alles zurücknehmen. ACID beschreibt zentrale Transaktionseigenschaften. Transaktionen sollten kurz bleiben und Fehlerpfade berücksichtigen.", [example("Transaktion", "BEGIN;\nUPDATE accounts SET balance = balance - 10 WHERE id = 1;\nUPDATE accounts SET balance = balance + 10 WHERE id = 2;\nCOMMIT;", "Beide Änderungen werden zusammen bestätigt."), example("Fehler zurückrollen", "BEGIN;\nUPDATE courses SET published = false WHERE id = 7;\nROLLBACK;", "Die Änderung wird nicht dauerhaft übernommen.")], "BEGIN;\nUPDATE courses SET published = false WHERE id = 7;\n", "Beschreibe, wann du COMMIT und wann ROLLBACK verwendest.", "BEGIN;[\\s\\S]*ROLLBACK;|COMMIT;"),
  lesson("performance", "05 · Zuverlässige Daten", "Indizes, EXPLAIN und sichere Parameter", "sql", "Du prüfst Abfragen und nutzt Indizes gezielt.", "Ein Index beschleunigt manche Such- und Sortierzugriffe, kostet aber Speicher und verlangsamt Änderungen. `EXPLAIN` zeigt den geplanten Abfrageweg; `EXPLAIN ANALYZE` führt die Abfrage tatsächlich aus. In Anwendungen bindest du Werte als Parameter und gibst keine dynamischen Nutzereingaben ungeprüft als SQL-Bezeichner weiter.", [example("Parameter in PostgreSQL", "SELECT id, title FROM courses WHERE id = $1;", "Der Wert wird getrennt vom SQL-Text übergeben."), example("Plan ansehen", "EXPLAIN SELECT id FROM courses WHERE slug = 'intro';", "Prüfe, ob ein Scan oder Indexzugriff plausibel ist.")], "SELECT id, title FROM courses WHERE id = $1;\n", "Schreibe eine parametrisierte Abfrage und erkläre, warum ein Index nicht auf jede Spalte gehört.", "WHERE\\s+id\\s*=\\s*\\$1|EXPLAIN\\s+SELECT"),
];

const c: LessonBlueprint[] = [
  intro("orientation", "Was ist C?", "c", "C ist eine kompakte, kompilierte Programmiersprache für Betriebssysteme, Geräte, Laufzeitbibliotheken und systemnahe Programme. Sie bietet wenig automatische Schutzmechanismen; der Programmierer verwaltet Speicher und Grenzen daher sorgfältig. C und C++ sind verwandte, aber unterschiedliche Sprachen.", [example("Übersetzen", "C-Quelltext → C-Compiler → ausführbares Programm", "Compilerwarnungen helfen, problematische Stellen früh zu finden."), example("Ausgabe", "printf(\"Hallo C\\n\");", "printf stammt aus der C-Standardbibliothek.")], "Was unterscheidet C von einer höheren, speicherverwalteten Sprache?", "C überlässt dem Programmierer viele Entscheidungen zu Speicher und Datenzugriff.", "C verhindert automatisch jeden Zugriff außerhalb eines Arrays.", "C ist nur eine Schreibweise für SQL-Abfragen."),
  lesson("run", "02 · Grundsyntax", "main und printf", "c", "Du erkennst den Programmeinstieg und gibst formatierten Text aus.", "Ein C-Programm startet in `main`, die eine Ganzzahl zurückgibt. `#include <stdio.h>` bindet Deklarationen der Ein-/Ausgabebibliothek ein. `printf` verwendet Formatangaben; jede Formatangabe muss zum übergebenen Typ passen.", [example("Kleines Programm", "#include <stdio.h>\nint main(void) {\n  printf(\"Hallo C\\n\");\n  return 0;\n}", "0 signalisiert üblicherweise erfolgreichen Abschluss."), example("Zahl formatieren", "printf(\"Punkte: %d\\n\", score);", "%d passt zu int.")], "#include <stdio.h>\nint main(void) {\n  // Ausgabe ergänzen\n  return 0;\n}\n", "Gib eine Meldung und einen int-Wert mit passendem printf-Format aus.", "printf\\s*\\("),
  lesson("types", "02 · Grundsyntax", "Grundtypen, Variablen und sizeof", "c", "Du wählst Grundtypen und initialisierst Variablen vor ihrer Nutzung.", "C bietet `char`, Integer-Typen, Gleitkommatypen und `_Bool` beziehungsweise `bool` über `<stdbool.h>`. Die genaue Bitbreite einiger Typen hängt von Plattform und Implementierung ab. Initialisiere Variablen immer; `sizeof` liefert die Größe eines Typs in Bytes auf der aktuellen Plattform.", [example("Werte initialisieren", "int score = 12;\ndouble ratio = 0.75;\nbool ready = true;", "Für bool wird stdbool.h eingebunden."), example("Größe prüfen", "printf(\"%zu\\n\", sizeof(score));", "%zu ist das passende Format für size_t.")], "int score = 12;\n", "Lege int, double und bool an, initialisiere sie und gib score aus.", "\\bint\\s+score\\s*=|\\bbool\\s+\\w+"),
  lesson("conditions", "03 · Ablauf", "Bedingungen und Schleifen", "c", "Du schreibst vollständige Verzweigungen und begrenzte Schleifen.", "`if` prüft einen Ausdruck; `else` behandelt den anderen Fall. `for` und `while` wiederholen Anweisungen. `break` beendet eine Schleife vorzeitig, sollte aber nicht unverständlich verschachtelte Abläufe ersetzen. Prüfe Schleifengrenzen sorgfältig, besonders bei Arrays.", [example("Zwei Fälle", "if (score >= 10) {\n  puts(\"Bestanden\");\n} else {\n  puts(\"Weiter üben\");\n}", "puts hängt einen Zeilenumbruch an."), example("Zähler", "for (int i = 0; i < 3; i++) {\n  printf(\"%d\\n\", i);\n}", "Die Schleife gibt 0, 1 und 2 aus.")], "int score = 8;\n", "Ergänze if/else für 10 Punkte und eine for-Schleife von 0 bis 4.", "if\\s*\\([^)]*score\\s*>=\\s*10|for\\s*\\(int\\s+i\\s*=\\s*0"),
  lesson("arrays", "03 · Ablauf", "Arrays und Zeichenketten", "c", "Du greifst nur innerhalb eines Arrays zu und verstehst C-Strings.", "Ein Array speichert Elemente desselben Typs in zusammenhängendem Speicher und hat eine feste Länge. C prüft Indexgrenzen zur Laufzeit nicht automatisch. Eine C-Zeichenkette ist ein `char`-Array mit abschließendem Nullzeichen `\\0`; plane Platz dafür ein und nutze begrenzte Funktionen.", [example("Array durchlaufen", "int scores[] = {4, 8, 12};\nfor (size_t i = 0; i < 3; i++) printf(\"%d\\n\", scores[i]);", "Der letzte gültige Index ist 2."), example("Puffer mit Grenze", "char name[32];\nfgets(name, sizeof name, stdin);", "fgets begrenzt die gelesene Menge auf die Puffergröße.")], "int scores[] = {4, 8, 12};\n", "Laufe sicher durch alle Elemente und lies Text mit fgets in einen begrenzten Puffer.", "fgets\\s*\\(|sizeof\\s+name"),
  lesson("functions", "04 · Funktionen und Zeiger", "Funktionen und Zeiger", "c", "Du übergibst Werte und erkennst, wann eine Funktion eine Adresse benötigt.", "Parameter werden in C als Werte übergeben. Ein Zeiger enthält eine Adresse; mit `&` erhältst du eine Adresse, mit `*` greifst du auf den referenzierten Wert zu. Ein Zeiger muss auf ein gültiges Objekt zeigen; `NULL` bedeutet, dass kein Ziel vorhanden ist.", [example("Wert berechnen", "int double_value(int value) {\n  return value * 2;\n}", "Die Eingabe bleibt unverändert."), example("Über Zeiger ändern", "void increment(int *value) {\n  if (value != NULL) (*value)++;\n}", "Die Funktion prüft den Nullzeiger vor dem Zugriff.")], "int double_value(int value) {\n  return value * 2;\n}\n", "Schreibe eine Funktion mit Zeigerparameter, prüfe NULL und verändere den Wert sicher.", "\\*value|NULL|double_value\\s*\\("),
  lesson("structs", "04 · Funktionen und Zeiger", "Structs, Header und mehrere Dateien", "c", "Du gruppierst Daten und trennst Schnittstelle von Implementierung.", "`struct` gruppiert Felder zu einem Datensatz. Ein Header deklariert Funktionen und Typen; die `.c`-Datei enthält die Implementierung. Include Guards verhindern mehrfaches Einbinden. Die Linkphase verbindet übersetzte Dateien; Compiler und Linker melden unterschiedliche Fehler.", [example("Datensatz", "struct Learner {\n  const char *name;\n  int score;\n};", "Das struct legt hier nur die Form fest, nicht den Textspeicher."), example("Header Guard", "#ifndef LEARNER_H\n#define LEARNER_H\nvoid print_learner(void);\n#endif", "Die Präprozessordirektiven verhindern doppelte Deklarationen.")], "struct Learner {\n  const char *name;\n  int score;\n};\n", "Erstelle ein struct und beschreibe, wer den Speicher für ein referenziertes Textfeld besitzt.", "struct\\s+Learner|#ifndef\\s+"),
  lesson("memory", "05 · Anwenden", "Speicher, Tests und sichere Builds", "c", "Du verwaltest dynamischen Speicher und prüfst Fehlerpfade.", "`malloc` reserviert Speicher, `free` gibt ihn frei; jeder erfolgreiche Besitz braucht genau eine passende Freigabe. Prüfe `malloc` auf NULL und vermeide Use-after-free. Aktiviere hohe Compilerwarnungen und nutze Werkzeuge wie AddressSanitizer. Unity (C) ist ein Unit-Testframework, nicht die Unity-Spieleengine.", [example("Reservieren und prüfen", "int *values = malloc(count * sizeof *values);\nif (values == NULL) return 1;", "Prüfe Größenüberläufe und Freigabe im vollständigen Programm."), example("Testaussage", "TEST_ASSERT_EQUAL_INT(8, double_value(4));", "Der Test prüft konkretes Verhalten.")], "int *values = malloc(3 * sizeof *values);\n", "Prüfe reservierten Speicher auf NULL, verwende ihn und gib ihn auf jedem passenden Pfad frei.", "malloc\\s*\\(|free\\s*\\("),
];

const kotlin: LessonBlueprint[] = [
  intro("orientation", "Was ist Kotlin?", "kotlin", "Kotlin ist eine statisch typisierte Programmiersprache, die häufig auf der JVM, für Android sowie für Server und Multiplattformprojekte genutzt wird. Kotlin kann mit Java-Bibliotheken zusammenarbeiten, ist aber eine eigene Sprache. Die Kotlin-Standardbibliothek und Android-APIs haben unterschiedliche Aufgaben.", [example("Kotlin auf der JVM", "Kotlin-Quelltext → Kotlin-Compiler → JVM-Bytecode", "Kotlin kann vorhandene Java-Bibliotheken aufrufen."), example("Konsolenausgabe", "println(2 + 3)", "Die Ausgabe ist 5.")], "Was stimmt über Kotlin und Java?", "Kotlin ist eine eigene Sprache und kann mit Java auf der JVM zusammenarbeiten.", "Kotlin ist nur eine neue Schriftart für Java-Code.", "Kotlin läuft nur als SQL-Abfrage im Browser."),
  lesson("run", "02 · Werte und Typen", "val, var und Typableitung", "kotlin", "Du unterscheidest unveränderliche Referenzen von neu zuweisbaren Variablen.", "`val` kann nur einmal zugewiesen werden; `var` erlaubt Neuzuweisung. Der Compiler leitet den Typ häufig ab. Unveränderliche Referenzen verhindern nicht automatisch, dass ein veränderliches Objekt intern geändert wird. Bevorzuge val, wenn kein neuer Wert zugewiesen werden muss.", [example("Unveränderliche Bindung", "val learner = \"Mina\"\nval score: Int = 12", "Der Typ kann explizit oder abgeleitet angegeben werden."), example("Neuzuweisung", "var attempts = 0\nattempts += 1", "var ist für einen veränderlichen Zähler passend.")], "val score: Int = 12\n", "Lege name mit val und einen Zähler mit var an und gib beide aus.", "\\bval\\s+name|\\bvar\\s+attempts"),
  lesson("null", "02 · Werte und Typen", "Null-Sicherheit und sichere Aufrufe", "kotlin", "Du behandelst fehlende Werte, ohne unkontrollierte Nullfehler zu erzeugen.", "Ein nicht-nullbarer Typ wie `String` kann nicht null enthalten. `String?` darf null sein. `?.` führt einen Zugriff nur bei vorhandenem Wert aus; `?:` liefert einen Standardwert. `!!` erzwingt einen Zugriff und kann abstürzen, deshalb nur bei wirklich bewiesener Nicht-Null-Bedingung.", [example("Sicherer Zugriff", "val length = name?.length", "length ist ebenfalls nullable."), example("Standardwert", "val displayName = name ?: \"Gast\"", "Elvis setzt einen Ersatzwert, wenn name null ist.")], "val name: String? = null\n", "Ermittle die Länge eines optionalen Namens und verwende einen sinnvollen Standardwert.", "\\?\\.|\\?:"),
  lesson("flow", "03 · Ablauf und Sammlungen", "if, when und Schleifen", "kotlin", "Du steuerst den Ablauf mit Ausdrücken und durchläufst Sammlungen.", "`if` und `when` können Werte liefern. `for` durchläuft eine Range oder Sammlung; `while` läuft bis eine Bedingung falsch wird. `when` ist oft übersichtlicher als viele verschachtelte if-Blöcke und kann den Compiler bei vollständigen sealed-Varianten unterstützen.", [example("if als Wert", "val label = if (score >= 10) \"Bestanden\" else \"Weiter üben\"", "Der Ausdruck liefert in beiden Zweigen einen String."), example("when", "val label = when (score) {\n  in 0..9 -> \"Weiter\"\n  else -> \"Bestanden\"\n}", "Bereiche können als Fälle geprüft werden.")], "val score = 8\n", "Ergänze eine when-Entscheidung und durchlaufe eine Liste mit for.", "when\\s*\\(|for\\s*\\(\\w+\\s+in"),
  lesson("collections", "03 · Ablauf und Sammlungen", "Listen, Maps und Transformationen", "kotlin", "Du wählst veränderliche oder unveränderliche Sammlungen und filterst Werte.", "`listOf` erstellt eine nicht veränderbare Liste über diese Referenz, `mutableListOf` eine Liste mit Änderungsoperationen. `map` transformiert jedes Element, `filter` behält passende Werte. Wähle nicht veränderbare Daten, wenn eine spätere Änderung nicht nötig ist.", [example("Liste", "val scores = listOf(4, 8, 12)", "Die Liste ist über diese Referenz nicht veränderbar."), example("Filter und map", "val passed = scores.filter { it >= 10 }.map { it * 2 }", "Die Werte 10 oder höher werden gewählt und verdoppelt.")], "val scores = listOf(4, 8, 12)\n", "Filtere bestandene Punktzahlen und verwandle sie anschließend in eine Liste verdoppelter Werte.", "\\.filter\\s*\\{|\\.map\\s*\\{"),
  lesson("functions", "04 · Typen und Funktionen", "Funktionen, Default- und Named-Argumente", "kotlin", "Du schreibst kleine Funktionen mit klaren Parametern und Rückgaben.", "`fun` definiert eine Funktion. Der Rückgabetyp steht nach dem Doppelpunkt; bei einem Ausdruck kann Kotlin ihn oft ableiten. Default-Argumente ersparen überladene Varianten; benannte Argumente machen Aufrufe bei mehreren Parametern lesbarer.", [example("Funktion", "fun double(value: Int): Int = value * 2", "Der Ausdruck nach = ist der Rückgabewert."), example("Default-Argument", "fun greet(name: String = \"Gast\") = \"Hallo, $name\"", "Der Aufrufer kann den Standardnamen übernehmen.")], "fun add(a: Int, b: Int): Int = a + b\n", "Schreibe add und greet mit einem Default-Argument und teste mehrere Aufrufe.", "fun\\s+add\\s*\\(|fun\\s+greet\\s*\\("),
  lesson("classes", "04 · Typen und Funktionen", "Klassen, Data Classes und Sealed Types", "kotlin", "Du modellierst Daten und Zustände mit passenden Kotlin-Typen.", "Eine `data class` liefert nützliche Wertoperationen wie copy und Gleichheit. `sealed class` oder `sealed interface` begrenzt bekannte Varianten; `when` kann diese Varianten vollständig behandeln. Nutze Klassen, wenn ein Typ eigene Identität oder Regeln braucht.", [example("Data Class", "data class Course(val id: String, val title: String)", "Unveränderliche val-Felder passen gut zu einem Datensatz."), example("Sealed State", "sealed interface LoadState\ndata object Loading : LoadState\ndata class Ready(val title: String) : LoadState", "Der Zustand kann nicht beliebig neue Varianten erhalten.")], "data class Course(val id: String, val title: String)\n", "Erstelle einen LoadState mit Loading und Ready und behandle beide im when-Ausdruck.", "data\\s+class\\s+Course|sealed\\s+interface"),
  lesson("async", "05 · Anwenden", "Tests, Coroutines, Android und Ktor", "kotlin", "Du ordnest Kotlin-Werkzeuge ein und verstehst asynchrone Arbeit.", "Coroutines ermöglichen strukturierte asynchrone Arbeit; `suspend` markiert Funktionen, die pausieren können. Android APIs bauen mobile Anwendungen, Ktor Server oder Clients. Unit-Tests prüfen Regeln unabhängig von UI. `suspend` bedeutet nicht automatisch einen neuen Thread; Dispatcher und Lebensdauer müssen passend gewählt werden.", [example("Suspend-Funktion", "suspend fun loadCourse(id: String): Course {\n  return repository.get(id)\n}", "Die Funktion kann in einem Coroutine-Kontext auf Arbeit warten."), example("Testidee", "assertEquals(8, double(4))", "Prüfe Randfälle getrennt von Android-Oberfläche oder Server.")], "suspend fun loadCourse(id: String): Course {\n  return repository.get(id)\n}\n", "Schreibe einen Test für eine Funktion und beschreibe, wann Coroutines, Android oder Ktor gebraucht werden.", "suspend\\s+fun|assertEquals\\s*\\("),
];

const swift: LessonBlueprint[] = [
  intro("orientation", "Was ist Swift?", "swift", "Swift ist eine statisch typisierte Programmiersprache, die vor allem für Apple-Plattformen und Serveranwendungen verwendet wird. Der Compiler übersetzt Swift in nativen Code. SwiftUI ist ein UI-Framework, XCTest ein Testwerkzeug; beides sind Ergänzungen zur Sprache.", [example("Programmablauf", "Swift-Quelltext → Swift-Compiler → Programm", "Der Compiler prüft Typen und erzeugt ausführbaren Code."), example("Konsolenausgabe", "print(2 + 3)", "Die Ausgabe ist 5.")], "Wo wird Swift häufig eingesetzt?", "Für Programme und Apps im Apple-Ökosystem sowie auch für Server.", "Als Datenbankabfragesprache für alle Webseiten.", "Ausschließlich zum Formatieren von HTML-Elementen."),
  lesson("run", "02 · Werte und Typen", "let, var und Typen", "swift", "Du verwendest konstante Bindungen und erkennst Swift-Grundtypen.", "`let` bindet einen unveränderlichen Wert; `var` erlaubt Änderung. Der Compiler leitet häufig den Typ ab. `Int`, `Double`, `Bool` und `String` sind zentrale Typen. Swift wandelt Zahlen nicht immer automatisch um; konvertiere bewusst.", [example("Werte", "let learner = \"Mina\"\nvar score: Int = 12", "score darf neu zugewiesen werden, learner nicht."), example("Konvertieren", "let ratio = Double(score) / 5.0", "Die explizite Umwandlung macht den Typ klar.")], "let learner = \"Mina\"\nvar score: Int = 12\n", "Lege Text und Zahl an, erhöhe score und berechne einen Double-Wert.", "\\b(?:let|var)\\s+score|Double\\s*\\("),
  lesson("optionals", "02 · Werte und Typen", "Optionals und sichere Unwraps", "swift", "Du behandelst Werte, die fehlen können.", "Ein Optional wie `String?` enthält entweder einen Wert oder `nil`. `if let` bindet den Wert nur, wenn er vorhanden ist. `??` liefert einen Standardwert. Ein erzwungenes `!` kann zur Laufzeit abstürzen und ist nur vertretbar, wenn die Nicht-Nil-Bedingung garantiert ist.", [example("if let", "if let name = optionalName {\n  print(name.count)\n}", "name ist innerhalb des Blocks sicher nicht nil."), example("Standardwert", "let displayName = optionalName ?? \"Gast\"", "Der Ausdruck ergibt immer einen String.")], "let optionalName: String? = nil\n", "Lies die Länge mit if let und erzeuge einen Standardnamen mit ??.", "if\\s+let\\s+|\\?\\?"),
  lesson("flow", "03 · Ablauf und Collections", "Bedingungen, switch und Schleifen", "swift", "Du behandelst Fälle vollständig und durchläufst Werte.", "`if` wählt einen Zweig. `switch` muss alle Fälle abdecken oder einen `default` enthalten. `for-in` durchläuft Bereiche und Collections. Swift-`switch` fällt nicht automatisch in den nächsten Fall durch; mehrere Fälle können gemeinsam angegeben werden.", [example("Grenzwert", "if score >= 10 {\n  print(\"Bestanden\")\n} else {\n  print(\"Weiter üben\")\n}", "Die Bedingung ergibt einen Boolean."), example("Switch", "switch score {\ncase 0..<10: print(\"Weiter\")\ndefault: print(\"Bestanden\")\n}", "0..<10 schließt die obere Grenze 10 aus.")], "let score = 8\n", "Ergänze einen switch für Punktzahlen und durchlaufe ein Array mit for-in.", "switch\\s+score|for\\s+\\w+\\s+in"),
  lesson("collections", "03 · Ablauf und Collections", "Arrays, Dictionaries und Sets", "swift", "Du wählst eine Collection passend zu Ordnung und Eindeutigkeit.", "Arrays bewahren Reihenfolge und erlauben Duplikate. Dictionaries speichern Schlüssel-Wert-Paare; Sets speichern eindeutige Werte ohne feste Reihenfolge. `map`, `filter` und `reduce` beschreiben Transformationen, Auswahl und Zusammenfassung.", [example("Array filtern", "let scores = [4, 8, 12]\nlet passed = scores.filter { $0 >= 10 }", "passed enthält nur 12."), example("Dictionary", "let points = [\"Mina\": 12]\nlet score = points[\"Mina\"]", "Der Zugriff liefert ein Optional, weil der Schlüssel fehlen kann.")], "let scores = [4, 8, 12]\n", "Filtere Werte ab 10 und greife auf einen Dictionary-Wert mit sicherer Nil-Behandlung zu.", "\\.filter\\s*\\{|\\?\\?"),
  lesson("functions", "04 · Typen und Funktionen", "Funktionen, Parameter und Rückgaben", "swift", "Du schreibst Funktionen mit klaren Parametern und Rückgabewerten.", "Eine Funktion wird mit `func` definiert. Swift unterscheidet oft externe Argumentlabels vom internen Parameternamen. Ein Rückgabetyp steht nach `->`. Kleine Funktionen mit klarer Aufgabe lassen sich einfacher testen.", [example("Funktion", "func double(_ value: Int) -> Int {\n  return value * 2\n}", "Der Unterstrich bedeutet: Beim Aufruf braucht value kein Label."), example("Guard", "func greet(_ name: String?) -> String {\n  guard let name else { return \"Hallo, Gast\" }\n  return \"Hallo, \\(name)\"\n}", "guard beendet frühzeitig, wenn eine Voraussetzung fehlt.")], "func add(_ a: Int, _ b: Int) -> Int {\n  return a + b\n}\n", "Schreibe add und eine greet-Funktion, die einen fehlenden Namen sicher behandelt.", "func\\s+add\\s*\\(|guard\\s+let"),
  lesson("structs", "04 · Typen und Funktionen", "Structs, Enums und Protokolle", "swift", "Du modellierst Werte und verbindliche Schnittstellen.", "Structs sind Werttypen und eignen sich für viele Datenmodelle. Enums beschreiben eine abgeschlossene Auswahl und können assoziierte Werte tragen. Protokolle definieren Fähigkeiten, die verschiedene Typen erfüllen können. Wähle Referenztypen wie class, wenn Identität oder geteilte Veränderlichkeit nötig ist.", [example("Struct", "struct Course {\n  let id: String\n  var title: String\n}", "Kopien eines Structs sind Werte und keine gemeinsame Klassenreferenz."), example("Enum mit Daten", "enum LoadState { case loading, ready(String), failed(Error) }", "Jeder Fall kann passende Zusatzdaten enthalten.")], "struct Course {\n  let id: String\n  var title: String\n}\n", "Erstelle ein Enum mit loading, ready und failed und behandle alle Fälle im switch.", "enum\\s+LoadState|switch\\s+state"),
  lesson("async", "05 · Anwenden", "async/await, SwiftUI und XCTest", "swift", "Du ordnest asynchrone Arbeit, UI und Tests ein.", "`async` markiert eine asynchrone Funktion; `await` wartet an einer möglichen Unterbrechungsstelle. SwiftUI beschreibt Oberflächen aus Zustand und Darstellung. XCTest prüft Verhalten. UI-Aktualisierungen gehören auf den passenden Actor, häufig `MainActor`; blockiere die Oberfläche nicht mit langer Arbeit.", [example("Asynchron laden", "func loadCourse() async throws -> Course {\n  try await client.fetchCourse()\n}", "Fehler werden mit throws sichtbar weitergereicht."), example("SwiftUI Ansicht", "struct CourseView: View {\n  var body: some View { Text(\"Kurse\") }\n}", "Die View beschreibt, was für den aktuellen Zustand dargestellt wird.")], "func loadCourse() async throws -> Course {\n  try await client.fetchCourse()\n}\n", "Teste eine kleine Funktion mit XCTest und beschreibe, wofür SwiftUI im Vergleich zur Sprache zuständig ist.", "async\\s+throws|XCTAssert|struct\\s+\\w+View\\s*:\\s*View"),
];

const gdscript: LessonBlueprint[] = [
  intro("orientation", "Was ist GDScript?", "plaintext", "GDScript ist die Skriptsprache von Godot. Sie ist für kurze, gut lesbare Spielregeln entwickelt. Der Editor hilft mit Fehlermeldungen, Autovervollständigung und direkt startbaren Szenen. Im Sprachkurs lernst du Werte, Entscheidungen, Schleifen und Funktionen. Nodes und Szenen setzt du danach im Spielekurs praktisch ein.", [example("Einfache Idee", "Eingabe → Spielregel → neuer Zustand", "Die Sprache drückt die Regel aus; die Engine zeigt das Ergebnis.", "plaintext")], "Was beschreibt GDScript?", "Spielregeln und Abläufe als lesbare Anweisungen", "Nur Farben einer Website", "Eine Datenbankabfrage ohne Godot"),
  lesson("run", "02 · Erste Schritte", "Ausgabe und Einrückung", "gdscript", "Du schreibst eine Anweisung und erkennst einen eingerückten Block.", "GDScript verwendet Einrückung, um zusammengehörige Anweisungen zu markieren. print zeigt Werte in Godots Ausgabe. Beginne mit einem Text und einer Rechnung. Achte darauf, dass Code in einer Funktion steht, die beim Start aufgerufen wird.", [example("Erste Ausgabe", "func _ready():\n    print('Hallo Spiel')\n    print(2 + 3)", "Beim Start der Szene erscheinen Text und Zahl im Ausgabefenster.")], "func _ready():\n    pass\n", "Gib beim Start einen Text und eine Rechnung aus.", "print\\s*\\("),
  lesson("values", "02 · Erste Schritte", "Variablen und Datentypen", "gdscript", "Du speicherst Spielwerte unter verständlichen Namen.", "var erstellt eine veränderliche Variable, const einen festen Wert. Du kannst einen Typ angeben, etwa int oder String. Nutze Namen wie score und speed; ein unklarer Name erschwert später die Fehlersuche.", [example("Punkte und Geschwindigkeit", "var score: int = 0\nconst MAX_SCORE: int = 5\nvar speed: float = 120.0", "Die Typangaben beschreiben erlaubte Werte.")], "var score: int = 0\n", "Lege eine Punktzahl, Geschwindigkeit und eine feste Obergrenze an.", "var\\s+speed|const\\s+MAX_SCORE"),
  lesson("conditions", "03 · Ablauf steuern", "Entscheidungen mit if und else", "gdscript", "Du behandelst Gewinn und Weiterspielen als getrennte Fälle.", "Eine Bedingung prüft true oder false. Der eingerückte Block läuft nur bei passendem Ergebnis. Prüfe den Grenzwert bewusst: Bei genau fünf Punkten soll das Spiel gewonnen sein.", [example("Zwei Fälle", "if score >= 5:\n    print('Gewonnen')\nelse:\n    print('Weiter sammeln')", "Genau ein Zweig läuft.")], "var score = 4\n", "Schreibe eine Gewinnprüfung für mindestens fünf Punkte mit else-Fall.", "if\\s+score\\s*>=\\s*5|else:"),
  lesson("loops", "03 · Ablauf steuern", "Schleifen und Listen", "gdscript", "Du verarbeitest mehrere Spielwerte ohne kopierte Anweisungen.", "Ein Array hält geordnete Werte. for durchläuft die Werte nacheinander; range erzeugt eine Zahlenfolge. Prüfe auch eine leere Liste, bei der die Schleife keinen Durchlauf hat.", [example("Punkte zählen", "var scores = [2, 4, 3]\nvar total = 0\nfor value in scores:\n    total += value\nprint(total)", "Das Ergebnis ist 9.")], "var scores = [2, 4, 3]\n", "Addiere die Werte mit einer for-Schleife und prüfe eine leere Liste.", "for\\s+\\w+\\s+in\\s+scores"),
  lesson("functions", "04 · Wiederverwenden", "Funktionen, Parameter und Rückgabe", "gdscript", "Du kapselst eine Spielregel in einer testbaren Funktion.", "Eine Funktion erhält Parameter und kann mit return ein Ergebnis liefern. Schreibe add_score für eine Punktzahl und einen Zuwachs. Prüfe 0, einen positiven Wert und einen ungültigen negativen Zuwachs.", [example("Punkte berechnen", "func add_score(current: int, amount: int) -> int:\n    return current + amount", "Die Funktion verändert keinen globalen Spielzustand.")], "func add_score(current: int, amount: int) -> int:\n    pass\n", "Gib die neue Punktzahl zurück und behandle einen negativen Zuwachs.", "func\\s+add_score|return"),
  lesson("collections", "04 · Wiederverwenden", "Dictionaries und Zustände", "gdscript", "Du ordnest benannte Werte einem Spielzustand zu.", "Ein Dictionary verbindet Schlüssel mit Werten. Nutze es für einen kleinen Spielstand, aber prüfe fehlende Schlüssel mit get. Für größere Projekte helfen später eigene Klassen und Engine-Objekte; zuerst musst du die Datenform verstehen.", [example("Spielstand", "var state = {'score': 3, 'lives': 2}\nprint(state.get('score', 0))", "get liefert bei fehlendem Schlüssel den Standardwert.")], "var state = {'score': 0}\n", "Ergänze lives und lies einen möglicherweise fehlenden Wert sicher aus.", "state\\.get|lives"),
  lesson("project", "05 · Eigenes Sprachprojekt", "Projekt: Punktestand ohne Engine-Abhängigkeit", "gdscript", "Du verbindest Werte, Bedingungen, Schleifen und Funktionen.", "Schreibe eine Funktion, die Sammelwerte addiert und entscheidet, ob das Ziel erreicht ist. Teste eine leere Liste, einen Wert genau am Ziel und einen Wert darüber. Erkläre jede verwendete Sprachregel, bevor du sie im Spielekurs in eine Szene einbaust.", [example("Ziel prüfen", "func won(scores: Array[int], target: int) -> bool:\n    var total = 0\n    for value in scores:\n        total += value\n    return total >= target", "Die Regel ist unabhängig von einer Godot-Szene prüfbar.")], "func won(scores: Array[int], target: int) -> bool:\n    pass\n", "Vervollständige won und prüfe drei Eingaben.", "for\\s+\\w+\\s+in\\s+scores|return\\s+total", "Erst die Regel verstehen, dann mit Engine-Objekten verbinden."),
];

const webDevelopment: LessonBlueprint[] = [
  intro("orientation", "Was ist Frontend-Entwicklung?", "plaintext", "In diesem Kurs baust du ausschließlich das, was Menschen im Browser sehen und bedienen. HTML beschreibt Bedeutung und Struktur, CSS die Gestaltung und JavaScript das Verhalten. TypeScript kann JavaScript beim Entwickeln mit Typen ergänzen. Später setzt du diese Bausteine gemeinsam in einer Website und mit einem UI-Framework ein. Daten können von einer vorhandenen API kommen; einen Server programmierst du im Backendkurs.", [example("Drei Aufgaben", "HTML = Inhalt · CSS = Darstellung · JavaScript = Verhalten", "Ein Button braucht Bedeutung, Gestaltung und gegebenenfalls eine Aktion."), example("Dein Projekt", "Skizze → HTML → CSS → Interaktion → Tests → Veröffentlichung", "Jeder Schritt macht die Website benutzbarer.")], "Welche Aufgabe hat HTML?", "HTML beschreibt Bedeutung und Struktur des Inhalts.", "HTML führt alle Datenbankabfragen des Servers aus.", "HTML legt ausschließlich Farben und Abstände fest."),
  lesson("html", "02 · Struktur", "Semantisches HTML", "html", "Du strukturierst Inhalt mit Elementen, die ihre Bedeutung ausdrücken.", "HTML-Elemente bestehen oft aus öffnendem Tag, Inhalt und schließendem Tag. Semantische Elemente wie `main`, `nav`, `article` und `button` helfen Browsern, Assistenztechnik und Suchmaschinen. Wähle ein Element nach seiner Aufgabe, nicht nach seinem Standardaussehen.", [example("Seitenstruktur", "<main>\n  <article>\n    <h1>Mein Lernprojekt</h1>\n    <p>Ich baue eine kleine Webseite.</p>\n  </article>\n</main>", "main enthält den Hauptinhalt; article ist ein eigenständiger Beitrag."), example("Link und Aktion", "<a href=\"/kurse\">Kurse ansehen</a>\n<button type=\"button\">Start</button>", "Ein Link navigiert; ein Button löst eine Aktion aus.")], "<main>\n  <h1>Mein Projekt</h1>\n</main>\n", "Baue eine semantische Seite mit nav, main, Überschrift, Artikel und einem echten Link.", "<main|<nav|<article"),
  lesson("forms", "02 · Struktur", "Formulare und Barrierefreiheit", "html", "Du erstellst Formulare mit beschrifteten Eingaben und verständlichen Aktionen.", "Jedes Eingabefeld braucht eine programmatisch zugeordnete Beschriftung. Ein Placeholder ersetzt kein Label. Verwende passende Eingabetypen und Fehlermeldungen in Textform; verlasse dich nicht allein auf Farbe. Tastaturbedienung und sichtbarer Fokus gehören zur Grundfunktion.", [example("Beschriftetes Feld", "<label for=\"email\">E-Mail-Adresse</label>\n<input id=\"email\" name=\"email\" type=\"email\" required>", "for und id verbinden Beschriftung und Eingabe."), example("Fehlermeldung", "<p id=\"email-error\">Bitte gib eine gültige Adresse ein.</p>", "Ein verständlicher Text benennt den Fehler und den nächsten Schritt.")], "<form>\n  <!-- beschriftetes Eingabefeld ergänzen -->\n</form>\n", "Erstelle ein barrierearm beschriftetes Formular für E-Mail und Nachricht.", "<label|type=\\\"email\\\""),
  lesson("css", "03 · Gestaltung", "CSS-Kaskade und Selektoren", "css", "Du wählst Elemente gezielt aus und verstehst, welche Regel gewinnt.", "CSS-Regeln bestehen aus Selektor und Deklarationen. Die Kaskade berücksichtigt Herkunft, Wichtigkeit, Spezifität und Reihenfolge. Beginne mit einfachen Klassen statt komplizierter Selektoren. Vermeide viele `!important`-Regeln, weil sie spätere Änderungen erschweren.", [example("Klasse gestalten", ".card {\n  padding: 1rem;\n  border-radius: 1rem;\n}", "Die Klasse card kann gezielt wiederverwendet werden."), example("CSS-Variablen", ":root { --brand: #1769e0; }\n.button { background: var(--brand); }", "Eine Variable hält wiederkehrende Werte konsistent.")], ".card {\n  padding: 1rem;\n}\n", "Gestalte eine Karte mit Klasse, Farbe, Innenabstand und einer wiederverwendbaren CSS-Variable.", "\\.card\\s*\\{|var\\(--brand\\)"),
  lesson("layout", "03 · Gestaltung", "Boxmodell, Flexbox und Grid", "css", "Du legst responsive Layouts mit passenden CSS-Werkzeugen an.", "Jedes Element hat Inhalt, Innenabstand, Rahmen und Außenabstand. `box-sizing: border-box` macht die Breitenberechnung meist leichter. Flexbox ordnet Elemente entlang einer Achse; Grid eignet sich für zweidimensionale Raster. Nutze flexible Größen und prüfe schmale Bildschirme.", [example("Boxmodell", "* { box-sizing: border-box; }\n.card { padding: 1rem; }", "Die angegebene Breite umfasst Innenabstand und Rahmen."), example("Grid", ".course-list {\n  display: grid;\n  grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr));\n  gap: 1rem;\n}", "Das Raster passt die Spaltenzahl an den verfügbaren Platz an.")], ".course-list {\n  display: grid;\n  gap: 1rem;\n}\n", "Erstelle ein responsives Kartenraster und erkläre den Unterschied zwischen Flexbox und Grid.", "display:\\s*grid|display:\\s*flex"),
  lesson("responsive", "03 · Gestaltung", "Responsive Design und Kontrast", "css", "Du machst Layouts auf kleinen und großen Bildschirmen lesbar.", "Mobile-first beginnt mit einem einfachen Layout und erweitert es über Media Queries. Vermeide feste Breiten, die Inhalte abschneiden. Schrift, Kontrast, Fokus und Touch-Zielgrößen beeinflussen Nutzbarkeit. Prüfe echte Text-Hintergrund-Kombinationen auch im dunklen und hellen Modus.", [example("Media Query", "@media (min-width: 48rem) {\n  .layout { grid-template-columns: 1fr 1fr; }\n}", "Ab 48rem stehen zwei Spalten zur Verfügung."), example("Flexible Breite", ".content { width: min(100% - 2rem, 70rem); margin-inline: auto; }", "Der Inhalt bleibt schmal genug zum Lesen.")], ".content {\n  width: min(100% - 2rem, 70rem);\n  margin-inline: auto;\n}\n", "Passe ein Einspaltenlayout ab einer passenden Breite an zwei Spalten an.", "@media\\s*\\(|width:\\s*min\\("),
  lesson("javascript", "04 · Verhalten", "DOM, Ereignisse und sichere Textausgabe", "javascript", "Du reagierst auf Aktionen, ohne Nutzereingaben als HTML auszuführen.", "Das DOM ist die strukturierte Darstellung des HTML-Dokuments im Browser. `querySelector` findet Elemente; Ereignislistener reagieren auf Klicks oder Eingaben. Verwende `textContent`, um Text einzusetzen. `innerHTML` mit nicht vertrauenswürdigen Daten kann Cross-Site-Scripting ermöglichen.", [example("Klickereignis", "button.addEventListener('click', () => {\n  message.textContent = 'Gestartet';\n});", "Die Funktion läuft erst beim Klick."), example("Eingabe anzeigen", "output.textContent = input.value.trim();", "Text wird als Text eingefügt, nicht als HTML interpretiert.")], "button.addEventListener('click', () => {\n  // Textausgabe aktualisieren\n});\n", "Reagiere auf einen Klick und gib einen Text sicher über textContent aus.", "addEventListener\\s*\\(|textContent\\s*="),
  lesson("network", "04 · Verhalten", "HTTP, Fetch und Ladezustände", "javascript", "Du fragst Daten ab und behandelst Lade-, Erfolgs- und Fehlerfälle.", "Fetch sendet eine HTTP-Anfrage und liefert ein Promise. Ein HTTP-Fehler wie 404 verwirft das Promise nicht automatisch; prüfe `response.ok`. Zeige Lade- und Fehlermeldungen und prüfe Daten, bevor du sie als Inhalt verwendest.", [example("API abfragen", "const response = await fetch('/api/courses');\nif (!response.ok) throw new Error('Anfrage fehlgeschlagen');\nconst courses = await response.json();", "Statusprüfung und JSON-Parsing sind getrennte Schritte."), example("Zustände", "Laden → Daten anzeigen\nFehler → verständliche Meldung\nLeer → Hinweis auf fehlende Ergebnisse", "Eine Oberfläche sollte alle drei Fälle abbilden.")], "async function loadCourses() {\n  // Fetch und Statusprüfung ergänzen\n}\n", "Hole eine Kursliste, prüfe response.ok und zeige einen Fehlerzustand.", "await\\s+fetch|response\\.ok"),
  lesson("frameworks", "05 · Projekt", "Komponenten, React und Veröffentlichung", "javascript", "Du ordnest Frameworks ein und veröffentlichst eine kleine zugängliche Webseite.", "Komponenten teilen eine Oberfläche in wiederverwendbare Teile. React ist eine JavaScript-Bibliothek, die UI aus Komponenten und Zustand aufbaut. Sie ersetzt HTML, CSS oder Browsergrundlagen nicht. Vor Veröffentlichung prüfst du Links, Tastaturbedienung, Ladezustände und mobile Ansichten.", [example("Wiederverwendbare Komponente", "function CourseCard({ title }) {\n  return <article><h2>{title}</h2></article>;\n}", "Eine Komponente erhält Daten über Props."), example("Webveröffentlichung", "Quellcode → Build → statische Dateien / Server → Domain", "Frontend- und Backend-Veröffentlichung sind unterschiedliche Schritte.")], "function CourseCard({ title }) {\n  return <article><h2>{title}</h2></article>;\n}\n", "Baue eine Kurskarte aus Daten, prüfe Tastatur und schmale Ansicht und erkläre, wann ein UI-Framework hilft.", "function\\s+CourseCard|<article>"),
];

const backend: LessonBlueprint[] = [
  intro("orientation", "Was ist ein Backend?", "javascript", "Ein Backend ist der Teil einer Anwendung, der auf einem Server läuft. Es nimmt Anfragen entgegen, prüft Eingaben und Berechtigungen, führt Geschäftsregeln aus und verwaltet Daten. Der Browser ist ein Client; eine API ist ein vereinbarter Zugang zu Backend-Funktionen. Ein Backend kann auch ohne sichtbare Webseite arbeiten.", [example("Anfrageweg", "Client → HTTP-Anfrage → Backend-Regeln → Datenbank → HTTP-Antwort", "Jeder Schritt muss Fehler und Berechtigungen berücksichtigen."), example("API-Antwort", "GET /api/courses → 200 OK + JSON", "Der Statuscode und Antwortformat gehören zum API-Vertrag.")], "Welche Aufgabe hat ein Backend?", "Es verarbeitet Anfragen, setzt Regeln durch und liefert Antworten.", "Es ist nur das Farbschema einer Browserseite.", "Es ist ein lokaler Editor, der ohne Server Daten speichert."),
  lesson("http", "02 · HTTP und Schnittstellen", "HTTP-Methoden, Pfade und Statuscodes", "plaintext", "Du beschreibst eine API-Anfrage samt erwarteter Antwort.", "HTTP überträgt Anfragen und Antworten. Methode und Pfad beschreiben die gewünschte Aktion; Header enthalten Metadaten, der Body optional Daten. Häufige Statuscodes: 200 Erfolg, 201 erstellt, 400 ungültige Anfrage, 401 nicht angemeldet, 403 keine Berechtigung, 404 nicht gefunden und 500 interner Fehler.", [example("Ressource lesen", "GET /api/courses\n→ 200 application/json", "GET soll Daten lesen und keine unerwartete Änderung auslösen."), example("Ressource erzeugen", "POST /api/courses\n→ 201 Created", "Eine erfolgreiche Erstellung kann die neue Ressource zurückgeben.")], "GET /api/courses\n", "Entwirf Statuscodes für erfolgreich, ungültige Eingabe und fehlende Ressource.", "GET\\s+/api/courses|POST\\s+/api/courses"),
  lesson("routes", "02 · HTTP und Schnittstellen", "Routing und Eingabevalidierung", "javascript", "Du leitest Anfragen weiter und prüfst Eingaben auf dem Server.", "Routing ordnet Methode und Pfad einem Handler zu. Der Handler prüft Form, Länge und erlaubte Werte, bevor er Geschäftslogik aufruft. Browserprüfungen verbessern Bedienung, ersetzen aber nie die Serverprüfung. Fehlerantworten sollen helfen, ohne interne Details offenzulegen.", [example("Node Route", "app.get('/api/courses/:id', async (req, res) => {\n  const id = Number(req.params.id);\n  if (!Number.isInteger(id) || id < 1) return res.status(400).json({ error: 'invalid_request' });\n});", "Validiere den Parameter vor einem Datenbankzugriff."), example("Fehlerantwort", "{ \"error\": \"invalid_request\" }", "Keine Stacktraces, Tokens oder SQL-Details an den Client senden.")], "app.get('/api/courses/:id', async (req, res) => {\n  // validieren\n});\n", "Validiere eine ID serverseitig und unterscheide ungültige von unbekannten IDs.", "Number\\.isInteger|res\\.status\\s*\\(400\\)"),
  lesson("database", "03 · Daten und Rechte", "Datenbankzugriff und Transaktionen", "javascript", "Du fragst Daten parametrisiert ab und bündelst zusammengehörige Änderungen.", "Nutze gebundene Parameter statt SQL-Strings aus Nutzereingaben. Begrenze Ergebnisgrößen und wähle nur benötigte Spalten. Transaktionen halten zusammengehörige Änderungen konsistent. Eine Datenbankrolle sollte nur Rechte besitzen, die der Dienst benötigt.", [example("Gebundene Abfrage", "const result = await db.query('SELECT id, title FROM courses WHERE id = $1', [id]);", "id ist ein Parameter und kein zusammengeklebter SQL-Text."), example("Transaktion", "BEGIN → Änderungen → COMMIT\nFehler → ROLLBACK", "So werden Teilergebnisse vermieden.")], "db.query('SELECT id, title FROM courses WHERE id = $1', [id]);\n", "Schreibe eine parametrisierte Abfrage und erkläre, wann du eine Transaktion nutzt.", "\\$1|\\[id\\]|BEGIN"),
  lesson("auth", "03 · Daten und Rechte", "Authentifizierung und Autorisierung", "plaintext", "Du unterscheidest Identitätsprüfung und erlaubte Aktionen.", "Authentifizierung prüft, wer die anfragende Person ist. Autorisierung prüft, ob sie genau diese Ressource und Aktion ausführen darf. Prüfe Rechte bei jeder relevanten Anfrage serverseitig. Ein versteckter Button ist keine Zugriffskontrolle.", [example("Zwei Fragen", "Authentifizierung: Wer bist du?\nAutorisierung: Darfst du Kurs 42 bearbeiten?", "Die zweite Antwort muss für die konkrete Ressource geprüft werden."), example("Prinzip geringster Rechte", "Nutzerrolle: veröffentlichte Kurse lesen\nAdminrolle: Kursdaten verwalten", "Rollen sollen nur notwendige Aktionen erlauben.")], "// Prüfe zuerst die Identität, dann die Berechtigung für die Ressource\n", "Schreibe die beiden Prüfungen für einen Endpunkt auf, der einen Kurs ändert.", "Authentifizierung|Autorisierung|Berechtigung"),
  lesson("errors", "04 · Zuverlässiger Betrieb", "Fehler, Logs und Rate Limits", "plaintext", "Du behandelst Fehler und protokollierst hilfreich, ohne Geheimnisse zu speichern.", "Antworten sollten passende Statuscodes und neutrale Fehlermeldungen nutzen. Serverlogs helfen bei Diagnose, dürfen aber Passwörter, Session-Tokens und unnötige personenbezogene Daten nicht enthalten. Rate Limits und Zeitlimits schützen Ressourcen; Wiederholungen brauchen Grenzen.", [example("Logfelder", "request_id · route · status · duration", "So lässt sich ein Vorgang finden, ohne den kompletten Request-Body zu protokollieren."), example("Sichere Antwort", "500 → { \"error\": \"temporarily_unavailable\", \"requestId\": \"…\" }", "Die interne Ursache bleibt in geschützten Logs.")], "// Begrenze Wiederholungen und protokolliere Status und requestId\n", "Entwirf einen sicheren Fehlerlog und eine Antwort bei einem vorübergehenden Serverfehler.", "requestId|temporarily_unavailable|status"),
  lesson("tests", "05 · Anwenden", "Tests, OpenAPI und Frameworks", "javascript", "Du prüfst API-Verträge und wählst ein Backendwerkzeug passend aus.", "Unit-Tests prüfen Geschäftsregeln; Integrationstests prüfen Datenbank und Routing. OpenAPI beschreibt eine HTTP-Schnittstelle maschinenlesbar. Express und Fastify sind Node-Webframeworks; ASP.NET Core, Spring Boot und Laravel gehören zu anderen Sprachökosystemen. REST ist ein Architekturstil, kein Framework.", [example("Testfall", "GET /api/courses/unknown → 404\nGET /api/courses/12 → 200", "Prüfe Erfolgs- und Fehlerfälle."), example("API-Vertrag", "GET /api/courses/{id}\n200: Course\n404: not_found", "Dokumentiere Eingabe, Antwort und mögliche Fehler.")], "GET /api/courses/12 -> 200\n", "Erstelle einen Erfolgs- und Fehlerfall für deine API und erkläre, ob Express oder Fastify dazu passt.", "404|200|OpenAPI|assert"),
];

const security: LessonBlueprint[] = [
  intro("orientation", "Was ist IT-Sicherheit?", "plaintext", "IT-Sicherheit schützt Systeme, Daten und Menschen vor unbefugtem Zugriff, Manipulation und Ausfall. Sicherheit ist kein einzelnes Produkt und kein einmaliger Scan. Du untersuchst, was geschützt werden muss, welche Bedrohungen realistisch sind und welche Schutzmaßnahmen das Risiko angemessen senken.", [example("Schutzziele", "Vertraulichkeit · Integrität · Verfügbarkeit", "Die Ziele helfen, Folgen eines Angriffs zu beschreiben."), example("Risiko denken", "Asset + Bedrohung + Schwachstelle + Auswirkung", "Ein Risiko braucht Kontext und eine passende Maßnahme.")], "Was ist das Ziel eines Bedrohungsmodells?", "Mögliche Missbrauchswege und Folgen erkennen, um passende Schutzmaßnahmen festzulegen.", "Eine Garantie schreiben, dass ein System nie angegriffen werden kann.", "Alle Sicherheitsverantwortung an einen Virenscanner abgeben."),
  lesson("assets", "02 · Grundlagen", "Schutzziele und Daten bewerten", "plaintext", "Du benennst schützenswerte Daten und mögliche Auswirkungen.", "Beginne mit Assets: Konten, Quellcode, personenbezogene Daten, Verfügbarkeit oder Geschäftsregeln. Bewerte Vertraulichkeit, Integrität und Verfügbarkeit getrennt. Eine öffentliche Kursbeschreibung braucht andere Schutzmaßnahmen als ein Sitzungstoken.", [example("Assetliste", "Asset: Sitzungstoken\nSchutzziel: Vertraulichkeit\nFolge bei Verlust: Kontoübernahme", "Konkrete Folgen helfen, Maßnahmen zu priorisieren."), example("Daten minimieren", "Nur speichern: notwendige Felder\nLöschen: sobald der Zweck entfällt", "Weniger gespeicherte Daten reduzieren mögliche Folgen.")], "Asset: Lernkonto\nSchutzziel: Vertraulichkeit\n", "Nenne zwei Assets einer Lernplattform und beschreibe je eine mögliche Auswirkung.", "Schutzziel|Auswirkung|Asset"),
  lesson("threats", "02 · Grundlagen", "Angreifer, Angriffsflächen und STRIDE", "plaintext", "Du findest mögliche Missbrauchswege systematisch.", "Angriffsfläche sind erreichbare Eingänge wie Formulare, APIs, Uploads und Abhängigkeiten. STRIDE hilft beim Sammeln möglicher Bedrohungen: Spoofing, Tampering, Repudiation, Information Disclosure, Denial of Service und Elevation of Privilege. Das Modell erzeugt Fragen, keine vollständige Sicherheitsgarantie.", [example("Uploadweg", "Browser → Upload-API → Dateispeicher → Vorschau", "Prüfe Dateityp, Größe, Zugriff und spätere Darstellung."), example("STRIDE-Frage", "Kann jemand eine andere Identität vortäuschen?\nKann ein Nutzer fremde Daten lesen?", "Fragen an konkrete Datenflüsse binden.")], "Browser → Upload-API → Dateispeicher\n", "Skizziere einen Datenfluss und formuliere zwei STRIDE-Bedrohungen dazu.", "STRIDE|Upload-API|Information Disclosure"),
  lesson("web-risks", "03 · Webrisiken", "XSS, SQL-Injection und CSRF", "javascript", "Du erkennst typische Webangriffe und ordnest passende Gegenmaßnahmen zu.", "XSS entsteht, wenn nicht vertrauenswürdiger Inhalt als aktiver Browsercode ausgeführt wird. SQL-Injection entsteht, wenn Eingaben SQL-Struktur verändern. CSRF missbraucht die Sitzung eines angemeldeten Browsers. Gegenmaßnahmen hängen vom Angriff ab: kontextgerechtes Escaping, parametrisierte Abfragen und CSRF-Schutz für zustandsändernde Aktionen.", [example("Sichere DOM-Ausgabe", "message.textContent = userInput;", "Der Text wird nicht als HTML interpretiert."), example("Gebundene SQL-Abfrage", "SELECT id FROM users WHERE email = $1;", "Der Parameter bleibt vom SQL-Befehl getrennt.")], "message.textContent = userInput;\n", "Ordne XSS und SQL-Injection je eine passende Gegenmaßnahme zu und nenne einen CSRF-Schutz.", "textContent|\\$1|CSRF"),
  lesson("identity", "03 · Webrisiken", "Passwörter, Sitzungen und Rechte", "plaintext", "Du speicherst Zugangsdaten nicht im Klartext und prüfst Berechtigungen konsequent.", "Passwörter werden mit einem geeigneten Passwort-Hashingverfahren samt individuellen Salt und Arbeitsfaktor gespeichert, nicht verschlüsselt oder im Klartext. Sitzungen brauchen sichere Cookie-Einstellungen und Ablaufregeln. Jede Anfrage prüft serverseitig die Rechte auf die konkrete Ressource.", [example("Cookie-Eigenschaften", "Secure · HttpOnly · SameSite", "Die genaue SameSite-Einstellung hängt vom Anmeldeablauf ab."), example("Zugriffsprüfung", "Ist angemeldet? → Ressource gehört zum Konto? → Aktion erlaubt?", "Prüfe jedes Glied serverseitig.")], "Passwortspeicherung: Passwort → Argon2id / bcrypt / scrypt → Hash\n", "Nenne sichere Sitzungseigenschaften und unterscheide Anmeldung von Rechteprüfung.", "Argon2id|bcrypt|HttpOnly|SameSite"),
  lesson("secrets", "04 · Sichere Umsetzung", "Secrets, Konfiguration und Abhängigkeiten", "plaintext", "Du hältst Geheimnisse aus Quellcode heraus und prüfst verwendete Pakete.", "API-Schlüssel, private Schlüssel und Datenbankpasswörter gehören nicht in Git oder Browsercode. Nutze geschützte Umgebungsvariablen oder einen Secret-Manager und rotiere versehentlich veröffentlichte Geheimnisse. Prüfe Abhängigkeiten, Herkunft, Version und Wartungszustand.", [example("Konfiguration", "APP_DATABASE_URL = Secret-Manager-Eintrag", "Der echte Wert darf nicht in ein öffentliches Frontend-Bundle."), example("Lieferkette", "Paketname → Lockfile → Herkunft → bekannte Schwachstellen", "Lockfiles machen aufgelöste Versionen nachvollziehbarer.")], "// Lade das Geheimnis aus geschützter Serverkonfiguration\n", "Beschreibe, was nach versehentlichem Git-Push eines API-Schlüssels zu tun ist.", "Secret-Manager|rotieren|Lockfile"),
  lesson("response", "05 · Reaktion und Prüfung", "Logging, Updates und Vorfallreaktion", "plaintext", "Du bereitest eine nachvollziehbare Reaktion auf einen Sicherheitsvorfall vor.", "Protokolle helfen beim Erkennen, dürfen aber keine Passwörter oder Tokens enthalten. Halte Verantwortliche, Kontaktweg und erste Schritte fest: betroffene Systeme eingrenzen, Geheimnisse widerrufen, Belege sichern, Wiederherstellung planen und Betroffene nach geltenden Pflichten informieren. Updates und Backups müssen regelmäßig geprüft werden.", [example("Erste Schritte", "Erkennen → Eindämmen → Belege sichern → Wiederherstellen → Lernen", "Passe den Ablauf an Art und Umfang des Vorfalls an."), example("Sicherer Log", "requestId · betroffene Route · Status · Zeit\nkein Passwort · kein Sitzungstoken", "Nur notwendige Diagnoseinformationen speichern.")], "Erkennen → Eindämmen → Wiederherstellen\n", "Schreibe eine kurze Reaktionsliste für ein geleaktes Sitzungstoken.", "Eindämmen|widerrufen|requestId"),
  lesson("frameworks", "06 · Werkzeuge", "OWASP, Scanner und Defense in Depth", "plaintext", "Du nutzt Sicherheitswerkzeuge als Unterstützung, nicht als Ersatz für Analyse.", "OWASP Top 10 ist eine Übersicht wichtiger Webrisikokategorien; es ist keine vollständige Sicherheitsprüfung. Dependency-Scanner und statische Analyse helfen bei bestimmten Fehlerklassen, erzeugen aber Fehlalarme und blinde Flecken. Mehrere Schutzschichten reduzieren Einzelrisiken, wenn jede Schicht passend konfiguriert ist.", [example("Prüffolge", "Code Review → Tests → Dependency Scan → Konfiguration prüfen", "Automatisierung ergänzt menschliche Prüfung."), example("Maßnahmen zuordnen", "SQLi → Parameter\nXSS → kontextgerechtes Escaping\nDoS → Limits und Zeitlimits", "Maßnahmen müssen den konkreten Angriff adressieren.")], "// Wähle für jedes Risiko eine konkrete Maßnahme\n", "Ordne drei Risiken je eine Maßnahme zu und benenne eine Grenze eines automatischen Scanners.", "OWASP|Parameter|Escaping|Limits"),
];

const ai: LessonBlueprint[] = [
  intro("orientation", "Was ist künstliche Intelligenz?", "plaintext", "Künstliche Intelligenz ist ein Sammelbegriff für Systeme, die Aufgaben wie Erkennen, Vorhersagen, Planen oder Textgenerieren unterstützen. Maschinelles Lernen ist ein Teilgebiet: Ein Modell passt Parameter anhand von Beispielen an. Ein generatives Sprachmodell erzeugt plausible Fortsetzungen; es prüft nicht automatisch, ob Aussagen wahr sind.", [example("Verschiedene Aufgaben", "Klassifikation: Spam oder kein Spam\nVorhersage: geschätzte Nachfrage\nGenerierung: Entwurf für eine Erklärung", "Jede Aufgabe braucht eigene Daten und Qualitätskriterien."), example("Modellablauf", "Eingabe → Modell → Vorschlag → menschliche Prüfung", "Ein KI-Ergebnis ist ein Vorschlag, keine verlässliche Quelle an sich.")], "Was bedeutet eine plausible KI-Antwort?", "Sie klingt passend, kann aber trotzdem falsch oder unvollständig sein.", "Sie wurde automatisch ausnahmslos mit Faktenquellen bestätigt.", "Sie ist immer neutral und frei von Verzerrungen."),
  lesson("types", "02 · Grundlagen", "Regelprogramme, Machine Learning und generative KI", "plaintext", "Du unterscheidest explizite Regeln von gelernten Mustern und generativen Ausgaben.", "Ein Regelprogramm führt ausdrücklich geschriebene Logik aus. Ein ML-Modell passt Parameter anhand von Daten an und nutzt sie später für Vorhersagen. Generative Modelle erzeugen neue Inhalte, etwa Text, Bilder oder Code. Viele Systeme kombinieren mehrere Verfahren; der Begriff KI allein sagt wenig über Zuverlässigkeit.", [example("Regel", "if points >= 10: passed = true", "Die Regel wurde direkt von Menschen festgelegt."), example("Modellvorhersage", "Eingaben + gelernte Parameter → geschätzte Klasse", "Das Ergebnis hängt von Training und Eingabedaten ab.")], "if points >= 10: passed = true\n", "Ordne drei Beispiele Regelprogramm, Vorhersage oder Generierung zu.", "Regelprogramm|Vorhersage|Generierung"),
  lesson("data", "02 · Grundlagen", "Daten, Merkmale, Labels und Datenschutz", "plaintext", "Du erkennst, welche Daten eine Lernaufgabe benötigt und welche sensibel sind.", "Bei überwachten Aufgaben enthalten Beispiele Merkmale und ein gewünschtes Label. Daten müssen zum vorgesehenen Einsatz passen. Prüfe Herkunft, Einwilligung, Lizenz, Repräsentation und sensible Merkmale. Sammle nur notwendige Daten und entferne Personenbezug, sofern die Aufgabe ihn nicht wirklich braucht.", [example("Klassifikation", "Merkmale: Nachrichtentext\nLabel: Spam / kein Spam", "Das Label soll die gewünschte Antwort darstellen."), example("Datenschutzprüfung", "Zweck → Datenbedarf → Rechtsgrundlage / Einwilligung → Aufbewahrung", "Eine technische Möglichkeit ist noch keine Erlaubnis zur Nutzung.")], "Merkmale: ____\nLabel: ____\n", "Skizziere eine kleine Lernaufgabe mit Merkmal und Label und streiche unnötige persönliche Daten.", "Merkmale:|Label:|Datenschutz|Einwilligung"),
  lesson("training", "03 · Modelle trainieren", "Training, Validierung und Testdaten", "plaintext", "Du trennst Datenmengen, damit du Leistung nicht am Lernmaterial schönrechnest.", "Trainingsdaten passen Modellparameter an. Validierungsdaten helfen beim Vergleichen von Einstellungen. Testdaten bleiben möglichst bis zur abschließenden Bewertung unangetastet. Wenn ähnliche Datensätze in mehreren Mengen auftauchen, kann Informationsleckage die Messung verfälschen.", [example("Datentrennung", "Datenbestand → Training / Validierung / Test", "Die Testmenge darf nicht laufend für Entscheidungen verwendet werden."), example("Leckagebeispiel", "Gleiche Person in Training und Test → Ergebnis wirkt besser als im Alltag", "Trenne bei wiederholten Messungen nach Person oder Zeit.")], "training: 70%\nvalidation: 15%\ntest: 15%\n", "Erkläre, warum Testdaten nicht zur wiederholten Auswahl von Modelleinstellungen dienen sollten.", "training|validation|test|Leckage"),
  lesson("metrics", "03 · Modelle trainieren", "Metriken, Baselines und Überanpassung", "plaintext", "Du misst ein Modell passend zu Folgen falscher Ergebnisse.", "Eine Baseline liefert einen einfachen Vergleich. Accuracy kann bei seltenen Ereignissen täuschen; Precision und Recall beantworten andere Fragen. Überanpassung liegt vor, wenn ein Modell Trainingsbeispiele auswendig lernt und bei neuen Fällen schlechter wird. Bewertungsmaß und Schwellenwert hängen vom Einsatzzweck ab.", [example("Ungleiche Klassen", "99 Fälle normal + 1 Betrugsfall\nImmer 'normal' sagen → 99% Accuracy, 0% Betrugsfund", "Accuracy allein zeigt das Risiko nicht."), example("Metrik wählen", "Betrug finden: Recall wichtig\nFalschalarme begrenzen: Precision wichtig", "Welche Fehler schwerer wiegen, bestimmt die Wahl.")], "Baseline: immer 'normal'\n", "Beschreibe für eine Aufgabe, welche falsche Antwort besonders schadet und welche Metrik das sichtbar macht.", "Accuracy|Precision|Recall|Baseline"),
  lesson("prompts", "04 · KI sinnvoll bedienen", "Gute Aufgabenstellungen und Kontext", "plaintext", "Du formulierst überprüfbare KI-Aufträge mit Ziel, Kontext und Ausgabeform.", "Eine hilfreiche Eingabe nennt Aufgabe, Zielgruppe, verfügbaren Kontext, gewünschtes Format und Grenzen. Bitte um nachvollziehbare Schritte oder offene Annahmen, wenn das nützlich ist. Eine längere Eingabe ist nicht automatisch besser; gib nur notwendige Informationen weiter und entferne Geheimnisse.", [example("Unklar", "Erklär Code.", "Zielgruppe, Ausschnitt und gewünschte Tiefe fehlen."), example("Besser", "Erkläre diese JavaScript-Funktion für Anfänger in 4 Schritten. Nenne eine Unsicherheit und ändere den Code nicht.", "Ziel, Niveau, Format und Handlung sind klar.")], "Aufgabe: ____\nZielgruppe: ____\nFormat: ____\n", "Formuliere einen Auftrag, der um Code-Erklärung bittet, keine Änderungen erlaubt und Tests verlangt.", "Zielgruppe|Tests|ändere den Code nicht"),
  lesson("verify", "04 · KI sinnvoll bedienen", "Antworten prüfen und Halluzinationen erkennen", "plaintext", "Du kontrollierst KI-Aussagen, Code und Quellen vor einer Verwendung.", "Sprachmodelle können Quellen, APIs oder Code erfinden. Prüfe wichtige Behauptungen anhand offizieller Dokumentation, führe Code nur in einer geeigneten Umgebung aus und ergänze Tests. Frage nach Annahmen und Gegenbeispielen. Eine überzeugend formulierte Antwort ist kein Korrektheitsnachweis.", [example("Code prüfen", "Vorschlag → Syntax prüfen → Tests → Randfälle → Review", "Code aus einer KI ist wie Code aus einer fremden Quelle zu prüfen."), example("Quelle prüfen", "API-Name → offizielle Dokumentation → Version vergleichen", "Eine zitierte URL oder Funktion kann erfunden oder veraltet sein.")], "// Prüfen: offizielle Quelle + Test + Randfall\n", "Nimm eine KI-Aussage und schreibe auf, wie du sie unabhängig überprüfen würdest.", "offizielle Dokumentation|Tests|Randfälle"),
  lesson("privacy", "05 · Verantwortung und Sicherheit", "Vertrauliche Daten, Rechte und Urheberrecht", "plaintext", "Du schützt Daten und prüfst, ob eine Eingabe an ein KI-System darf.", "Gib keine Passwörter, Tokens, privaten Kundendaten oder vertraulichen Quelltexte an einen Dienst, bevor dessen Datenverarbeitung ausdrücklich geprüft und freigegeben ist. Beachte Lizenz und Urheberrecht bei Trainingsmaterial und generierten Inhalten. Prüfe Nutzungsbedingungen, Speicherfristen, Zugriffsrechte und mögliche Weiterverwendung.", [example("Vor dem Einfügen", "Ist der Dienst freigegeben?\nEnthält der Text Geheimnisse?\nKann ich Daten anonymisieren?", "Nicht erforderliche Daten weglassen."), example("Geheimnis entfernen", "API_KEY=REDACTED\nuser_id=ANONYMIZED", "Platzhalter sind besser als echte Zugangsdaten.")], "API_KEY=REDACTED\n", "Bereite einen Codeausschnitt für eine KI-Frage vor, ohne Zugangsdaten oder private Nutzerdaten preiszugeben.", "REDACTED|ANONYMIZED|freigegeben"),
  lesson("bias", "05 · Verantwortung und Sicherheit", "Bias, Fairness und menschliche Aufsicht", "plaintext", "Du untersuchst, welche Gruppen ein System schlechter behandeln könnte.", "Daten und Modellentscheidungen können bestehende Ungleichheiten verstärken. Miss Leistung für relevante Gruppen, prüfe Datenlücken und definiere, wer Entscheidungen überprüfen und anfechten kann. Bei folgenreichen Entscheidungen braucht es menschliche Verantwortung, dokumentierte Grenzen und einen Weg, Fehler zu korrigieren.", [example("Gruppenprüfung", "Gesamtquote + Fehlerquote je relevanter Gruppe", "Ein guter Gesamtwert kann ungleiche Fehler verdecken."), example("Aufsicht", "KI-Vorschlag → menschliche Prüfung → begründete Entscheidung", "Die zuständige Person muss genug Informationen und Zeit haben.")], "Gesamtquote: ____\nGruppenprüfung: ____\n", "Nenne eine mögliche Verzerrung in einem Bewerbungsfilter und eine konkrete Prüfung.", "Fehlerquote|Gruppe|menschliche Prüfung"),
  lesson("applications", "06 · KI-Anwendungen", "KI für Lernen, Programmieren und Alltag", "plaintext", "Du wählst Aufgaben, bei denen KI hilft, ohne Verantwortung abzugeben.", "Sinnvolle Anwendungen sind Ideen sammeln, Texte zusammenfassen, Code erklären, Testfälle vorschlagen und Routinearbeiten unterstützen. Für Lernen sollte die KI Hinweise und Rückfragen geben, statt sofort die Lösung zu liefern. Für Entscheidungen über Gesundheit, Finanzen, Recht oder Beschäftigung ist eine fachkundige Prüfung nötig.", [example("Tutor-Modus", "1. Stelle eine Rückfrage.\n2. Gib einen Hinweis.\n3. Lass mich den nächsten Schritt schreiben.", "Das unterstützt eigenes Verständnis statt bloßes Kopieren."), example("Code-Review", "Bitte nenne Risiken und Tests. Ändere keine Datei.", "Die KI kann eine Prüfliste liefern; Entwickler verifizieren sie.")], "Aufgabe: Erkläre den Fehler, ohne den Code zu ändern.\n", "Entwirf einen KI-Lernauftrag, der zuerst einen kleinen Hinweis und danach eine Verständnisfrage gibt.", "Hinweis|Verständnisfrage|ohne den Code zu ändern"),
  lesson("coding", "06 · KI-Anwendungen", "KI beim Programmieren: sicherer Arbeitsablauf", "plaintext", "Du nutzt KI-Unterstützung kontrolliert und kannst jede Änderung begründen.", "Gib einen kleinen, isolierten Ausschnitt und eine konkrete Frage. Lege fest, ob die KI nur erklären, Tests vorschlagen oder einen Patch entwerfen darf. Prüfe Diff, Lizenz- und Sicherheitsrisiken, führe Tests aus und committe erst, wenn du die Änderung selbst verstehst. Niemals blind generierten Code in Produktion übernehmen.", [example("Kontrollierter Ablauf", "Frage → Vorschlag → Diff prüfen → Tests → Review → übernehmen", "Du entscheidest über jede Änderung."), example("Enger Auftrag", "Finde einen möglichen Randfall. Gib nur Testideen, keine Codeänderung.", "Kleine Aufgaben sind leichter zu prüfen.")], "// KI-Vorschlag erst prüfen und testen\n", "Schreibe einen Auftrag für Testideen und liste drei Prüfungen auf, die vor Übernahme nötig sind.", "Diff prüfen|Tests|Review"),
  lesson("rag", "07 · Systeme bauen", "Suche, RAG und Chatbots", "plaintext", "Du verstehst, wie Dokumentensuche eine Modellantwort unterstützen kann.", "Retrieval-Augmented Generation sucht relevante Dokumente und gibt sie als Kontext an ein Sprachmodell. Das kann Antworten näher an interne Quellen bringen, garantiert aber keine korrekte Antwort. Berechtigungen müssen schon bei der Suche gelten; Quellen sollten sichtbar sein und veraltete Dokumente erkannt werden.", [example("RAG-Ablauf", "Frage → Dokumente suchen → Berechtigung prüfen → Kontext → Antwort mit Quellen", "Das Modell sollte nur Dokumente sehen, die die fragende Person lesen darf."), example("Grenze", "Kein relevantes Dokument gefunden → Rückfrage oder keine Antwort", "Erfinden ist nicht das richtige Verhalten bei fehlendem Kontext.")], "Frage → Suche → passende Dokumente → Antwort mit Quellen\n", "Zeichne einen RAG-Ablauf mit Berechtigungsprüfung und definiere, was bei fehlendem Kontext passiert.", "Berechtigung|Quellen|kein relevantes Dokument"),
  lesson("automation", "07 · Systeme bauen", "Agenten und Werkzeugaufrufe begrenzen", "plaintext", "Du begrenzt KI-Automationen und prüfst Aktionen vor ihrer Ausführung.", "Ein Agent verbindet ein Modell mit Werkzeugen wie Suche, Dateizugriff oder API-Aufrufen. Werkzeugausgaben sind nicht automatisch vertrauenswürdig. Begrenze Berechtigungen, setze Zeit- und Kostenlimits, bestätige irreversible Aktionen durch Menschen und protokolliere nur nötige Informationen.", [example("Berechtigungsgrenzen", "Lesen: freigegebene Kursdateien\nSchreiben: nur nach Bestätigung\nLöschen: gesperrt", "Gib einer Automation nur die nötigen Rechte."), example("Bestätigung", "Vorschlag → Vorschau → Nutzerbestätigung → Ausführung", "Die Bestätigung muss vor dem irreversiblen Schritt erfolgen.")], "Vorschlag → Vorschau → Bestätigung → Ausführung\n", "Lege für einen KI-Agenten fest, welche Aktion automatisch erlaubt und welche bestätigungspflichtig ist.", "Bestätigung|Berechtigungen|Zeitlimit"),
  lesson("evaluation", "08 · Bewerten und veröffentlichen", "KI-Systeme evaluieren und überwachen", "plaintext", "Du misst Qualität vor Veröffentlichung und beobachtest Fehler im Betrieb.", "Erstelle repräsentative Testfälle, einschließlich schwieriger und missbräuchlicher Eingaben. Miss Korrektheit, Latenz, Kosten, Sicherheit und Gruppenunterschiede. Vergleiche Änderungen gegen eine feste Baseline. Überwache reale Fehler, biete eine Meldemöglichkeit und plane Abschaltung oder Rückfall auf ein einfacheres Verfahren.", [example("Testset", "Normalfall · Randfall · Mehrdeutigkeit · Angriffseingabe · keine Daten", "Testfälle müssen zum tatsächlichen Einsatz passen."), example("Freigabe", "Messwert + Grenzen + Verantwortliche + Rollbackplan", "Vor Veröffentlichung muss klar sein, wer den Betrieb verantwortet.")], "Testset: Normalfall / Randfall / missbräuchliche Eingabe\n", "Definiere drei Messgrößen und eine Rückfallmaßnahme für eine KI-Funktion.", "Baseline|Latenz|Rollback|Fehler"),
];

const gameDevelopment: LessonBlueprint[] = [
  intro("orientation", "Was ist Spieleentwicklung?", "javascript", "Spieleentwicklung verbindet Regeln, Eingaben, Spielzustand, Darstellung, Audio und Tests zu einem interaktiven Programm. Eine Game Loop aktualisiert das Spiel wiederholt und zeichnet den aktuellen Zustand. Eine Engine bietet Werkzeuge, aber ein kleines spielbares Regelwerk ist der beste Anfang.", [example("Spielzyklus", "Eingabe → Zustand ändern → Kollision prüfen → Bild zeichnen", "Diese Schritte wiederholen sich während des Spiels."), example("MVP", "Eine Figur bewegen und ein Ziel erreichen", "Ein kleiner funktionierender Prototyp ist wertvoller als viele unfertige Features.")], "Was ist eine Game Loop?", "Eine wiederholte Aktualisierung des Spielzustands mit anschließender Darstellung.", "Eine Schleife, die nur einmal beim Installieren läuft.", "Ein Dateiformat, in dem Spielstände immer automatisch gespeichert werden."),
  lesson("coordinates", "02 · Spielzustand", "Koordinaten, Zustand und Szenen", "javascript", "Du beschreibst Positionen und hältst den Spielzustand nachvollziehbar.", "Ein 2D-Spiel verwendet meist x- und y-Koordinaten. Die Bildschirmkoordinaten beginnen häufig links oben; die y-Richtung steigt nach unten. Der Spielzustand umfasst Position, Punkte, Leben und Modus. Szenen oder Zustandsmaschinen trennen Menü, Spiel und Pause.", [example("Position", "const player = { x: 40, y: 80, score: 0 };", "Die Objektfelder beschreiben aktuellen Zustand."), example("Zustände", "menu → playing → paused → gameOver", "Definiere, welche Übergänge erlaubt sind.")], "const player = { x: 40, y: 80, score: 0 };\n", "Lege Spielerposition und Punkte an und zeichne die erlaubten Übergänge zwischen Spielzuständen.", "\\{[^}]*x:\\s*\\d+[^}]*y:|playing.*paused"),
  lesson("input", "02 · Spielzustand", "Eingaben und Steuerung", "javascript", "Du trennst Eingabe davon, wie der Spielzustand darauf reagiert.", "Tastatur, Maus und Controller liefern Eingaben. Lies sie in einem klaren Schritt und ändere dann den Zustand. Auf Tastaturfokus, Pause und wiederholte Eingaben musst du achten. Eine Eingabe sollte nicht direkt beliebige globale Werte an vielen Stellen ändern.", [example("Tasten prüfen", "if (keys.left) player.x -= speed * delta;", "Die Position wird pro verstrichener Zeit angepasst."), example("Aktion kapseln", "function jump(player) {\n  if (player.onGround) player.velocityY = -jumpForce;\n}", "Eine Funktion stellt die Spielregel zentral dar.")], "if (keys.left) {\n  // Spielerzustand ändern\n}\n", "Behandle Links- und Rechtsbewegung und verhindere Springen, wenn die Figur in der Luft ist.", "keys\\.left|onGround"),
  lesson("loop", "03 · Bewegung und Kollision", "Game Loop und delta time", "javascript", "Du hältst Bewegung unabhängig von der Bildrate.", "Eine Game Loop liest Eingaben, aktualisiert Zustand und zeichnet. `delta time` beschreibt die Zeit seit dem letzten Schritt. Bewegung als Geschwindigkeit mal delta time verhindert, dass Figuren auf schnellen Bildschirmen schneller laufen. Begrenze sehr große Zeitsprünge nach einem Tabwechsel.", [example("Zeitbasierte Bewegung", "player.x += player.speed * deltaSeconds;", "speed wird in Einheiten pro Sekunde gemessen."), example("Ablauf", "readInput();\nupdate(deltaSeconds);\nrender();", "Trenne die Phasen, damit Fehler leichter zu finden sind.")], "function update(deltaSeconds) {\n  player.x += player.speed * deltaSeconds;\n}\n", "Berechne Bewegung mit delta time und erkläre den Unterschied zu festem Pixelzuwachs pro Frame.", "deltaSeconds|deltaTime|\\*\\s*delta"),
  lesson("collision", "03 · Bewegung und Kollision", "Kollisionen, Grenzen und Physik", "javascript", "Du erkennst Überlappungen und entscheidest, ob eine Physik-Engine nötig ist.", "Eine einfache Rechteckkollision prüft, ob sich zwei Bereiche überlappen. Spielfeldgrenzen verhindern, dass Objekte verschwinden. Eine Physik-Engine hilft bei vielen Kräften und Kontakten, kann aber unnötig kompliziert sein, wenn einfache Regeln genügen.", [example("Rechtecke überlappen", "const hit = a.left < b.right && a.right > b.left && a.top < b.bottom && a.bottom > b.top;", "Alle vier Richtungen müssen überlappen."), example("Grenze", "player.x = Math.max(0, Math.min(maxX, player.x));", "Die Position bleibt innerhalb des Spielfelds.")], "const hit = a.left < b.right && a.right > b.left;\n", "Ergänze die vertikalen Kollisionstests und begrenze die Spielerposition.", "a\\.top\\s*<\\s*b\\.bottom|Math\\.min\\s*\\("),
  lesson("gameplay", "04 · Spielregeln", "Punkte, Ziele und UI", "javascript", "Du definierst klare Sieg-, Verlust- und Rückmelderegeln.", "Punkte, Ziele und UI sollten aus einem einzigen nachvollziehbaren Spielzustand abgeleitet werden. Ein Sammelspiel braucht Regeln für Berührung, Punktestand, Gewinn und erneuten Start. Zeige die Rückmeldung auch visuell und mit Text, nicht nur durch Farbe oder Ton.", [example("Punktestand", "if (overlaps(player, coin)) {\n  score += 1;\n  coin.active = false;\n}", "Die Kollision verändert Zustand und entfernt das Ziel."), example("Gewinnbedingung", "const won = score >= targetScore;", "Die Regel ist unabhängig von der Darstellung prüfbar.")], "let score = 0;\nconst targetScore = 5;\n", "Sammle ein Objekt genau einmal und beende das Spiel bei fünf Punkten.", "score\\s*\\+=\\s*1|targetScore"),
  lesson("testing", "05 · Werkzeuge und Veröffentlichung", "Speichern, Tests und Engines", "javascript", "Du testest Spielregeln und wählst eine Engine passend zum Projekt.", "Teste Regeln wie Kollision, Punktestand und Zustandswechsel getrennt von der Grafik. Godot unterstützt GDScript und C#, Unity hauptsächlich C#; beide Engines liefern Szenen-, Asset- und Editorwerkzeuge. Wähle nach Zielplattform, Team, Lernaufwand und Lizenz. Speichere und lade Spielstände mit Versions- und Fehlerbehandlung.", [example("Regel testen", "assert(addScore(4, 1) === 5);", "Eine reine Regel ist leichter zu testen als eine komplette Szene."), example("Speicherformat", "{ \"version\": 1, \"score\": 5, \"level\": 2 }", "Prüfe Version und Werte beim Laden.")], "function addScore(score, amount) { return score + amount; }\n", "Teste Grenzwerte einer Spielfunktion und vergleiche, was eine Engine für dein Projekt leisten würde.", "assert\\s*\\(|version.*score"),
];

const career: LessonBlueprint[] = [
  intro("orientation", "Auf dem Weg zum Entwicklerjob", "plaintext", "Der Einstieg in einen Entwicklerjob braucht nicht eine einzige richtige Programmiersprache. Wichtig sind solide Grundlagen, nachvollziehbare Projekte, Problemlösen und Zusammenarbeit. Erwartungen unterscheiden sich nach Rolle, Team und Region. Reale Stellenanzeigen und Gespräche mit Teams helfen mehr als pauschale Versprechen.", [example("Arbeitsproben", "Problem → Entscheidung → Ergebnis → nächste Verbesserung", "Ein gutes Projekt zeigt, wie du denkst, nicht nur welche Tools du kennst."), example("Rollen vergleichen", "Frontend · Backend · Plattform · Daten · Mobile · Test", "Rollen überschneiden sich, haben aber unterschiedliche Schwerpunkte.")], "Was macht ein Portfolio-Projekt überzeugend?", "Es erklärt Problem, Entscheidungen, Ergebnis und wie man es ausprobiert.", "Es listet möglichst viele Frameworknamen ohne Beispiele auf.", "Es behauptet, dass keine Fehler oder Grenzen existieren."),
  lesson("roles", "02 · Orientierung", "Rollen, Anforderungen und Lernziele", "plaintext", "Du zerlegst eine gewünschte Rolle in beobachtbare Fähigkeiten.", "Lies mehrere passende Stellenanzeigen und markiere wiederkehrende Anforderungen. Unterscheide Muss-Kriterien von Wunschlisten. Formuliere daraus kleine Lernziele: etwa eine API bauen, einen Test schreiben oder einen Pull Request nachvollziehen. Ein Abschluss allein beweist nicht jede praktische Fähigkeit.", [example("Anforderung übersetzen", "'REST-Erfahrung' → GET/POST verstehen, Statuscodes, Tests, Dokumentation", "Konkrete Übung macht einen Schlagwortwunsch überprüfbar."), example("Lernziel", "Ich baue bis Freitag einen Endpunkt mit Eingabeprüfung und drei Tests.", "Zeit, Ergebnis und Prüfung sind konkret.")], "Lernziel: Ich baue ____ und prüfe es mit ____.\n", "Nimm eine technische Stellenanforderung und formuliere eine kleine überprüfbare Übung.", "prüfe es mit|Tests|Endpunkt"),
  lesson("portfolio", "03 · Eigene Arbeit zeigen", "Portfolio und Projektumfang", "plaintext", "Du planst ein kleines Projekt, das du fertigstellen und erklären kannst.", "Wähle ein echtes, überschaubares Problem. Schreibe zuerst die Kernfunktion und klare Grenzen auf. Ein fertiges kleines Projekt mit Tests und Startanleitung ist meist nützlicher als ein großes unfertiges. Nutze keine fremden Daten oder Assets ohne Erlaubnis.", [example("Klein anfangen", "V1: Kurse filtern\nV2: Filter speichern\nV3: Tastaturbedienung verbessern", "Stufen liefern früh ein benutzbares Ergebnis."), example("Projektbeschreibung", "Für wen? Welches Problem? Was funktioniert? Was fehlt?", "Ehrliche Grenzen machen die Arbeit glaubwürdiger.")], "Projekt: ____\nNutzerproblem: ____\nErste Version: ____\n", "Schreibe ein einwöchiges Projektziel mit drei Funktionen und zwei ausdrücklich ausgeschlossenen Ideen.", "Nutzerproblem|Erste Version|Grenzen"),
  lesson("git", "04 · Zusammenarbeit", "Git, Commits und Branches", "plaintext", "Du speicherst nachvollziehbare Änderungen und kannst einen Stand wiederfinden.", "Git speichert Versionshistorie. Ein Commit sollte eine zusammengehörige Änderung mit verständlicher Nachricht enthalten. Branches isolieren Arbeit, ein Pull Request macht sie prüfbar. Ein Commit ist kein Backup, wenn Repository und Backups am selben gefährdeten Ort liegen.", [example("Kleine Änderung", "git status\ngit add src/example.ts\ngit commit -m \"Add course filter\"", "Prüfe vor dem Commit, welche Dateien enthalten sind."), example("Branchablauf", "Branch → Änderung → Tests → Pull Request → Review → Merge", "Ein Review sucht Korrektheit und Risiken, nicht Fehler im Wert einer Person.")], "git status\n", "Beschreibe, was du vor einem Commit prüfst und wann du einen Branch nutzt.", "git status|git commit|Pull Request"),
  lesson("tests-review", "04 · Zusammenarbeit", "Tests, Debugging und Code Review", "plaintext", "Du machst Änderungen überprüfbar und gibst hilfreiches Feedback.", "Tests sichern Regeln gegen spätere Änderungen ab. Debugging beginnt mit reproduzierbarem Verhalten und einer Hypothese. Ein gutes Review nennt konkrete Auswirkungen und stellt Fragen, wenn Kontext fehlt. Prüfe Fehlerfälle, Zugriffsrechte und Lesbarkeit statt nur Formatierung.", [example("Bugbericht", "Schritt 1 → erwartetes Ergebnis → tatsächliches Ergebnis → relevante Umgebung", "Reproduzierbare Berichte verkürzen die Fehlersuche."), example("Review-Kommentar", "Bei leerer Liste könnte index 0 fehlschlagen. Wie soll der Fall behandelt werden?", "Konkrete Frage plus Begründung ist hilfreicher als 'falsch'.")], "Erwartet: ____\nTatsächlich: ____\nSchritte: ____\n", "Formuliere einen hilfreichen Review-Kommentar zu einem möglichen Grenzfall.", "Erwartet:|Tatsächlich:|Wie soll"),
  lesson("interview", "05 · Bewerben und wachsen", "Lebenslauf, Gespräch und STAR", "plaintext", "Du beschreibst eigene Beiträge und Fehler ehrlich und strukturiert.", "Ein Lebenslauf sollte wahr, knapp und auf die Rolle bezogen sein. Erkläre im Gespräch, was du selbst umgesetzt und warum du Entscheidungen getroffen hast. STAR ordnet eine Erfahrung in Situation, Aufgabe, Handlung und Ergebnis. Es ist eine Strukturierungshilfe, kein auswendig zu lernender Trick.", [example("STAR", "Situation: Ausgangslage\nAufgabe: mein Anteil\nHandlung: konkrete Schritte\nErgebnis: belegbare Wirkung", "Benenne auch Teambeiträge und Grenzen."), example("Fehler erklären", "Ursache → Auswirkungen → Korrektur → was ich gelernt habe", "Eine ehrliche Fehleranalyse zeigt Verantwortung.")], "Situation: ____\nAufgabe: ____\nHandlung: ____\nErgebnis: ____\n", "Beschreibe ein eigenes Lernproblem mit STAR, ohne deinen Anteil zu übertreiben.", "Situation:|Aufgabe:|Handlung:|Ergebnis:"),
  lesson("growth", "05 · Bewerben und wachsen", "Sicheres Portfolio und Weiterlernen", "plaintext", "Du veröffentlichst Projekte ohne sensible Daten und planst den nächsten Lernschritt.", "Prüfe vor Veröffentlichung Lizenzen, Zugangsdaten und personenbezogene Inhalte. Entferne echte Tokens aus der Historie und rotiere sie, wenn sie veröffentlicht wurden. Sammle Feedback, notiere offene Probleme und wähle den nächsten Schritt aus echten Lücken statt aus Trends.", [example("Release-Check", "Startanleitung · Tests · Lizenz · keine Secrets · bekannte Grenzen", "Ein öffentlicher Codebestand ist für andere nachvollziehbar und sicher."), example("Nächster Schritt", "Lücke → kleine Übung → Ergebnis prüfen → wiederholen", "Lernen ist ein fortlaufender Prozess.")], "Release-Check: Tests / Lizenz / keine Secrets\n", "Erstelle eine Veröffentlichungsliste für dein Portfolio und markiere, wie du ein versehentlich veröffentlichtes Token behandeln würdest.", "keine Secrets|rotieren|Lizenz"),
];

type ProjectArc = { language: string; framework: string; frameworkWhy: string; workshopMarker: string; frameworkExample: string; project: string; projectBrief: string; capstoneExample: string; testExample: string; testMarker: string; capstoneMarker: string; criteria: string[] };
const projectArcs: Record<string, ProjectArc> = {
  javascript: { language:"javascript", framework:"React, Vite und Node.js", frameworkWhy:"React hilft bei Oberflächen aus wiederverwendbaren Komponenten; Vite startet einen modernen Frontend-Entwicklungsserver; Node.js führt JavaScript auch serverseitig aus. Die Sprachgrundlagen bleiben dieselben.", workshopMarker:"CourseCard", frameworkExample:"function CourseCard({ title, minutes }) {\n  return <article><h2>{title}</h2><p>{minutes} min</p></article>;\n}", project:"Lernkurs-Finder", projectBrief:"Baue eine kleine Seite, auf der Lernende Kurse suchen, filtern und als Favorit speichern können.", capstoneExample:"const courses = [{ title: 'JavaScript', minutes: 30 }];\nconst matches = courses.filter(course => course.title.includes('Java'));\nconsole.log(matches);", testExample:"console.assert(filterCourses(courses, 'Java').length === 1);\nconsole.assert(filterCourses([], 'Java').length === 0);", testMarker:"console\\.assert|test\\(", capstoneMarker:"filter|function|=>", criteria:["Leere und passende Suchanfragen funktionieren.","Eine Funktion kapselt das Filtern.","Mindestens zwei Randfälle sind geprüft.","README erklärt Start und Grenzen."] },
  java: { language:"java", framework:"JUnit 5 und Spring Boot", frameworkWhy:"JUnit prüft Java-Verhalten automatisiert. Spring Boot liefert Bausteine für HTTP-APIs und Konfiguration; erst sinnvoll, wenn Klassen, Methoden und Fehlerbehandlung sitzen.", workshopMarker:"GetMapping", frameworkExample:"@GetMapping(\"/courses\")\nList<Course> courses() { return service.findAll(); }", project:"Aufgaben-API", projectBrief:"Entwickle einen kleinen Dienst, der Lernaufgaben anlegt, auflistet und als erledigt markiert.", capstoneExample:"record Task(long id, String title, boolean done) {}\nTask complete(Task task) {\n  return new Task(task.id(), task.title(), true);\n}", testExample:"assertEquals(true, complete(task).done());\nassertEquals(task.title(), complete(task).title());", testMarker:"assertEquals|@Test", capstoneMarker:"record Task|complete\\(", criteria:["Titel darf nicht leer sein.","Statusänderung bewahrt Titel und ID.","JUnit prüft Erfolgs- und Fehlerfall.","API-Antworten haben nachvollziehbare Statuscodes."] },
  python: { language:"python", framework:"pytest, FastAPI und pandas", frameworkWhy:"pytest macht Verhalten mit kurzen Tests sichtbar. FastAPI stellt Python-Funktionen als validierte HTTP-Endpunkte bereit. pandas eignet sich für tabellarische Daten; für kleine Datenmengen ist die Standardbibliothek oft einfacher.", workshopMarker:"FastAPI", frameworkExample:"from fastapi import FastAPI\napp = FastAPI()\n\n@app.get('/health')\ndef health():\n    return {'status': 'ok'}", project:"Lernzeit-Auswertung", projectBrief:"Lies Lernzeiteinträge ein, berechne Wochenwerte, finde Ausreißer und stelle die Auswertung als kleine API bereit.", capstoneExample:"def weekly_total(entries):\n    return sum(item['minutes'] for item in entries)\n\nprint(weekly_total([{'minutes': 20}, {'minutes': 15}]))", testExample:"def test_weekly_total():\n    assert weekly_total([{'minutes': 20}, {'minutes': 15}]) == 35\n    assert weekly_total([]) == 0", testMarker:"assert.*weekly_total|def test_", capstoneMarker:"def weekly_total|sum\\(", criteria:["Leere Liste ergibt 0.","Ungültige Minutenwerte werden erkannt.","pytest prüft Normalfall und Randfall.","Die API gibt dokumentiertes JSON zurück."] },
  php: { language:"php", framework:"Laravel und PHPUnit", frameworkWhy:"Laravel organisiert HTTP-Routen, Validierung und Datenbankzugriff. PHPUnit prüft Regeln unabhängig von der Oberfläche. Vor dem Framework müssen PHP-Funktionen, Arrays und sichere Ausgabe verstanden sein.", workshopMarker:"Route::get", frameworkExample:"Route::get('/courses', [CourseController::class, 'index']);\n\npublic function index() {\n  return Course::query()->where('published', true)->get();\n}", project:"Kursanmeldung", projectBrief:"Baue einen kleinen Kurskatalog mit sicherer Suche und einer Anmeldung, die doppelte Einträge verhindert.", capstoneExample:"function normalizeEmail(string $email): string {\n  return strtolower(trim($email));\n}\n\necho normalizeEmail(' Mina@Example.com ');", testExample:"self::assertSame('mina@example.com', normalizeEmail(' Mina@Example.com '));", testMarker:"assertSame|assertEquals", capstoneMarker:"function normalizeEmail|strtolower", criteria:["Eingaben werden serverseitig validiert.","SQL-Werte werden parametrisiert.","HTML-Ausgabe wird kontextgerecht escaped.","Doppelte Anmeldung erhält eine verständliche Antwort."] },
  typescript: { language:"typescript", framework:"React, Zod und Vitest", frameworkWhy:"React baut Komponenten. TypeScript prüft Datenformen beim Entwickeln; Zod validiert tatsächliche Laufzeitdaten. Vitest automatisiert Tests. Ein TypeScript-Typ allein überprüft keine Netzwerknutzereingabe.", workshopMarker:"CourseSchema", frameworkExample:"import { z } from 'zod';\nconst CourseSchema = z.object({ title: z.string().min(1), minutes: z.number().positive() });\nconst course = CourseSchema.parse(input);", project:"Typsicherer Kursplaner", projectBrief:"Erstelle einen Planer, der Kursdaten validiert, Lernzeit berechnet und ungültige API-Antworten verständlich behandelt.", capstoneExample:"type Course = { title: string; minutes: number };\nfunction totalMinutes(items: Course[]): number {\n  return items.reduce((sum, item) => sum + item.minutes, 0);\n}", testExample:"expect(totalMinutes([{ title: 'JS', minutes: 20 }])).toBe(20);\nexpect(totalMinutes([])).toBe(0);", testMarker:"expect\\(|describe\\(", capstoneMarker:"type Course|reduce\\(", criteria:["Unbekannte JSON-Daten werden zur Laufzeit geprüft.","Leere und fehlerhafte Antworten sind abgedeckt.","Komponenten erhalten klar definierte Props.","Fehlermeldungen sind für Nutzende verständlich."] },
  cpp: { language:"cpp", framework:"STL, CMake und Catch2", frameworkWhy:"Die C++-Standardbibliothek stellt vector, string, map und Algorithmen bereit. CMake konfiguriert den Build; Catch2 prüft Funktionen. Moderne Ressourcenverwaltung bevorzugt RAII und Smart Pointer.", workshopMarker:"count_if", frameworkExample:"#include <algorithm>\n#include <vector>\nstd::vector<int> scores{4, 8, 12};\nconst auto passed = std::count_if(scores.begin(), scores.end(), [](int n) { return n >= 10; });", project:"Punktestand-Analysator", projectBrief:"Lies Punktestände ein, berechne Statistik und markiere ungültige Werte ohne Speicherfehler.", capstoneExample:"int countPassed(const std::vector<int>& scores) {\n  return std::count_if(scores.begin(), scores.end(), [](int score) { return score >= 10; });\n}", testExample:"REQUIRE(countPassed({4, 12}) == 1);\nREQUIRE(countPassed({}) == 0);", testMarker:"REQUIRE\\(|TEST_CASE", capstoneMarker:"countPassed|std::count_if", criteria:["Leere Eingabe funktioniert.","Grenzwerte sind definiert und getestet.","Daten werden als const-Referenz übergeben.","CMake baut Anwendung und Tests reproduzierbar."] },
  csharp: { language:"csharp", framework:".NET, ASP.NET Core und xUnit", frameworkWhy:"ASP.NET Core bietet Routing und Dependency Injection für APIs. xUnit prüft Regeln automatisiert. Für Spiele kann Unity C# verwenden; Engine-Code sollte trotzdem testbare Spiellogik trennen.", workshopMarker:"MapGet", frameworkExample:"app.MapGet(\"/courses\", (CourseService service) => service.ListPublished());\napp.Run();", project:"Aufgaben-Dienst", projectBrief:"Baue einen Dienst, der Aufgaben validiert, speichert und nach Status filtert.", capstoneExample:"public record TaskItem(string Title, bool Done);\nstatic TaskItem Complete(TaskItem task) => task with { Done = true };", testExample:"Assert.True(Complete(new TaskItem(\"Test\", false)).Done);\nAssert.Equal(\"Test\", Complete(task).Title);", testMarker:"Assert\\.(True|Equal)|\\[Fact\\]", capstoneMarker:"record TaskItem|Complete\\(", criteria:["Leere Titel werden abgewiesen.","Änderungen erhalten unveränderte Felder.","xUnit deckt Normal- und Fehlerfälle ab.","API trennt Routen von Geschäftsregeln."] },
  rust: { language:"rust", framework:"Cargo, Clippy und Axum", frameworkWhy:"Cargo verwaltet Builds, Abhängigkeiten und Tests; Clippy weist auf verbreitete Fehler hin. Axum verbindet Rust-Funktionen mit HTTP-Routen. Ownership und Result bleiben auch im Framework wichtig.", workshopMarker:"Router", frameworkExample:"use axum::{routing::get, Router};\nfn health() -> &'static str { \"ok\" }\nfn app() -> Router { Router::new().route(\"/health\", get(health)) }", project:"Sicherer Aufgaben-Endpunkt", projectBrief:"Entwickle einen Dienst, der Aufgaben einliest, ungültige Daten ablehnt und Fehler als Result zurückgibt.", capstoneExample:"fn complete(title: &str) -> Result<String, &'static str> {\n  if title.trim().is_empty() { return Err(\"Titel fehlt\"); }\n  Ok(format!(\"[x] {}\", title))\n}", testExample:"assert!(complete(\"Lernen\").is_ok());\nassert!(complete(\"  \" ).is_err());", testMarker:"assert!\\(|#\\[test\\]", capstoneMarker:"Result<|fn complete", criteria:["Leere Daten ergeben einen Fehler statt eines Absturzes.","Rückgaben nutzen Result.","Cargo test prüft Erfolg und Fehler.","HTTP-Fehler sind für Client und Logs klar getrennt."] },
  sql: { language:"sql", framework:"PostgreSQL, EXPLAIN und SQLAlchemy", frameworkWhy:"PostgreSQL liefert Transaktionen, Constraints und Abfragepläne. EXPLAIN zeigt, wie eine Abfrage ausgeführt wird. SQLAlchemy nutzt SQL aus Python; ORM ist kein Ersatz für Joins, Indizes und Transaktionsverständnis.", workshopMarker:"GROUP\ BY", frameworkExample:"SELECT c.category, COUNT(*) AS amount\nFROM courses AS c\nWHERE c.published IS TRUE\nGROUP BY c.category;", project:"Lernfortschritt-Datenbank", projectBrief:"Entwirf Tabellen für Lernende, Kurse und Fortschritt und beantworte Fragen mit Joins, Aggregaten und Transaktionen.", capstoneExample:"BEGIN;\nUPDATE progress SET completed = TRUE WHERE learner_id = $1 AND course_id = $2;\nCOMMIT;", testExample:"EXPLAIN (ANALYZE, BUFFERS) SELECT id FROM courses WHERE slug = $1;\n-- Prüfe Ergebnis und tatsächlichen Plan", testMarker:"EXPLAIN|BEGIN", capstoneMarker:"UPDATE progress|BEGIN", criteria:["Fremdschlüssel und Constraints verhindern ungültige Beziehungen.","Alle Nutzereingaben werden parametrisiert.","Mehrere zusammengehörige Änderungen laufen in einer Transaktion.","EXPLAIN wird für eine echte Abfrage interpretiert."] },
  c: { language:"c", framework:"C-Standardbibliothek, Make und Unity Test", frameworkWhy:"Die C-Standardbibliothek stellt I/O und Speicherfunktionen bereit. Make wiederholt Compileraufrufe zuverlässig; Unity ist ein schlankes C-Testframework. Puffergrößen und Besitz müssen explizit geprüft werden.", workshopMarker:"countPassing", frameworkExample:"#include <stddef.h>\nsize_t countPassing(const int *scores, size_t length) {\n  size_t count = 0;\n  for (size_t i = 0; i < length; i++) if (scores[i] >= 10) count++;\n  return count;\n}", project:"Robuster CSV-Punkteleser", projectBrief:"Lies Zahlen aus einer Datei, prüfe fehlerhafte Zeilen und gib Durchschnitt sowie Grenzfälle sicher aus.", capstoneExample:"int parse_score(const char *text, int *out) {\n  char *end = NULL;\n  long value = strtol(text, &end, 10);\n  if (end == text || *end != '\\0' || value < 0 || value > 100) return 0;\n  *out = (int)value;\n  return 1;\n}", testExample:"TEST_ASSERT_EQUAL_INT(1, parse_score(\"42\", &score));\nTEST_ASSERT_EQUAL_INT(0, parse_score(\"abc\", &score));", testMarker:"TEST_ASSERT|assert\\(", capstoneMarker:"strtol|parse_score", criteria:["Ungültige Eingabe wird gemeldet.","Puffergrenzen werden eingehalten.","Rückgabewerte unterscheiden Erfolg und Fehler.","Make baut Programm und Tests mit Warnungen."] },
  kotlin: { language:"kotlin", framework:"Kotlin Coroutines, Ktor und Android Compose", frameworkWhy:"Coroutines verwalten nebenläufige Arbeit ohne Callback-Ketten. Ktor baut Kotlin-HTTP-Dienste; Compose erstellt deklarative Android-Oberflächen. UI-Zustand und Geschäftslogik bleiben getrennt.", workshopMarker:"listPublished", frameworkExample:"get(\"/courses\") {\n  call.respond(courseService.listPublished())\n}", project:"Lernziel-App", projectBrief:"Baue eine kleine App, die Lernziele speichert, erledigte Aufgaben anzeigt und Ladefehler verständlich darstellt.", capstoneExample:"data class Goal(val title: String, val done: Boolean = false)\nfun complete(goal: Goal) = goal.copy(done = true)", testExample:"assertEquals(true, complete(Goal(\"Üben\")).done)\nassertEquals(\"Üben\", complete(Goal(\"Üben\")).title)", testMarker:"assertEquals|\\[Test\\]", capstoneMarker:"data class Goal|copy\\(", criteria:["Leerer Titel wird nicht gespeichert.","UI zeigt Lade-, Erfolgs- und Fehlerzustand.","Suspend-Aufrufe blockieren nicht den UI-Thread.","Tests prüfen Regeln getrennt von der Oberfläche."] },
  swift: { language:"swift", framework:"SwiftUI, XCTest und async/await", frameworkWhy:"SwiftUI beschreibt Oberflächen aus Zustand; XCTest prüft Verhalten. async/await macht Netzwerkzugriffe lesbarer, Fehler müssen weiterhin mit do/catch und UI-Zuständen behandelt werden.", workshopMarker:"CourseRow", frameworkExample:"struct CourseRow: View {\n  let title: String\n  var body: some View { Text(title) }\n}", project:"Lernziel-App für iOS", projectBrief:"Erstelle eine Liste von Lernzielen mit Filter, Statusänderung und verständlicher Offline-Anzeige.", capstoneExample:"struct Goal { let title: String; var done = false }\nfunc complete(_ goal: Goal) -> Goal {\n  var copy = goal; copy.done = true; return copy\n}", testExample:"XCTAssertTrue(complete(Goal(title: \"Üben\")).done)\nXCTAssertEqual(complete(goal).title, goal.title)", testMarker:"XCTAssert|\\[Test", capstoneMarker:"struct Goal|func complete", criteria:["Statusänderung erhält den Titel.","Leere Eingaben sind abgefangen.","UI unterscheidet Laden, Fehler und leere Liste.","XCTest prüft Geschäftsregeln."] },
  "web-development": { language:"javascript", framework:"React, Vite, Playwright und WCAG", frameworkWhy:"React wird bei wiederverwendbaren UI-Zuständen nützlich; Vite vereinfacht Entwicklung und Build. Playwright prüft Nutzerabläufe. Semantisches HTML, Tastaturbedienung und Kontrast bleiben unabhängig vom Framework wichtig.", workshopMarker:"Search", frameworkExample:"function Search({ value, onChange }) {\n  return <label>Kurse suchen<input value={value} onChange={e => onChange(e.target.value)} /></label>;\n}", project:"Barrierefreier Kurskatalog", projectBrief:"Baue eine responsive Kursseite mit Suche, Kategorien, Tastaturbedienung und leerem Suchzustand.", capstoneExample:"const visible = courses.filter(course => course.title.toLowerCase().includes(query.toLowerCase()));\nreturn visible.length ? <CourseList courses={visible} /> : <p>Keine Kurse gefunden.</p>;", testExample:"await page.getByLabel('Kurse suchen').fill('Java');\nawait expect(page.getByRole('heading', { name: 'JavaScript' })).toBeVisible();", testMarker:"getByRole|getByLabel|expect\\(", capstoneMarker:"filter\\(|getByRole", criteria:["Seite funktioniert ohne Maus.","Überschriften und Formulare sind semantisch.","Layout bleibt auf schmalem Bildschirm nutzbar.","Playwright testet Suche und leeren Zustand."] },
  backend: { language:"javascript", framework:"Fastify, PostgreSQL, Zod und OpenAPI", frameworkWhy:"Fastify bietet schlanke HTTP-Routen. Zod validiert Eingaben zur Laufzeit; PostgreSQL speichert konsistente Daten. OpenAPI dokumentiert den Vertrag. Authentifizierung und Autorisierung sind unterschiedliche Prüfungen.", workshopMarker:"fastify\.get", frameworkExample:"fastify.get('/courses/:id', async (request, reply) => {\n  const id = Number(request.params.id);\n  if (!Number.isInteger(id)) return reply.code(400).send({ error: 'invalid_id' });\n  return repository.findCourse(id);\n});", project:"Kurs-API", projectBrief:"Baue eine API mit Kursliste, Detailansicht und Lernfortschritt, inklusive Validierung, Datenbank und Rechteprüfung.", capstoneExample:"const result = await db.query('SELECT id, title FROM courses WHERE id = $1', [courseId]);\nif (!result.rowCount) return reply.code(404).send({ error: 'not_found' });", testExample:"await app.inject({ method: 'GET', url: '/courses/invalid' }).then(r => assert.equal(r.statusCode, 400));", testMarker:"inject\\(|assert\\.", capstoneMarker:"db\\.query|reply\\.code", criteria:["Ungültige IDs liefern 400.","Fremde Lernfortschritte sind nicht lesbar.","SQL ist parametrisiert und Änderungen transaktional.","OpenAPI beschreibt Erfolg und Fehler."] },
  security: { language:"javascript", framework:"OWASP ASVS, ZAP und Semgrep", frameworkWhy:"ASVS macht Sicherheitsanforderungen prüfbar. ZAP testet erreichbare Webanwendungen, Semgrep sucht ausgewählte Code-Muster. Keines der Werkzeuge beweist Sicherheit; Ergebnisse brauchen fachliche Prüfung und Freigabe.", workshopMarker:"db\\.query", frameworkExample:"// unsicher: query + userInput\n// sicher: db.query('SELECT id FROM users WHERE id = $1', [userId]);", project:"Bedrohungsmodell und sichere Lernplattform", projectBrief:"Untersuche Login, Kurs-API und Upload. Erstelle Bedrohungsmodell, sichere Änderungen und nachvollziehbare Prüffälle.", capstoneExample:"const safeOutput = element.textContent;\nconst query = 'SELECT id FROM courses WHERE slug = $1';\n// Eingaben bleiben Daten, niemals SQL- oder HTML-Code", testExample:"assert.equal(response.statusCode, 401);\nassert.equal(await canReadCourse(otherUser, privateCourse), false);", testMarker:"401|assert|canRead", capstoneMarker:"textContent|\\$1|safeOutput", criteria:["Datenfluss und Angriffsfläche sind dokumentiert.","XSS und SQL-Injection werden je konkret verhindert.","Zugriff wird serverseitig geprüft.","Automatischer Scan und seine Grenzen sind notiert."] },
  ai: { language:"python", framework:"scikit-learn, PyTorch, pandas, SQLAlchemy und FastAPI", frameworkWhy:"pandas verarbeitet Tabellen, scikit-learn bietet klassische ML-Pipelines, PyTorch trainiert neuronale Netze, SQLAlchemy bindet SQL-Daten an Python und FastAPI stellt geprüfte Modelle als API bereit. Starte mit einem einfachen Baseline-Modell, bevor du größere Netze einsetzt.", workshopMarker:"make_pipeline", frameworkExample:"from sklearn.pipeline import make_pipeline\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression\nmodel = make_pipeline(TfidfVectorizer(), LogisticRegression())", project:"Transparenter Feedback-Klassifikator", projectBrief:"Erstelle einen nachvollziehbaren Klassifikator für anonymisierte Rückmeldungen: Daten rechtmäßig sammeln, per SQL ablegen, in Python prüfen, Baseline und Modell trainieren, Fehler auswerten und als API bereitstellen.", capstoneExample:"model.fit(train_texts, train_labels)\npredictions = model.predict(test_texts)\nprint(classification_report(test_labels, predictions))", testExample:"assert len(train_texts) > 0\nassert set(train_labels) <= {'positiv', 'neutral', 'kritisch'}\nassert model.score(test_texts, test_labels) >= baseline_score", testMarker:"assert|classification_report|pytest", capstoneMarker:"model\\.fit|predict|classification_report", criteria:["Datenquelle, Lizenz, Zweck und Löschweg sind dokumentiert.","Daten werden bereinigt und ohne Leckage in Train/Validierung/Test geteilt.","Baseline, Modell und Fehlermetriken werden verglichen.","SQL-Abfragen sind parametrisiert und personenbezogene Felder minimiert.","FastAPI prüft Eingaben und liefert überwachte, dokumentierte Antworten."] },
  "game-development": { language:"csharp", framework:"Godot, Unity und NUnit", frameworkWhy:"Godot eignet sich für 2D- und 3D-Prototypen und nutzt GDScript oder C#. Unity verwendet C# und ein großes Asset-Ökosystem. Wähle eine Engine nach Zielplattform; teste Spielregeln außerhalb der Szene.", workshopMarker:"CollectCoin", frameworkExample:"public void CollectCoin() {\n  score += 1;\n  coin.Visible = false;\n}", project:"Kleines Sammelspiel", projectBrief:"Entwickle einen spielbaren Level mit Bewegung, Kollision, Punktestand, Pause, Neustart und gespeichertem Bestwert.", capstoneExample:"static int AddScore(int score, int points) => score + Math.Max(0, points);\nstatic bool HasWon(int score, int target) => score >= target;", testExample:"Assert.That(AddScore(4, 1), Is.EqualTo(5));\nAssert.That(HasWon(5, 5), Is.True);", testMarker:"Assert\\.|TestCase", capstoneMarker:"AddScore|HasWon", criteria:["Spiel läuft mit Tastatur und klarer Rückmeldung.","Pause und Neustart setzen den Zustand korrekt.","Punktestand wird nur einmal pro Objekt erhöht.","NUnit prüft Siegbedingung und Grenzfälle."] },
  career: { language:"plaintext", framework:"GitHub, Pull Requests, CI und README", frameworkWhy:"Git hält nachvollziehbare Historie fest. Pull Requests bündeln Review und Diskussion; CI führt Prüfungen reproduzierbar aus. Das Portfolio muss erklären, was du selbst beigetragen hast und wie man das Projekt startet.", workshopMarker:"Problem", frameworkExample:"Problem → kleinste nutzbare Lösung → Tests → Review → Release", project:"Vorzeigbares Portfolio-Projekt", projectBrief:"Wähle ein echtes kleines Problem, plane eine erste nutzbare Version, entwickle sie in überprüfbaren Schritten und veröffentliche eine ehrliche Projektbeschreibung.", capstoneExample:"Zielgruppe: Lernende\nProblem: Lernzeit bleibt unsichtbar\nVersion 1: Minuten erfassen und Wochenübersicht zeigen\nNachweis: 3 Tests + Startanleitung", testExample:"Release-Check: Startbar? Tests grün? Lizenz klar? Secrets entfernt? Grenzen dokumentiert?", testMarker:"Tests|README|Lizenz", capstoneMarker:"Zielgruppe:|Problem:|Version 1:", criteria:["Nutzerproblem und Umfang sind klar.","Mindestens eine lauffähige Kernfunktion ist fertig.","Tests und README ermöglichen die Prüfung.","Eigener Beitrag, Grenzen und nächste Schritte sind ehrlich dokumentiert."] },
};

const aiEngineering: LessonBlueprint[] = [
  lesson("python-bridge", "04 · Python als Werkzeug", "Warum Python für KI?", "python", "Du kannst erklären, warum Python für Datenarbeit und viele KI-Werkzeuge genutzt wird.", "Python ist keine KI. Es ist eine Programmiersprache mit gut nutzbaren Bibliotheken für Daten und Modelle. Erst wenn Variablen, Listen, Dictionaries, Funktionen und Schleifen verständlich sind, helfen Bibliotheken wie pandas und scikit-learn. Du kannst mit kleinen Beispielen beginnen; du musst nicht zuerst eine riesige KI bauen.", [example("Python berechnet eine Kennzahl", "scores = [1, 0, 1, 1]\naccuracy = sum(scores) / len(scores)\nprint(accuracy)", "Die Bibliothek übernimmt hier noch nichts: Python rechnet den Anteil richtiger Antworten aus."), example("Datenstruktur", "row = {'text': 'Paket da', 'label': 'positiv'}\nprint(row['label'])", "Ein Dictionary kann ein Beispiel mit Eingabe und Zielwert darstellen.")], "scores = [1, 0, 1, 1]\n", "Erkläre im Code, was Liste, sum, len und Division zur Berechnung der Genauigkeit beitragen.", "sum\\(|len\\("),
  lesson("python-environment", "04 · Python als Werkzeug", "Projektumgebung und Pakete", "python", "Du richtest eine getrennte Python-Umgebung ein und hältst Abhängigkeiten nachvollziehbar fest.", "Eine virtuelle Umgebung trennt Pakete eines Projekts von anderen Python-Projekten. Installiere Pakete nur aus nachvollziehbaren Quellen und notiere verwendete Versionen. Für reproduzierbare Arbeit speicherst du Datenaufbereitung, Trainingscode und Konfiguration getrennt. Ändere nicht einfach globale Python-Installationen.", [example("Virtuelle Umgebung", "python -m venv .venv\n# Windows: .venv\\Scripts\\Activate.ps1\n# macOS/Linux: source .venv/bin/activate", "Die Aktivierung unterscheidet sich je nach Betriebssystem und Shell."), example("Pakete festhalten", "python -m pip install pandas scikit-learn\npython -m pip freeze > requirements.txt", "Eine Liste macht die Umgebung nachvollziehbarer; sie garantiert nicht, dass beliebige Pakete sicher sind.")], "python -m venv .venv\n", "Schreibe die Befehle für eine virtuelle Umgebung auf und nenne zwei Informationen, die du für eine reproduzierbare Auswertung festhältst.", "requirements|venv|Version"),
  lesson("dataframe", "05 · Daten sammeln und aufbereiten", "Daten mit pandas prüfen", "python", "Du lädst tabellarische Daten, findest fehlende Werte und prüfst ihre Verteilung.", "pandas stellt tabellarische Daten als DataFrame bereit. Vor dem Training prüfst du Spalten, Datentypen, fehlende Werte, doppelte Zeilen und Label-Verteilung. Bereinige nachvollziehbar und sichere die Rohdaten unverändert. Zufällige Beispiele durchzusehen hilft, kaputte Labels und unerwartete Inhalte zu entdecken.", [example("CSV inspizieren", "import pandas as pd\ndf = pd.read_csv('feedback.csv')\nprint(df.shape)\nprint(df.isna().sum())\nprint(df['label'].value_counts())", "Erst prüfen, wie viele Zeilen und fehlende Werte es gibt."), example("Dubletten prüfen", "duplicates = df.duplicated(subset=['text']).sum()\nprint('Doppelte Texte:', duplicates)", "Dubletten zwischen Train und Test können die Bewertung verfälschen.")], "import pandas as pd\ndf = pd.read_csv('feedback.csv')\n", "Ergänze Prüfungen für fehlende Werte und Label-Anteile, bevor ein Modell trainiert wird.", "isna\\(\\)|value_counts\\("),
  lesson("collect-label", "05 · Daten sammeln und aufbereiten", "Datenquellen, Labels und Datenqualität", "plaintext", "Du sammelst Beispiele rechtmäßig und entwickelst nachvollziehbare Label-Regeln.", "Daten kommen aus eigenen Erhebungen, offenen Datensätzen oder erlaubten Exporten. Prüfe Lizenz, Herkunft, Zweck und mögliche Personenbezüge, bevor du sie einliest. Ein Label ist eine Zielantwort, die nach klaren Regeln vergeben wird. Zwei Personen können Beispiele unabhängig labeln und Uneinigkeiten klären. Halte Änderungen und Löschwege fest.", [example("Label-Regel", "kritisch: enthält konkrete Beschwerde\nneutral: reine Information\nunklar: manuelle Prüfung statt geratenem Label", "Grenzfälle brauchen eine dokumentierte Regel."), example("Datenprotokoll", "Quelle · Lizenz · Erhebungsdatum · Felder · Bereinigung · Löschweg", "Provenienz hilft, Ergebnisse später einzuordnen.")], "Quelle: ____\nLizenz/Zweck: ____\nLabel-Regel: ____\n", "Beschreibe für den Feedback-Klassifikator Quelle, erlaubte Nutzung, Label-Regel und Umgang mit unklaren Beispielen.", "Quelle:|Lizenz|Label-Regel|unklar"),
  lesson("sklearn-model", "06 · Erste Modelle mit scikit-learn", "Ein Textmodell als verständliche Baseline", "python", "Du trainierst einen kleinen Klassifikator und verstehst, welche Schritte die Pipeline ausführt.", "scikit-learn verbindet Vektorisierung und Modell in einer Pipeline. TF-IDF wandelt Texte in gewichtete Zahlenmerkmale um; LogisticRegression lernt eine Klassengrenze. `fit` lernt nur aus Trainingsdaten, `predict` wendet das Modell auf neue Texte an. Teile Daten zuerst in Train und Test, damit du keine Trainingsleistung als echte Qualität ausgibst.", [example("Durchgängiger Minimalablauf", "from sklearn.model_selection import train_test_split\nfrom sklearn.pipeline import make_pipeline\nfrom sklearn.feature_extraction.text import TfidfVectorizer\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import classification_report\n\ntexts = ['Sehr hilfreich', 'Danke für die gute Erklärung', 'Das hat mir geholfen', 'Funktion fehlt', 'Leider nicht korrekt', 'Die Aufgabe ist unklar']\nlabels = ['positiv', 'positiv', 'positiv', 'kritisch', 'kritisch', 'kritisch']\nX_train, X_test, y_train, y_test = train_test_split(texts, labels, test_size=0.33, random_state=42, stratify=labels)\nmodel = make_pipeline(TfidfVectorizer(), LogisticRegression(max_iter=1000))\nmodel.fit(X_train, y_train)\npredictions = model.predict(X_test)\nprint(classification_report(y_test, predictions, zero_division=0))", "Jede Variable hat eine Aufgabe: X sind Eingaben, y sind Labels, Pipeline kapselt Umwandlung und Modell."), example("Neue Eingabe", "model.predict(['Die Rückmeldung war hilfreich.'])", "Eine Vorhersage ist keine sichere Wahrheit; prüfe Fehlklassifikationen.")], "# Importiere und trainiere eine Pipeline\n", "Ergänze den Ablauf mit einem eigenen Beispiel und erkläre, warum die Testdaten nicht an `fit` übergeben werden.", "model\\.fit\\(|train_test_split"),
  lesson("sklearn-evaluate", "06 · Erste Modelle mit scikit-learn", "Fehler untersuchen und Modelle vergleichen", "python", "Du vergleichst Baseline und Modell und untersuchst konkrete falsche Vorhersagen.", "Ein einzelner Score reicht selten. Vergleiche das Modell mit einer einfachen Baseline. Nutze Confusion Matrix und Precision/Recall passend zu den Fehlerfolgen. Prüfe eine Liste falsch klassifizierter Beispiele. Ändere nach jeder Entscheidung nur einen Schritt und nutze Testdaten nicht wiederholt zum Tuning.", [example("Metriken", "from sklearn.metrics import classification_report, ConfusionMatrixDisplay\nprint(classification_report(y_test, predictions))", "Der Bericht zeigt Precision, Recall und F1 pro Klasse."), example("Fehlerliste", "for text, expected, predicted in zip(X_test, y_test, predictions):\n    if expected != predicted:\n        print(expected, '→', predicted, text)", "Einzelne Fehler zeigen fehlende Daten, uneindeutige Regeln oder systematische Muster.")], "# Vergleiche die Vorhersage mit dem echten Label\n", "Ergänze einen Bericht und nenne eine Fehlentscheidung, die für deine Anwendung besonders teuer wäre.", "classification_report|ConfusionMatrix|expected != predicted"),
  lesson("sql-ai-data", "07 · KI mit SQL-Daten", "Trainingsdaten mit SQL abfragen", "sql", "Du verwaltest Trainingsdaten strukturiert und holst nur benötigte Felder sicher ab.", "SQL speichert Beziehungen und erlaubt gezielte Auswahl, Bereinigung und Aggregation. Ein Datensatz kann etwa Text, Label, Quelle, Erstellungszeit und Freigabestatus enthalten. Verwende Constraints gegen ungültige Labels, Rechte mit kleinstmöglichem Umfang und gebundene Parameter. Ziehe Daten mit dokumentierter Abfrage in Python; kopiere keine private Datenbank ungeprüft in einen externen KI-Dienst.", [example("Tabelle mit Regeln", "CREATE TABLE feedback (\n  id INTEGER PRIMARY KEY,\n  text TEXT NOT NULL,\n  label TEXT NOT NULL CHECK (label IN ('positiv', 'neutral', 'kritisch')),\n  approved_for_training BOOLEAN NOT NULL DEFAULT FALSE\n);", "NOT NULL und CHECK verhindern einen Teil ungültiger Einträge."), example("Nur freigegebene Beispiele", "SELECT text, label\nFROM feedback\nWHERE approved_for_training = TRUE\n  AND text IS NOT NULL;", "Abfrage und Freigaberegel dokumentieren, bevor Daten ins Training gehen.")], "SELECT text, label\nFROM feedback\nWHERE approved_for_training = TRUE;\n", "Ergänze eine Abfrage, die nur freigegebene, nichtleere Beispiele einer Klasse liest und eine gebundene ID verwendet.", "WHERE|\\$1|approved_for_training"),
  lesson("sql-python", "07 · KI mit SQL-Daten", "SQL-Abfragen aus Python nutzen", "python", "Du verbindest ein Modellprojekt mit einer Datenbank, ohne SQL-Eingaben zusammenzukleben.", "Python-Datenpipelines laden Datensätze häufig aus PostgreSQL oder SQLite. SQLAlchemy stellt eine Verbindung und Transaktionen bereit. Parameter werden als Werte gebunden; sie dürfen nicht per Stringverkettung in SQL eingesetzt werden. Lade nur erlaubte Spalten, protokolliere keine sensiblen Texte und halte Modellversion sowie Datenstand getrennt fest.", [example("Sichere Parameter", "from sqlalchemy import text\nquery = text('SELECT text, label FROM feedback WHERE dataset_id = :dataset_id')\nrows = connection.execute(query, {'dataset_id': selected_id})", "Der Wert bleibt vom SQL-Befehl getrennt."), example("Saubere Pipelinegrenze", "Datenbank → freigegebene Stichprobe → Bereinigung → Split → Training", "Dokumentiere Zeilenzahl, Zeitraum und Hash des Datenexports.")], "# Lade freigegebene Daten mit gebundenem Parameter\n", "Schreibe eine SQLAlchemy-Abfrage mit benanntem Parameter und beschreibe, welche Metadaten du für Reproduzierbarkeit speicherst.", "execute|:\\w+|dataset_id"),
  lesson("pytorch-neural-network", "08 · Neuronale Netze mit PyTorch", "Ein kleines neuronales Netz trainieren", "python", "Du kannst Tensoren, Modell, Verlustfunktion, Optimierer und Trainingsschritt einordnen.", "PyTorch verwendet Tensoren für Zahlen, `nn.Module` für Modellbausteine und Autograd für Ableitungen. Der Trainingsloop setzt Gradienten zurück, berechnet Vorhersagen, Verlust und Gradienten und aktualisiert Parameter. Beginne mit einem kleinen Datensatz und Modell. Eine GPU ist für ein Mini-Beispiel nicht nötig; große Netze brauchen dagegen erhebliche Daten und Rechenleistung.", [example("Kleiner Trainingskern", "import torch\nfrom torch import nn\n\ntorch.manual_seed(1)\nfeatures = torch.tensor([[0.0], [1.0], [2.0], [3.0]])\nlabels = torch.tensor([0, 0, 1, 1])\nmodel = nn.Sequential(nn.Linear(1, 8), nn.ReLU(), nn.Linear(8, 2))\noptimizer = torch.optim.Adam(model.parameters(), lr=0.01)\nloss_fn = nn.CrossEntropyLoss()\n\nfor _ in range(100):\n    optimizer.zero_grad()\n    logits = model(features)\n    loss = loss_fn(logits, labels)\n    loss.backward()\n    optimizer.step()\n\nmodel.eval()\nwith torch.no_grad():\n    print(model(features).argmax(dim=1))", "features enthalten Zahlenmerkmale, labels die Zielklassen; logits sind noch keine bestätigte Antwort."), example("Reihenfolge merken", "Vorhersage → Verlust berechnen → Gradienten zurücksetzen/berechnen → Parameter aktualisieren", "Ein Trainingsschritt wiederholt diese Folge mit Trainingsbeispielen.")], "# Baue Modell, Verlust und Optimierer\n", "Ordne im Code `forward`, Verlust, `backward` und `step` ein und erkläre, was sich nach einem Trainingsschritt verändert.", "loss\\.backward|optimizer\\.step|nn\\.Linear"),
  lesson("pytorch-loop", "08 · Neuronale Netze mit PyTorch", "Trainingsloop, Overfitting und Speichern", "python", "Du trainierst über Batches, misst getrennt und speicherst Gewichte nachvollziehbar.", "Ein Dataset und DataLoader teilen Beispiele in Batches. Nach jeder Epoche misst du Leistung auf Validierungsdaten im Evaluationsmodus. Sinkender Trainingsverlust bei schlechterer Validierungsleistung deutet auf Overfitting. Speichere Modellgewichte, Architektur, Vorverarbeitung, Zufallsseed und verwendete Bibliotheksversionen zusammen.", [example("Epoche in Grundzügen", "for batch_x, batch_y in train_loader:\n    optimizer.zero_grad()\n    loss = loss_fn(model(batch_x), batch_y)\n    loss.backward()\n    optimizer.step()\n\nmodel.eval()\nwith torch.no_grad():\n    validation_logits = model(validation_x)", "Validierungsdaten werden nicht für Gradientenupdates verwendet."), example("Gewichte speichern", "torch.save(model.state_dict(), 'model.pt')", "Zum Wiederverwenden brauchst du auch Architektur und Vorverarbeitung.")], "# Trainiere über mehrere Batches und prüfe Validierung\n", "Ergänze einen Trainingsloop, der Trainings- und Validierungsschritt trennt und Gewichte speichert.", "train_loader|model\\.eval|state_dict"),
  lesson("pretrained-models", "09 · Generative Modelle und Nutzung", "Vortrainierte Modelle und Transformers", "python", "Du unterscheidest ein vortrainiertes Modell verwenden, feinabstimmen und von Grund auf trainieren.", "Transformers lernen in einer Vortrainingsphase allgemeine Muster aus sehr großen Datenmengen. In einem eigenen Projekt verwendest du meist ein vorhandenes, erlaubtes Modell, formulierst eine Aufgabe und testest es. Feinabstimmung verändert Gewichte mit zusätzlichen Beispielen. Ein Modell von Grund auf zu trainieren erfordert enorme Daten, Fachwissen und Rechenressourcen; ein kleines Kursprojekt ist kein ChatGPT-Nachbau.", [example("Modellkarte prüfen", "Modellname → Lizenz → Trainingshinweise → Eingabebegrenzung → bekannte Risiken", "Eine verfügbare Datei bedeutet nicht automatisch, dass jede Nutzung erlaubt ist."), example("Transformers Pipeline", "from transformers import pipeline\nclassifier = pipeline('text-classification', model='REPLACE_WITH_REVIEWED_MODEL')\nprint(classifier('Beispieltext'))", "Prüfe Modelllizenz, Sicherheitsrisiken und Version, bevor du Gewichte lädst.")], "# Prüfe die Modellkarte und dokumentiere deine Auswahl\n", "Erkläre, wann du ein bestehendes Modell nutzt, wann Fine-Tuning hilft und warum ein Modelltraining von Grund auf eine andere Größenordnung hat.", "transformers|Lizenz|Fine-Tuning"),
  lesson("ai-capstone-pipeline", "13 · Großes Abschlussprojekt", "Abschlussprojekt: eigene Daten bis zum geprüften Modell", "python", "Du planst eine vollständige, reproduzierbare und verantwortungsvolle Modellpipeline.", "Baue einen kleinen Klassifikator, dessen Entscheidung nachvollziehbar und begrenzt ist. Sammle oder wähle nur rechtmäßig nutzbare Daten, dokumentiere Quelle und Labelregeln, speichere freigegebene Datensätze in SQL, bereinige sie in Python, vergleiche Baseline und scikit-learn-Modell, untersuche Fehler und stelle eine geprüfte Vorhersagefunktion bereit. PyTorch ist eine Erweiterung, nicht automatisch die bessere erste Lösung.", [example("Projektkette", "Quelle/Lizenz → SQL-Import → Datenprüfung → Python-Aufbereitung → Train/Test-Split → Baseline → Modell → Fehleranalyse → API", "Jeder Übergang erhält eine dokumentierte Prüfung."), example("Vorhersage mit Grenzen", "def predict_feedback(text):\n    if not text.strip():\n        raise ValueError('Text fehlt')\n    label = model.predict([text])[0]\n    return {'label': label, 'model_version': MODEL_VERSION}", "Eine reale Anwendung braucht zusätzlich Authentifizierung, Limits, Logs ohne sensible Texte und einen Rückfallweg.")], "# Beschreibe Ziel, Datenquelle und Testaufteilung\n", "Lege die Daten- und Modellpipeline an. Zeige eine Baseline, einen geprüften Testdatensatz, Fehleranalyse, Datenbankabfrage und eine sichere Schnittstelle; schreibe zusätzlich eine Grenze des Modells auf.", "(?=[\\s\\S]*train_test_split)(?=[\\s\\S]*model\\.fit)(?=[\\s\\S]*classification_report)", "Das Projekt ist abgeschlossen, wenn du jeden Schritt erklären und die Grenzen deiner Messung benennen kannst.", ["1. Definiere Problem, Zielgruppe, Fehlerfolgen und Erfolgskriterien.", "2. Prüfe Herkunft, Lizenz, sensible Felder und Löschweg der Daten.", "3. Lege SQL-Schema und gebundene Abfragen an; dokumentiere Stichprobe und Labels.", "4. Bereinige Daten in Python und trenne Training, Validierung und Test ohne Leckage.", "5. Vergleiche Majority-Baseline, scikit-learn-Pipeline und bei Bedarf ein kleines PyTorch-Modell.", "6. Untersuche Fehlklassifikationen, dokumentiere Metriken und veröffentliche eine begrenzte API.", "7. Prüfe Eingaben, Rechte, Kosten, Datenschutz, Modellversion und Rollback."] , ["Datenquelle und Nutzungsrecht sind nachvollziehbar.","SQL speichert Label und Freigabestatus mit Constraints.","Baseline und ML-Modell werden am selben zurückgehaltenen Testset verglichen.","Falsche Vorhersagen werden einzeln analysiert.","API validiert Eingaben und nennt Modellversion.","README beschreibt Start, Grenzen, Datenschutz und bekannte Fehler."]),
];

